/* 平成14年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h14.committeeSessions.push(...[{"id":"h14-20020304-8","meetingId":"h14-cm03","date":"2002年3月4日","dateIso":"2002-03-04","committee":"建設委員会","time":"午前１０時０８分～午後３時０２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"１件、１件了解が得られたらというその話の中身というのは、管財人が入って仕組みができたらということなんですか。そこのところをもう少し詳しく。","respondent":"北村下水道河川課長","answer":"会社更生法の適用ということで、管財人のところに全部の権限が集約されて、既存の執行体制は一回解散ということになります。管財人のほうで審査して、では、この現場は始めていいですよということになれば再開できるというようなことだと聞いています。","id":"exchange-001"}]},{"id":"topic-02","title":"の１、議案審査に移らせていただきます。 (1)、第２７号議案、品川区みどりの条例の一部を改正する条例","agenda":"の１、議案審査に移らせていただきます。 (1)、第２７号議案、品川区みどりの条例の一部を改正する条例","exchanges":[{"speaker":"上山委員","kind":"質問","question":"最初にちょっと基本的なことをお尋ねしたいんですが、そこら辺の係わりはどうなっているのか、ちょっとお尋ねしたい。全体的なこの計画の目標というんですか、この２点をお尋ねしたいんですが、いかがか尋ねました。","respondent":"松代道路公園課長","answer":"２点目の目標ですが、平成６年にみどりの条例というものをつくりまして、接道部緑化等を進めてまいりました。今後、その辺のところもよく見極めながら、今後の目標値を定めてまいりたいと考えているところです。","id":"exchange-002"},{"speaker":"上山委員","kind":"質問","question":"集中豪雨もそういうのに影響されているんじゃないかと言われている中ですから、いろいろな意味でも、効果が期待できるんじゃないかと思っています。ちょっと説明を求めました。","respondent":"田平建築課長","answer":"一例を申し上げますと、条例で義務づけられます屋上面積の２０％を緑化した場合を想定します。日影規制なしという地域地区で考えた場合、既存の指定容積率４００％の場合は、１３％が屋上緑化によって上乗せされる。","id":"exchange-003"},{"speaker":"上山委員","kind":"質問・要望","question":"最後に要望なんですけれども、年間１０件ということで、計算すると３００万円ぐらいだと思うんです。それから件数も含めて、ぜひ検討などをしていただければと、これは要望だけにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"築舘委員","kind":"質問","question":"砂が飛ぶとか、そういういろいろな条件も、ある意味で悪いところがあると思うんです。その辺の研究といいますか、説明を求めました。","respondent":"松代道路公園課長","answer":"そういった意味では、積極的にそれらのものを参考にしたいと思ってありますが、さらに１年過ぎた中で技術が進歩しています。非常にその辺が厳しいと思うんですが、その範囲の中で、できる限り参考にしていただけるようなものをつくっていきたいと考えているところです。","id":"exchange-005"},{"speaker":"沢田委員","kind":"提案","question":"今のに関連するんですけれども、どういう植物を植栽するか。私も提案したし、実際にはどの程度の効果があるのか、何かデータみたいなものがあったら教えてもらえないか尋ねました。","respondent":"松代道路公園課長","answer":"その辺のところが非常に難しいと思うんですが、その場合は、施工上でどうなのか。二酸化炭素の抑制、景観形成、こういったものが効果として挙げられているものです。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"非常に期待は大きいんですけれども、大きい割には、３０万円というのはどの程度なのかというのがよくわからない。３０万円固定というのが、マンションでもとなるとどうなのかなというのがあるんで、そこら辺をもう少し教えてもらえますか。","respondent":"松代道路公園課長","answer":"庁内に検討委員会を立ち上げまして、関係する１０課の課長方を中心にしまして、いろいろと検討しました。今後は、そういったものをよく見極めながら対応してまいりたいと考えているところです。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"３０万円で半分だとすると、６０万円で大体いくのか、いかないのかというあたりがもう一つ見えてこないんです。区が率先してやると同時に、ご指導をいただきたいと思うんですけれども、そこら辺はいかがか尋ねました。","respondent":"松代道路公園課長","answer":"加えて、そこの屋上にもぜひお願いしたいということは当然なことでして、指導できる立場、もしくはお願いする立場でやっていきたい。幼稚園も含めて、そういう機会等がありますれば、準じて、ぜひお願いをしていきたいと考えているところです。","id":"exchange-008"},{"speaker":"本間委員","kind":"質問","question":"壁面というのはちょっとイメージがよくわからないんですけれども、どういうことを想定して、助成になるのか。すみませんが、現段階で、一つ、二つ具体的な例を説明するよう求めました。","respondent":"松代道路公園課長","answer":"まさに輻射熱等を下げて全体のビルの温度を下げるといった効果等を生み出していくものですので、そういった緑をぜひお願いをしたいと考えています。","id":"exchange-009"},{"speaker":"本間委員","kind":"質問","question":"特に私どもは４階建ての４階でしたから、それこそバケツに一杯ぐらいの水がたまりまして、大変な被害を受けたことがあります。しょっちゅうそういうことがありますものですから、この辺の限界については、どういうふうにお考えか尋ねました。","respondent":"松代道路公園課長","answer":"かつ、ずっと継続した緑の状態が保てないということがありますので、緑を維持する方法が一番よかろうということで考えてあります。それもパレット式になっていまして、そういったものをご提案をしながら、さらに更新を続けてご提案をしていこうかと考えているところです。","id":"exchange-010"},{"speaker":"辻委員","kind":"質問・要望","question":"ちょっと確認させていただきたいんですが、新たに１,０００m2以上のものは、それをつくる際に義務づけが始まったと考えていいんですか。それから、１,０００m2以上の建築行為というのは、年間、大体どのぐらいあるんか尋ねました。","respondent":"松代道路公園課長、田平建築課長","answer":"２点目のご質問は、平成１２年度に１,０００m2以上の区に提出された建築計画ですけれども、私どもで調べた範囲では、一応３０件です。屋上設置が可能、屋上緑化をした場合はどの程度というものをある程度想定しまして… 具体的には指導を受けてくると、そういうふうに窓口で周知をし、周知および確認申請の事前相談という部分でやりたいと考えております。","id":"exchange-011"},{"speaker":"辻委員","kind":"確認","question":"４月２９日あたりに広場でやるんじゃないですか、植木を。その辺、どう今後やられるように考えているんか尋ねました。","respondent":"松代道路公園課長","answer":"そういった方にも対応できるようなものを、先ほど言いましたような形で提案をしていければと思っています。最悪、どうしてもだめな場合は、地上部分をもうちょっと広げていただいくというお願いをできればと考えているところです。","id":"exchange-012"},{"speaker":"辻委員","kind":"質問","question":"そういったときに、２割をどう確保するかといったら、私道部とか、壁面とかという形で確保していく必要が絶対にあると思うんです。最後に、要綱等ができましたら、またぜひ、教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"横山副委員長","kind":"質問・要望","question":"そうすると、それはやっぱり壁面で求めるのかと思ったら、地上面でというようなお話があったから、それはそれでいいんですけど。維持費がかかっていくわけですから、周知をしていただければと、このように思っています。","respondent":"松代道路公園課長","answer":"まず第一に、できれば１０月１日の施行の前に、総合庁舎の屋上を少しでも早くごらんいただけるように取りかかってみたいと思っています。こういった形になりますというようなものを、幾つかのパターンも含めて、正直に区民の方にご提案していきたいと考えているところです。","id":"exchange-014"}]},{"id":"topic-03","title":"議案審査(2)、第２８号議案、品川区手数料条例の一部を改正する条例","agenda":"議案審査(2)、第２８号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"それと、４番なんですが、ちょっと高いかなという気がするんですけど。真ん中を通して道路にするということなんですが、さっきのあれじゃないんですけれども、平成１２年度でどれぐらい件数があったのかとの意見を述べました。","respondent":"田平建築課長","answer":"４番についてですか。","id":"exchange-015"},{"speaker":"沢田委員","kind":"質問","question":"４番について、適用件数というんですか、実態がどれぐらいなのか教えてもらいたい。","respondent":"田平建築課長","answer":"４番の建ぺい率の許可制度は、若干説明申しましたが、条件があります。ちなみに、東京都２３区は、３万３,０００円に統一しております。","id":"exchange-016"},{"speaker":"上山委員","kind":"質問・要望","question":"その辺もあわせて、よくやってもらいたいというのが１点で、これは要望です。ほかにもしあるのかどうか、ちょっと確認したかったんで、そこら辺をちょっとお願いします。","respondent":"中村交通安全担当課長","answer":"これは、今後、管理は区のほうになる予定になっていますけれども、そういう意味では、鉄道事業者にご協力をいただいているということです。当区内については、今後、鉄道事業者の協力はいただいているんじゃないかと考えています。","id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"あそこには、駐輪場の計画がなかったんですか。あったら、説明を求めました。","respondent":"中村交通安全担当課長","answer":"具体的にそちらのほうに駐輪場について整備するという予定はございませんけれども、それぞれお願いするという形で進めていきたいと思います。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問・要望","question":"要望だけ。小規模でもいいから、こちら側にもつくることをぜひ検討していただきたいということだけ、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"辻委員","kind":"質問","question":"将来的には最大７３０台まではということがあるんですけど、整理とかそういうのをやっているのか、いないのか。ここの放置自転車の整理というのは、今までどういう形でやられているんか尋ねました。","respondent":"中村交通安全担当課長","answer":"放置禁止区域の指定を行う予定になっていますので、新たに啓発指導員をそちらのほうに投入しまして、新年度からは実施する予定です。今回、その中でこらちのほうについても進めて、駅周辺にとめられないようにということで実施する予定になっております。","id":"exchange-020"},{"speaker":"辻委員","kind":"質問","question":"今度、東急の撤去自転車を置く場所というのは、それはどんな地点になるんですか。東急の高架下か何か使って。","respondent":"中島街路事業担当課長","answer":"７０％なんですけれども、今年の秋ぐらいの段階で、駅舎等が完成する見込みになっております。その中に駐輪場を設置するということで要望していまして、放置自転車については、その奥に一時保管所の設置を予定をしているです。","id":"exchange-021"},{"speaker":"辻委員","kind":"確認","question":"だから、私が言うのは、東急の中で、３９０台がどういう動きをするか一時的にわからないです。いきなり八潮に持っていくか、東急の新しくできたところの利用価値というのも、改めて確認するような方向でできないものだろうかということです。","respondent":"中谷まちづくり事業部長","answer":"今、そのまま設置できないということになってはいけないので、ここで出発せざるを得なかったという実態があります。もし来年に設置いたしますと、２年弱はちょっとご不便をおかけいたしますが、よろしくご理解いただきたいと思います。","id":"exchange-022"},{"speaker":"築舘委員","kind":"質問","question":"だけれども、その場合に、禁止区域とか、警告のビラとか、撤去とか、これは目黒区と協力体制なんですか。費用の面とか、いろいろどういうふうになっているんか尋ねました。","respondent":"中村交通安全担当課長","answer":"それぞれ設置していただくということで、役割分担といいますか、自分の場所について実施するという形でやってあります。目黒区内のものについては目黒区のほうで実施していただく、品川区内については、私どものほうで実施するというような予定になっております。","id":"exchange-023"},{"speaker":"築舘委員","kind":"意見","question":"放置自転車というのが７５０台ぐらいで、昔、もう要らないということで放置した自転車が意外と多いんじゃないかと思うんですね。通学、通勤、買い物とかで、そのまま乗っていくという割合の調査というのは、目黒駅ではわかりますかとの意見を述べました。","respondent":"中村交通安全担当課長","answer":"今のご質問の、それぞれの割合の調査といいますか、こちらについては実施してはございません。ただ、あの駅に置かれている台数等からすれば、かなり通勤、通学等に使われている自転車が多いんじゃないかと考えています。","id":"exchange-024"},{"speaker":"築舘委員","kind":"質問・要望","question":"こういう場合に、禁止区域に置かないで、ちょっと禁止区域じゃないところに置いちゃうというようなケースがやっぱり出てくるんですか。結果的に、正直者はばかを見るというようなことがあるかどうか、その実態を聞かせていただきたい。","respondent":"中村交通安全担当課長","answer":"それと、いつ撤去ということでわかっていれば、皆さんその日には置かないということがあるんじゃないかと思います。前日、撤去を実施したということもやりましたので、やはり皆さんに放置はしていただきたくないということで進めてまいりたいと考えております。","id":"exchange-025"},{"speaker":"上山委員","kind":"質問","question":"健康にもいいと言われていますけれども、そういう意味から、鉄道事業者への要請というのはされているんですか。そこら辺はどんな感じなのか、ちょっと教えていただければありがたいんですが、最後にすみません。","respondent":"中村交通安全担当課長","answer":"駐輪場の設置の協力が求められた場合に、鉄道事業者そのものが駐輪場を設置することまでの義務づけはなされていませんけれども、社会の中では。設置までは向こうでやられたんですけれども、このような運びになったということで、ご理解のほどをよろしくお願いします。","id":"exchange-026"},{"speaker":"沢田委員","kind":"意見","question":"もう一度、全体計画と、現在の進捗状況はどうなのかということをお尋ねしたい。あまりにも工事期間が長いんじゃないかと、いろいろ意見が出ているんですけど、ちょっとそこら辺を説明していただけますかとの意見を述べました。","respondent":"北村下水道河川課長","answer":"それから、とりあえずトンネルの構体ができ上がって初めて使えるということになってまいりますので、平成１４年度末ということになろうかと思います。","id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"今、聞き落としたのかもしれませんが、最終的に供用開始は何年か尋ねました。","respondent":"北村下水道河川課長","answer":"平成１６年度完成予定ですので、平成１７年夏から使えるかと思います。","id":"exchange-028"},{"speaker":"辻委員","kind":"質問","question":"３ページの断面図で見ると、目黒川の水位との落差というんですか、一時的な放流を待つという感じですか。その辺の考えというのはどうなんか尋ねました。","respondent":"北村下水道河川課長","answer":"かむろ坂のほうが地盤的に高いですから、高低差を利用して、仮に目黒川の水位が高くても水は流せるという格好にはなっています。ですから、目黒川の水位が上がってしまうと流せないということではありません。","id":"exchange-029"},{"speaker":"辻委員","kind":"意見","question":"その辺の水というのは、上からカットされるからということもあるわけですけれども、それは今後の課題としてお願いしたいということです。ちょっと、水圧を何とかということをとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"沢田委員","kind":"質問","question":"私の地域で言うと、長者丸のほうにしろ、低層の一種住専はかなりの部分はみんな環状７号線の内側に入っている。まだ基本方針だから、そこまではフレームはつくってないかもしれないんですけれども、そこらがもし示されていたら、教えてもらえますか。","respondent":"伊佐都市計画課長","answer":"この考え方の中に、的確かつ厳格な規制を実施する一方で、例えば用途地域の指定を一斉に上げていくという考え方に立っているものではございません。","id":"exchange-031"},{"speaker":"沢田委員","kind":"意見","question":"まあ、「環状７号線の内側は中高層住宅地、センター・コア再生ゾーンで都心居住を進める地区は中高層住宅地として誘導」と書いてあるんですよね。環状７号線の内側で中低層で暮らしている人、そこの安全をどう確保し、この間も反対させてもらったんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"上山委員","kind":"質問・要望","question":"いろいろあるんでしょうけど、最初にちょっとそういうイメージでいいのかどうか、そこら辺を教えていただけませんか。面積的にどうなのか、ちょっとよくわからないけど、どういう感じになるのか。","respondent":"伊佐都市計画課長","answer":"ご説明いたしましたが、環状６号線の内側が、ここで言うセンター・コア再生ゾーンとなります。東京都全体を視野に入れたときの、広い視点から見たゾーニングがなされているものです。","id":"exchange-033"},{"speaker":"上山委員","kind":"意見","question":"全体をどうするのかは別ですよ、齟齬というか、自己矛盾みたいな感じもしなくはないんです。ちょっと意見だけとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"辻委員","kind":"意見","question":"３ページ目の「安全で健康に暮らせる生活環境の形成」ということで、防火と準防火の間ということでしたが、なぜこういう考え方が出てきたのか。その辺の考え方はとの意見を述べました。","respondent":"伊佐都市計画課長","answer":"これも、ご指摘のとおり、国の法改正が必要になってまいります。この制度が、今後果たして動いてくるかという部分について、今の時点ではちょっと見えてないという状況です。","id":"exchange-035"},{"speaker":"辻委員","kind":"質問","question":"こういう答申が出てきたんでしょうから、防火の面から見れば、鉄筋でかちんとしてやればいいけど。新しい建築技法から言えば、何かの方法もあるとか、その辺も含めて、考えが出ていると思うんです。","respondent":"田平建築課長","answer":"そうなった暁には、そういうことも一つの手法として、東京都の場合には検討していかなくちゃならないかなと思います。そして、住民のご理解をいただく必要があります。","id":"exchange-036"},{"speaker":"辻委員","kind":"質問","question":"密集地域での事業というか、メンテナンスがあるじゃないですか。じゃあどうするかということが起こったときに、そういうものががちんと出てないと、同じことが起こるんじゃないかなと思います。","respondent":"伊佐都市計画課長","answer":"やっぱり面的に建て替えといいますか、細街路なんかも拡幅しつつ進めていく手法として、今回の地区計画の活用という考え方が強く出てきています。これまでの基本方針は、ほとんど用途地域の見直しのための方針であって、注視していきたいと考えております。","id":"exchange-037"},{"speaker":"上山委員","kind":"質問","question":"今回、品川区に便利になったと思うんですが、予定の利用というんですか、こういう道路というのは、一般的にどのぐらい需要があるのか。もしその辺がちょっとあれば、教えていただけたらと思うんですが。","respondent":"伊佐都市計画課長","answer":"今回の臨海工事に環境アセスメントが行われてございまして、臨海トンネル部分での交通量は、１日２４時間で２万９,０００台です。","id":"exchange-038"},{"speaker":"築舘委員","kind":"質問","question":"開通式典につきましては、４月１０日と書いてあるんですけど、これは我々もあれか尋ねました。","respondent":"伊佐都市計画課長","answer":"大変失礼いたしました。４月１０日の開通式の招待状がまいってございまして、区から、区長、助役、正副議長、正副建設委員長を行かせていただきます。","id":"exchange-039"},{"speaker":"辻委員","kind":"質問","question":"あの計画はまだ生きているんですか。やっぱりそれはそれとして、将来計画は持っているんか尋ねました。","respondent":"伊佐都市計画課長","answer":"国道３５７号線の一般道路としての通行につきましては、国土交通省で検討中です。東京都のほうからも、強く働きかけてありますし、これは大変重要な幹線であるとして、整備を進められているということで、検討中ですということです。","id":"exchange-040"},{"speaker":"横山副委員長","kind":"質問","question":"それとも、向こうで、こうすると便利ですから庭先を買ってくださいときているのか。そこら辺のところを、ちょっと説明を求めました。","respondent":"浜脇住環境整備課長","answer":"平成１３年度の１２月にこれが買えたものですから、７０m2の分と一緒に、来年度早々にやるように設計を開始したところです。まちづくり協議会のほうにもご報告をしておりまして、公園なんだけれども、通路のほうで設計をしたいということで考えているところであります。","id":"exchange-041"},{"speaker":"横山副委員長","kind":"意見","question":"そんな形で、上、下、後に出るより、ここに出ることができると、あそこの地域がずっと、防災の意味じゃ優れた場所になりますので、結構だと思います。そして、今言われるように、一緒の工事でやっていかれるということなんで、それも了解しておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"上山委員","kind":"質問","question":"ちょっとお尋ねなんですけど、不動産業者側というんですか、これはいわば負担する形になるんですか。手数料が少なくなるということでよろしいんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"この間、たまたま役員の方とお話をしたんですけど、今でもやっぱり、通常、一般の方が不動産屋に一歩入るのは、相当勇気が要るということだそうです。そういった中で、こういったシールを張って、安心ですよということでのメリットはありますと、協会のほうは考えてくれます。","id":"exchange-043"},{"speaker":"沢田委員","kind":"質問","question":"改正についてというよりも、今までずっと細街路の整備をやってきた実績なんですけれども、大体、延長でどれぐらいになって、それが品川区全体の細街路のどれぐらいを占めるのか、もしわかったら、教えてもらえますか。","respondent":"田平建築課長","answer":"区内の総延長は、まだこの１０倍ほどあります。１００年かかるという話になりますけれども、まちの中を見ますと、相当セットバックした建物が目につくかなと思います。","id":"exchange-044"},{"speaker":"上山委員","kind":"確認","question":"この４６戸というのは、既存の三棟の戸数より増えているのかどうか、そこら辺を確認したかったのが１点です。間取りとの関係で、うまく合っているのかちょっと気になったので、そこら辺をちょっと教えていただけませんか尋ねました。","respondent":"田村住宅課長","answer":"３点ほどのご質問なので、私のほうからお答えします。そういう意味からすれば、戻り入居を考えますと、１ＤＫという形を、区として考えたわけです。","id":"exchange-045"},{"speaker":"上山委員","kind":"質問・要望","question":"は要望にしたいと思うんですが、４戸ぐらい増える形になるかと思うんですが、ないのか。あれば、教えていただきたいと思うのが一つ。","respondent":"田村住宅課長","answer":"建替時移管は２３区で初めての事業になるので、新たに追加で東京都のほうから住宅の移管というお話は、今のところ具体的にはございません。今この事業が動いているので、また何か都から、話は来ると思います。","id":"exchange-046"},{"speaker":"辻委員","kind":"質問","question":"公共の施設を２５０m2で見たときに、約１,０００m2近くあるわけですから、どれぐらいの。事業部なんかで、共通に検討していかないと、事業部でやった意味がないんじゃないかと思いますけど、いかがか尋ねました。","respondent":"田村住宅課長","answer":"図面でご説明しますと、まず２ページの右上、合わせて４７m2ほどあります。建物の６階の屋上そのものは、太陽光熱を一応検討している最中なので、大幅に有効面積の中で取り入れられているです。","id":"exchange-047"},{"speaker":"辻委員","kind":"質問・要望","question":"こちらも、やる以上、新しい建物ですし、区はせっかく取り組むんですから、それなりに最大限、こういう形でやっていくんだと。これは結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"沢田委員","kind":"質問","question":"あるいは、戻り入居の方は１けた台と言いますけど、既存の家賃と荏原市場跡地の家賃と、戻ったときの家賃。今後、屋上緑化を進めていく上での見通しになると思うんで、わかったら教えてもらえますか。","respondent":"田村住宅課長","answer":"それと、結局、今回の建替時移管が法定建替えですので、１０年間の家賃の経過措置があります。ですから、特別平米単価を、屋上緑化分何がしという形で出しているのではなくて、既存の工事費の中で屋上緑化も工夫してやるという考え方です。","id":"exchange-049"},{"speaker":"沢田委員","kind":"質問","question":"実際に同じ面積で移った場合に、やっぱり１割とか２割とか上がるんじゃないかと思うんですけど、その辺の大体の見当があったら教えてほしい。それから、屋上緑化というのはそんなに金がかからないものなんか尋ねました。","respondent":"松代道路公園課長、田村住宅課長","answer":"２万５,０００円ぐらいである程度できるようなものを、今、いろいろご提案をしようかなと思っています。それには前提条件になります、構造に合ったいろいろな防水、灌水が出てきますので、一概には言えないところがあるということは… 家賃の関係ですが、既存の大井伊藤町に住まわれている方を見ますと、やはり、１世帯当たり使用料が１万円から、高い方で２万円ぐらいです。","id":"exchange-050"},{"speaker":"辻委員","kind":"質問","question":"大井伊藤町住宅の都営住宅というのは２ＤＫですか、１ＤＫか尋ねました。","respondent":"田村住宅課長","answer":"現在は、１ＤＫが２３.２４m2で３６戸、３Ｋ、４０.３２m2が６戸、合わせて４２戸です。","id":"exchange-051"},{"speaker":"辻委員","kind":"質問","question":"単身で募集するんですか、それとも所帯で募集するんですか。区民住宅ですから、年齢は関係ないですよね。","respondent":"田村住宅課長","answer":"辻委員からご指摘のとおり、型別供給ということで、実際も間取り等、平米数も東京都とも調整しながらやっております。募集は、具体的にはこれから決めていきますが、１ＤＫ、３５m2前後というのは、１人から２人世帯の募集を考えているところです。","id":"exchange-052"},{"speaker":"辻委員","kind":"質問・要望","question":"では、要望だけ。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"上山委員","kind":"質問・要望","question":"ちょっとお尋ねしたいのは、具体的に例えば家賃とかを含め、どれぐらいに設定されるような考えでいらっしゃるのか。あるいは、どのぐらいの時点で発表するつもりでいらっしゃるのか、その辺をちょっと教えていただきたいと思うんですが。","respondent":"田村住宅課長","answer":"やはり１３２戸の規模がありますので、大体、今年の夏ごろを考えております。４月ぐらいまでには決めないと、検討している最中なので、またお知らせしたいと考えています。","id":"exchange-054"},{"speaker":"沢田委員","kind":"質問","question":"建設委員会で行ったときにちょっと言ったことがあるんですけれども、何であんなになっちゃったんでしょうか。事故が起きる前に、早く改善したほうがいいと思うんです。","respondent":"松代道路公園課長","answer":"ちょっと、今、私、場所が確定できないものですから、すぐに調査をしまして、状況等をお知らせします。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/807981?Template=document&Id=3712#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":65968,"voices":178}},{"id":"h14-20020304-9","meetingId":"h14-cm03","date":"2002年3月4日","dateIso":"2002-03-04","committee":"文教委員会","time":"午前10時08分～午後２時２９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"条例整備は都道府県から当該区市町村ということですけれども、これは今の東京都の条例と全く変わらないということなのか尋ねました。","respondent":"久保田学務課長","answer":"条文の書き方とか、基本的には今まであった条例を継続するという意味合いがありますので、東京都の条例をほぼ参考にしてつくったです。ですから金額等においても変わりはございません。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"もう１件ですけれど、この公務災害の発生件数、最近では１０年間発生したことがなくて、品川区では全くないというのですけれど、例えばどんなことがあったのか尋ねました。","respondent":"久保田学務課長","answer":"このときには林間学校の実施に伴う保健衛生指導のために学校に来たところ、こういうケースがあります。そういうようなところです。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問","question":"こういう決め方というのはどこでどういうふうに決めるんでしょうか。それぞれ学校ごとというか、５８校、そういうのだと思うのですけれども、トータルを薬剤師も教えていただけますか。","respondent":"久保田学務課長","answer":"それから歯科、それから薬剤師ということで、合計５人掛ける５８校です。薬剤師会から推薦をいただきまして、それぞれの学校長のほうと協議しまして、それで決定しているという状況です。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問","question":"今申し上げたように、やめちゃった場合とか、お願いするとかそういうところで探すとかというのは手だてとしてどういうふうな手続きなんですか。どういうふうに学校医さんって決めているんですかと言われて、決め方とか手順とか、もう少し規定とか何かあるのかなと思って。","respondent":"久保田学務課長","answer":"医師会の方でもそういうような確実な人材を用意していただくという意味合いから推薦を受けて決定しているというような状況になってあります。私どもと、それからまた医師会の方と相談して新たな方を何とか探して、それでやっているというのが現状です。","id":"exchange-004"},{"speaker":"桜井委員","kind":"質問","question":"規則みたいなのはないんですか。基準とか規則とか。","respondent":"久保田学務課長","answer":"規則ではないんですけれども、要網的なものは私ども持っております。教育委員会規則で一応そういう任命をすることになっていますので、それを受けて私ども要網的なものは持ってあります。","id":"exchange-005"},{"speaker":"高星委員","kind":"質問・要望","question":"これにかかってくるのは具体的な何かあったときの補償の関係ですから、今の桜井委員との関係でちょっと教えてもらいたいんだけれど。コントロールというか、実態の把握をここはどうなるんだというのだけをちょっとお聞かせいただきたいと思うんですけれど。","respondent":"久保田学務課長","answer":"それは全く学校のほうで独自にやっている、この薬剤師会とは全く違うものです。これは月々それぞれ薬剤師に決まった報酬をお支払いしている状況でお仕事をやっていただいているです。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この条例的にはわかったんですが、この条例が区に変わってきたことによって補償額の財源的なものというのはどこから。どこかの保険か何かに入っている分からこれ補償額が出てくるんか尋ねました。","respondent":"久保田学務課長","answer":"これが市町村になったということで、特別交付税の措置の予定というふうにはなってあります。ただ、そういう関係から言うと、いわゆる財調関係の部分には当然対象にはなるというふうには思っております。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると例えばさっきちょっと出させてもらったんですけれど、保険みたいなものは一切なしの、そっくりこういう案件が起きたときに区の持ち出し、財調の財源かもしれないけれど、区として持ち出してというふうに考えればいいわけか尋ねました。","respondent":"久保田学務課長","answer":"というのは、出たときに、発生したときに一切対処するというような考え方でやっているというふうに聞いております。私ども区としてもそういうような考え方で行きたいというふうに考えております。","id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"先ほどの説明の中で、参考までに伺いたいんですけれども、教職員の方の公務災害の基準などと比べるとどういう割合なのかなと。特に補償基礎額とかこの辺の算定の仕方で何か額とかがあるのかどうかを教えていただきたい。","respondent":"久保田学務課長","answer":"ちょっと比較はできないんですが、基本的に学校の場合の補償の基礎額というのは、国家公務員のいわゆる公務災害補償がありますよね。これは非常に難しい問題でして一概にはお話はなかなか難しいんですけれども、そんな感じで受け取っていただければと思います。","id":"exchange-009"},{"speaker":"桜井委員","kind":"質問","question":"今の説明の後段ですけれど、前段はこれはもちろん理解しているんですけれど、狭まった理由というのは何なのか尋ねました。","respondent":"鷹倉庶務課長","answer":"恐らく実質的に考えられるのはということですけれども、社会に説明していく中で、こういうふうに考えられます。","id":"exchange-010"},{"speaker":"桜井委員","kind":"質問・要望","question":"それで例えばこういう事例の方がこのことによってだめになっちゃうとか、例えばですよ。ちょっとわからないんですけれども、少し具体的な事例があれば教えていただきたいんですが。","respondent":"鷹倉庶務課長","answer":"私どもの方、これ幼稚園教育職員、調べてありますので、１２年度からですが、今のところ調べたところ該当者はなかったですので。区全体の中では総務委員会でやっていると思うんですけども、そちらの中ではいろいろ事例があるのかなと思われます。","id":"exchange-011"},{"speaker":"桜井委員","kind":"質問・要望","question":"そういう地域の皆さんからもかなりある日突然聞かされた話ですから一体どういうことなんだという意見が出たと聞いているんですけれど。ＰＴＡの連合会長はそれぞれ今は４月ですか、新たに決まりますよね。","respondent":"若月教育長、鷹倉庶務課長","answer":"学校の体質を変えるとか、教員の意識を変えるといったようなこと、どうも説明が結びつかないというご指摘であります。こういうふうに私たちは考えて、今回の実施に踏み切ったと、かように考えているところです。あるいは二日野の場合もう少し早くしたかったんですけれど、相手の都合で翌週の１３日ですけれども、説明に行ってあります。","id":"exchange-012"},{"speaker":"桜井委員","kind":"質問・要望","question":"この準備委員会というのは公開になっていくんでしょうか。そういうことをやって、ぜひやっていただきたいと思うんですが、いかがか尋ねました。","respondent":"若月教育長、鷹倉庶務課長","answer":"ですから私たちはそのさまざまな考えられる範囲の方策で今それに取り組んでいるわけでありまして、例えば委員がご指摘のように。今持っているそれぞれの小・中の課題が少しでも解決され前進されればいいなと… 公開問題がございましたけれども、プラン２１推進委員会もそうですけれども、一切情報公開で対応しているです。説明をしてほしいというような話があればこちらから出向いてやっているという話もございまして、今後やっていく予定です。","id":"exchange-013"},{"speaker":"桜井委員","kind":"質問・要望","question":"やはりそれは区民の大事な子どもたちを教育していくわけですから。それについてだけもう１点聞いて終わります。","respondent":"指田教育次長","answer":"したがってこれは固まり次第いろんな説明会を順次やっていきますけれども。ということは、これについては、だから連携だけはぜひとも学校と私どもの間で連携がないという中でやっているわけじゃありませんので。","id":"exchange-014"},{"speaker":"川西委員","kind":"質問・要望","question":"ですからそういう点では公聴会がいいのか、どういう組織がいいのかわかりませんが、検討委員会を進める段階で必要だというふうに思います。ですからそういう点ではそこの利用者、今利用している人かどうかは別ですよ。","respondent":"鷹倉庶務課長、若月教育長","answer":"したがって今回検討委員会を設けたのは、こういう中身をオーソライズしながらこういうふうに出していく。我々は先ほど地域の説明もしましたけれども、公のところを教育委員会だとか文教委員会… 例えば「論座」なら「論座」に私のインタビューで考えを載せてありますが、あれは何も小中一貫のコンセプトをすべて語っているわけではございません。","id":"exchange-015"},{"speaker":"川西委員","kind":"質問・要望","question":"一言だけ要望を申し上げておきたいのは、さっきおっしゃった幼稚園の保護者は将来を見るときにあると思うんです。できるだけニュースは的確に伝えてほしいというふうに思いますので、よろしく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"高星委員","kind":"質問","question":"各町会長にどういうようなものが行っているかというと、Ａ４のペラ１枚なんですよね。こういう話だったもんですから、ちょっと役員会の中でどういうような話をされたのかということをちょっとお聞きしたい。","respondent":"指田教育次長","answer":"一貫はできないかもわからないけれど、連携というものは追求していきたいと、こういう話は私させていただきました。これについてはこのあとそこでご回答はしませんでしたけれども、その辺が出されたという内容です。","id":"exchange-017","title":"町会・自治会支援"},{"speaker":"高星委員","kind":"質問","question":"私も然るべき予算委員会の中でちょっと質問を考えているものですから、どっちにしても今、二日野の校長先生が小学校の校長会の会長だと。さっき言った地区委員会で次長が拒否をしたのかどうかわからないけれども、その辺のいきさつだけちょっと聞いて私からは終わりたいと思います。","respondent":"指田教育次長","answer":"そのつもりはありませんから、今までそういうふうな町会長会議を傍聴させたこともなければそういうこともないからということもあったんだと思います。別段初めからポーンと切っているという話ではないので、その点だけはご理解いただければありがたいなという気はしています。","id":"exchange-018"},{"speaker":"高星委員","kind":"質問","question":"今の４年生から全部絡んでくる話となってくるわけですから、もともとの子どもは最初から行っちゃうという話にもなるわけですよ。具体的なものの進め方によってはやっぱりきちんとした考え方を言わざるを得ないときはありますので、ひとつ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"松澤委員","kind":"質問・要望","question":"私は統廃合論者ですから、ここは統廃合ではないという中でも．やはり二つの学校、その辺はしっかりとカバーして説明をしてほしいと求めました。今の体育館そのものが狭いとか不都合とか、そういう何か公式的な室内のインドアのものをやるにはという、そういうような問題もあったんか尋ねました。","respondent":"指田教育次長、山岡スポーツ協会次長","answer":"反対論、これは１００パーセントはやっぱりなかなか、全員の方が賛成ということはやはりこれはなかなか難しいだろうと思っています。基本姿勢としてはやはり１人でも多くの方にご納得いただけるような形でもっての説明会というものはや… ですから一回り大きくしていただきたいというのは考えております。それは今後の検討課題です。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"３クラス、４クラス想定しているわけですから。そうすると学校の体育館というのは別につくるわけか尋ねました。","respondent":"鷹倉庶務課長","answer":"基本的に別というふうに、今のところ一つの考えを持っています。","id":"exchange-021"},{"speaker":"松澤委員","kind":"質問","question":"入学のときにどうなんだろう、３クラス、４クラス。中学校は１６０人までということですけれど、最低１２０名、そのような進め方というのはどうなんか尋ねました。","respondent":"青木指導課長、富田教育改革担当課長","answer":"カリキュラムの問題につきましては今後研究を進めていく中で具体化していきたいというふうに考えております。そこでやはり選ばれる学校という形でそれぞれの保護者や子どもたちが学校をどういうふうな形で選ぶのかということも含めてま… これも検討部会の中で具体的には論議し検討していくことですが、小中一貫校、９年間一貫した教育ということが趣旨ですので。","id":"exchange-022"},{"speaker":"松澤委員","kind":"質問・要望","question":"そうなってくると、ことし二日野は１２名ですから、１２名しか小学生がいないところに１００名からの小学生が増えるわけですよね。私たちもできるだけ地元の意見を聞きながら、私も自分は区民の代表ですから議会で十分に議論し最後は報告していただくよう求めました。","respondent":"指田教育次長","answer":"したがって、今後の進め方についても、当然それはプラン２１推進委員会でかけた問題についてはきちんきちんと定期的に委員会のほうにご報告する。それからそれが一巡となりながら同時に区民のご意見や何かもお受けいただき、同時に説明もしていきたい、このように考えております。","id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"この点についてどうなのかと課長さんに伺ったら、私がいただいたのは１２年度で、１３年度はこれからまとめということでまだ触れていませんけれど。１点と、親の声を広く聞いてほしいんだというところで、どのぐらい参加の人数があったのか教えていただきたいです。","respondent":"青木指導課長、鷹倉庶務課長","answer":"これは小中連携のみならず、プラン２１の推進校はすべてにわたって１年間を振り返ってそれぞれの学校の評価と、教育委員会からの評価も出しています。それぞれのこの小中一貫教育のまとめも今しています。 説明会、丁寧にということ、それからあまねく広くです。それまでもう何回か役員クラスの方に状況報告的なことも進めつつ、声も広く聞くような形になっていかざるを得ないのかな、このように思ってあります。","id":"exchange-024"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そこをどこに出したらどう吸い上げてくれるのかというのが一番の関心事なんで、ぜひ、期間も十分取ってやっていただきたいなと思っています。とにかくこのプラン２１始まってからいろんな取り組みがあるんだけれども、そこに本当に心砕いてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それからもう１点は、車の問題がやはり子どもたちにとって心配だという、その辺をどう感じているのか。全部先々の問題になってくると思うんですけれど、基本的な考え方を教えていただきたい。","respondent":"青木指導課長、鷹倉庶務課長","answer":"交流可能であるというふうに考えております。この９年間のカリキュラムの中で多様な形で多様な子どもに対応できるようなカリキュラムの開発というようなことで研究が進められていくと思いますの… 体育館側からそういう要望が出てきますし、先ほど説明しました施設検討部会、学校のほうですね。安全管理の面とすり合わせしながら立地の問題等々いろいろ具体的に検討していく必要があるかな、こういうふうに考えております。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"確認","question":"もう一度確認ですけれども、中学校が転校生も中学校で受け入れていただけるという点。","respondent":"久保田学務課長","answer":"これはまた一つの検討課題ではあると思いますけれども、それともやっぱりそうじゃなくてほかの学校に行きたいのかというところをやっぱり選択できるような、そういうシステムは今後検討していきたいというふうに思っております。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"９年間、何かやっぱり見て小学校１年と中学３年と随分違う考え方も持っているし、その辺がちょっと気になって。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"桜井委員","kind":"意見","question":"今４ブロックあるけれども、それも学区を外すみたいな話もあるようなんですが、現実に。今後の検討課題、戸越台中はちなみにどうなるのかとの意見を述べました。","respondent":"久保田学務課長","answer":"そこのところもやっぱりこの準備委員会の中で十分に議論していきたいというふうに思います。","id":"exchange-029"},{"speaker":"桜井委員","kind":"意見","question":"任期が１年でしょう。というふうに思いますとの意見を述べました。","respondent":"指田教育次長","answer":"それは確かに継続して２年、３年というふうに継続する課題もあるでしょうし、１年のところの短期の中でもって整理ができる課題もあると思っています。","id":"exchange-030"},{"speaker":"高星委員","kind":"意見","question":"８日のプレス発表の後にやりますということを８日前に言っただけのことですよ。だからその辺のところを一つ、もう一度これから進め方、ひとつよろしく、その辺の考え方を聞きたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"川西委員","kind":"提案","question":"施設の有効利用、もっといろんな人が出入りするような地域に活性化していくということをご提案しますが、もしご意見があったら聞かせていただきたい。予算委員会で質問しませんからとの意見を述べました。","respondent":"指田教育次長、鷹倉庶務課長","answer":"この間、私どもも率直にプラン２１を進めていくに当たって、統廃合を前提にしたものではないということははっきり申し上げてきております。それは真摯に受けとめさせていただきたいというところで… これはそれぞれ学校につきまして、個別の学校改築検討委員会というような形のものを立ち上げていきたいなと思ってありますけれども、その中で。この辺のところを踏まえながら進めていきたいな、このように考えてあります。","id":"exchange-032"},{"speaker":"川西委員","kind":"質問","question":"１点だけ。これはいつごろ検討委員会を立ち上げていくかという検討はどの程度まで進んでいるのか、されているのか、伺います。","respondent":"鷹倉庶務課長","answer":"ただ、正式には４月からでいいのかなと思ってあります。そういうことを見据えながら、きちっと計画を立てていきたいな、こう思ってあります。","id":"exchange-033"},{"speaker":"川西委員","kind":"意見","question":"改めてこの表を見ますと、台場小学校はなぜ２０番なのか。ブロックが違うでしょうとの意見を述べました。","respondent":"久保田学務課長","answer":"これは行政順というんですか、通常私どもはそれぞれの学校に番号を振ってございまして、台場は２０番目ということになってあります。これでやると、もう一つブロック別に出せばよかったんですけれども、今回は一覧に出させていただきました。","id":"exchange-034"},{"speaker":"桜井委員","kind":"質問","question":"学校名をちょっと言うのはあれですから、あと３６番というところが１３年、１４年で共通した傾向が見られますよね。いかがか尋ねました。","respondent":"久保田学務課長","answer":"やはりこれは学校選択が始まる前から指定校変更でもって大井第一に来る傾向が強かった学校でございまして、その傾向が継続しているということで。","id":"exchange-035"},{"speaker":"桜井委員","kind":"質問・要望","question":"従来の流れが若干加速している部分というんでしょうか、従来の傾向がそのまま続いて、若干場所によっては加速化しているという理解でいいのかどうか。いかがか尋ねました。","respondent":"久保田学務課長","answer":"減っているところに対しての支援策なり、教育委員会としても今後ともやはり全力を挙げて支援していきたい、こういうふうに考えているところです。連絡を密にして、これは学校が当然やるべきことだと思っていますので、そういう点でのお話は１回も聞いてはおりません。","id":"exchange-036"},{"speaker":"桜井委員","kind":"質問・要望","question":"だからそういうことを、それは私の意見ですから、もし違うというのがあれば調べてほしいと求めました。そこのところはやっぱりきめ細かく分析をされていただきたいなと、それで必要な支援はぜひお願いしたいなという、要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"高星委員","kind":"意見","question":"ちょっと取り組むべき課題は取り組む課題としてきちんと整理して出していかなきゃ、この辺のところをどう、考え方。私の言っていることはおかしいかなとの意見を述べました。","respondent":"指田教育次長","answer":"本当に街の方々を含めて、プラン２１は始まったばかりというふうなところではないかというふうに思っています。初めから統廃合があってプラン２１を進めたというわけではありませんので、そこだけひとつ斟配していただければというふうに思っております。","id":"exchange-038"},{"speaker":"高星委員","kind":"意見","question":"学校の統廃合を議論するというときにいないかもわからないじゃない。だから、そういうことも含めて、やっぱりどうも順序が逆のような気がしてならないんですとの意見を述べました。","respondent":"指田教育次長、若月教育長","answer":"教育委員会とすれば、これでもってもうインパクトの部分が１００％上がったかというと、まだまだ私は上がってはいないと思っています。まだ３年目という段階において、これは私自身のちょっと考え方も含めて、述べさせていただきました。それも学校だけではなくて親御さんや区民の方も一緒になって考えてもらおう、区民の方や保護者の中から、そういう声が出てくるだろう。","id":"exchange-039"},{"speaker":"高星委員","kind":"質問","question":"だから、だれの英知が結集された方針なんですかというのを言いたくなっちゃうんですよ。〔「小中一貫ですか」と呼ぶ者あり〕それも含む学校改革のやつ。","respondent":"若月教育長","answer":"何かそのお話を伺っていると、私が１人でものを考えて、私が１人でものを進めているような受けとめ方をされて非常に心外であります。こういう姿勢は私どもは従来からずっと持っておりますし、これからもその姿勢は持っていきたい、こんなふうに思っています。","id":"exchange-040"},{"speaker":"高星委員","kind":"意見","question":"２人でやっていたんじゃどうしようもないんだけれども、じゃあ、最後に一言。あるいは学校関係者、ＰＴＡも含めていろいろな事前に議論をしたという経過がないもんだから、だから僕はやっぱり心配するわけとの意見を述べました。","respondent":"若月教育長","answer":"ただ、今進めているさまざまな教育改革についてですね、確かに校長によって温度差があることは間違いありません。しかし、それでもこういう方向でやりましょうと言って今進んでいるのが品川区の教育改革だと、こういうふうにご理解をいただければと思います。","id":"exchange-041"},{"speaker":"松澤委員","kind":"質問","question":"あの時にはゼロになっちゃったらどうするんだというふうなお話をしましたけれども、この９人という数字をどんなふうにとらえているのか。その９人という数字の重さをどのように考えているのかをお聞きしたいと思います。","respondent":"久保田学務課長","answer":"結果的には現在見込み９人ということで、これは第４回定例会、その辺の部分も影響して少なくなったという状況がありました。ぜひとも学校の取り組み、あるいは今後の方向性というものを説明しながら、それでもやはり結果的にこの９名に落ち着いたという状況にあります。","id":"exchange-042"},{"speaker":"松澤委員","kind":"質問","question":"そうじゃないですかね。そんなときで、小学校の子どもたちの教育というか、しつけというか、そこらから問題がしてくると思うんだけれども、その辺はどう考えているんか尋ねました。","respondent":"青木指導課長","answer":"そうしたいじめだとか不登校だとか、そうした問題を解決する一つの方策になるのではないかなというふうにも私は考えております。教育委員会も、そうした状況をつくっていけるように支援してまいりたいというふうに考えております。","id":"exchange-043"},{"speaker":"松澤委員","kind":"質問","question":"いや、だから、その課題の子が中学に来て、今のそういうふうにするんだというのはわかったんだから。小学校の間はどういうしつけや教育をしたんか尋ねました。","respondent":"青木指導課長","answer":"その情報交換などをもとに、さらには中学校に進学する際には中学校とよく連絡をとり合って進学させていくというような方法で今やっているところです。今後も小学校の指導に生活指導主任たちを通してまた考えていきたいというふうに思っております。","id":"exchange-044"},{"speaker":"松澤委員","kind":"質問","question":"学校は子どもたちを選べないわけですから、じゃあこの子どもたちを３年間うちの中学校で一生懸命教育しようと、そのような環境があればいいわけよね。ちょっとその辺の応援体制というのは今後やっていけるんか尋ねました。","respondent":"青木指導課長、若月教育長","answer":"学校とよく連絡をとり合って、指導主事、学校経営指導員、そうした指導課のスタッフでサポートしていきたいと思います。 これはなかなか実感として問題が起きないだけに小学校の教員には伝わりにくいという大変難しい部分はあります。しかし、ご指摘のとおり、この９名という数は大変重い数字だ、私はそう受けとめております。","id":"exchange-045"},{"speaker":"高星委員","kind":"質問・要望","question":"学童クラブというのは、例えば今日来ないけれどもどうしたのという形になるじゃないですか。だけれども、ここではその辺の扱いはどうなっているんだったかなと思って、ちょっと悪いんだけれども教えていただきたい。","respondent":"富田教育改革担当課長","answer":"勉強会があります、参加申し込みをしていただく折に、フリータイムにつきましてもわかっている範囲で参加の予定というのは出していただいております。参加につきまして、親御さんのほうから問い合わせをしていただけばお答えをしますという対応を今のところしています。","id":"exchange-046"},{"speaker":"高星委員","kind":"質問","question":"あいつどうしているかな、こうしているかなと、具体的なそのようなところで問題が起きたようなことはありませんでしたでしょうか。何か細かい問題が起きなかったのかどうなのかということを、１年になるので、ちょっと聞いてみたいと思います。","respondent":"富田教育改革担当課長","answer":"相談をしてきてもらいたいということは、繰り返し保護者の方へのお知らせでも、また児童にも言っているところです。３時帰りの予定だったけれどももっと遊んでいたとか、その辺についても親子できちんと確認をしていただくのが基本であるです。","id":"exchange-047"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"フリータイム、あと勉強会、あと種々の教室が組まれていますね。その辺、指導員のところの待遇というか、報酬のところを聞かせていただきたい。","respondent":"富田教育改革担当課長","answer":"その役割といったものが若干異なってくるのかなというような認識をしておりまして、今後もやはり地域、また協力できる保護者の方が支える。","id":"exchange-048"},{"speaker":"飯沼副委員長","kind":"質問","question":"１回６０名近く、２人いたんだけれども片一方の方がやめられて、結局１人で全部責任を負っているというお話をちょっと伺ったんですね。その辺の責任とか内容から言って、講師料とか考えられるんじゃないかなと思うんですけれども、その辺というのはいかがか尋ねました。","respondent":"富田教育改革担当課長","answer":"初めにご指摘の、ないところというのは、こちらで抜けている月という意味ですか。","id":"exchange-049"},{"speaker":"飯沼副委員長","kind":"意見","question":"例えば、だから毎月１回とかじゃなくて、ない月もあるのかなという。その辺がなぜかなというとの意見を述べました。","respondent":"富田教育改革担当課長","answer":"こういう１表にまとめてしまいましたけれども、また魅力的な内容ということで、毎月実施という意味ではございません。学校支援ボランティアの名簿の中からお声をかけてお願いをしてきたところですけれども、その辺につきまして、こちらもモデル実施ということで。","id":"exchange-050"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"パソコン教室については、本当に子どもたちがすごい喜んで参加しているということなので、ぜひ内容を充実させるという意味では、本当に学校の先生のところとか、あと専任の方全体を見ていらっしゃる方のご意見なんかも十分取り入れて、担当者が悩まないように工夫をしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"桜井委員","kind":"質問・要望","question":"佐藤弥二郎議員の「学校経営と外部評価について」から、外部評価の問題で１点、明日質問をさせてほしいと求めました。これは文教委員会に正式に報告のない中身でありますので、改めて聞きたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/547087?Template=document&Id=4430#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":63681,"voices":139}},{"id":"h14-20020304-5","meetingId":"h14-cm03","date":"2002年3月4日","dateIso":"2002-03-04","committee":"総務委員会","time":"午前１０時０４分～午後５時０８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を101件整理しています。","topics":[{"id":"topic-01","title":"第１４号議案から第１６号議案までは職員の勤務に係る議案でありますので、一括審査いたします。 それでは、(1)の第１１号議案…","agenda":"第１４号議案から第１６号議案までは職員の勤務に係る議案でありますので、一括審査いたします。 それでは、(1)の第１１号議案…","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"私も勉強不足で、伺いたいんですけれども、これからまた株が上がってくるわけですですね。そういうところの何か上がってくるとか、そういうことになっているんか尋ねました。","respondent":"太川総務課長","answer":"先ほど改正の理由といたしまして説明をさせていただきましたけれども、設立時には定款にそれを書いておかなければいけないということであります。そういう意味合いから、今回、商法のほうは額面株式について廃止をしたというふうに聞いてあります。","id":"exchange-001"},{"speaker":"北野委員","kind":"質問","question":"初歩的なことでお伺いしたいんですけれども、提出というのは、どこあてに提出するのか。そこのところがわからないんです。","respondent":"太川総務課長","answer":"これは区長が区長に提出するです。","id":"exchange-002"}]},{"id":"topic-02","title":"の第１２号議案、品川区同和対策資金貸付条例を廃止する条例","agenda":"の第１２号議案、品川区同和対策資金貸付条例を廃止する条例","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"事業振興資金は昭和６２年度以降、生業資金が昭和６３年度以降新規貸付を行っていないということですね。それ以降は貸し付けを行っていないということですけれども、申し込みはなかったんか尋ねました。","respondent":"阿部人権啓発課長","answer":"申し込みもございません。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"実際問題、法律も終了ですからね。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"北野委員","kind":"質問","question":"この貸し付けを受けるための手続きはどういうふうにされているのか、ちょっとお伺いしたいと思います。","respondent":"阿部人権啓発課長","answer":"区長に、例えば貸し付けするのが適当であれば、そのような報告をいたします。その報告に基づいて貸し付けをするです。","id":"exchange-005"},{"speaker":"北野委員","kind":"質問","question":"期間としては、審査の結果が出るまでというのはどのぐらいだったんでしょうか。結局、こちらのほうに移った場合と、どっちが利用しやすいかという部分の判断が必要かなと思います。","respondent":"阿部人権啓発課長","answer":"この項が現在利率０.５％ですので、事業振興資金は年３.６５％ですから、大分利率が低くなるということがあります。社会福祉協議会のほうは１４１万円ですので、貸し付けの金額が大きくなるというようなメリットがあるというふうに考えてあります。","id":"exchange-006"}]},{"id":"topic-03","title":"の第１３号議案、品川区職員定数条例の一部を改正する条例","agenda":"の第１３号議案、品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"おそらくそういうことになるだろうと思うんだけれども、一番うしろの４ページの２番の表で、ここ３年ぐらいの新規採用の数は分かりますかとの意見を述べました。","respondent":"古川人事課長","answer":"６名ですが、幼稚園教諭関係が３名でございましたので、平成１３年度につきましては採用０です。保育士につきましては１２名、保健婦を１名、最終的には４月１日の採用をいたします。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"意見","question":"どういうふうにカウントするのか。我々は定数をどういうふうに把握しておけばいいのか、その辺を聞かしてくれませんかとの意見を述べました。","respondent":"古川人事課長","answer":"４月に数名フルタイムを予定していますが、これは定数の中に含まれているです。その者を除いた人員を採用する予定で今進めているです。","id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問","question":"２人で１人ということにするという考え方というふうに、実際の数より多い人が働くということになるよという理解をしておけばよろしいんですか。単純に定数が１００だとしても、１１０人いる職場もありますよという考え方でいいか尋ねました。","respondent":"古川人事課長","answer":"４０時間を１と考えますと、単純に申し上げますと、２０時間ですと０.６人、時間数で捉えますとそういう形になります。これは従来の再雇用も同じような形です。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、週４０時間の人だけが定数条例の範囲の中にカウントされて、それ以外の方は、再任用という制度に変わったけれども、再雇用と人数の定数に係る部分は同じですよという、それは法的にはいいんか尋ねました。","respondent":"古川人事課長","answer":"しかし、短時間につきましては、同じ一般職ではありますが、条例定数による管理ではなくて、別途管理という位置づけになっております。法的に問題はございません。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問","question":"それだけは理解しておきます。議論をしていくときに、こっちのものが１００人ぐらい再任用として短時間の人がいるんですよということも、その辺はどういうふうにお考えか尋ねました。","respondent":"古川人事課長","answer":"再雇用のときは一定の判断の中でこれも対象になった。最終的には４月以降人数の勤務形態すべて固まりますので、その辺の考え方については皆さんにご報告できるというふうに考えてあります。","id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そういう方たち、もちろん相手側の理解をいただかないとということですけれども、そういうことも視野に入れていくべきだなというふうに思います。専門が要求されるので、その辺もぜひお考えに入れておいていただきたいと、お願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"研修等の１人当たりの労働生産性をアップさせるということとは別で、減らした分、逆に支出としては増えてくるものだと思うんです。本来ですと、それらと兼ね合わせた数字というのはつかんでいらっしゃるのかどうかというのをお聞かせほしいと求めました。","respondent":"古川人事課長、市岡企画財政課長","answer":"先ほどご説明申し上げた中で、高齢職員を向上させるという点と、それから人件費等をどういうふうにするかというのがあります。先ほどのご説明のとおり、先ほどお答えいたしました問題でしたが、そうしたものが入ってきている。そういう意味では、職員費の減に対応する委託料が幾ら増えているというふうな捉え方はしておりませんが、予算編成の中では。","id":"exchange-013"},{"speaker":"田中委員","kind":"意見","question":"逆に委託費が結果的には前年よりも費用が増えた、かかってしまったなどということがあってはいけませんので、そういう観点からの評価のできるような仕組みづくりをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"土井副委員長","kind":"質問","question":"保険年金課で１７名の減ですが、さまざまなそのほかのこれに係わる事業の中であったのかもしれませんので、その辺をお伺いしたいということ。そこら分を聞かせていただけませんか。","respondent":"古川人事課長","answer":"この関係で全体で圧縮された部分が１７ということでございまして、保険年金課は配分定数上は８６人で、１７人予算計上しております。","id":"exchange-015"},{"speaker":"土井副委員長","kind":"質問","question":"１７人はみんな給料が違うわけでしょうから、その分まで見るよという、財調的な発想の見積もりで出ていたんでしょうか。それとも具体的にこちらのほうから１７人が、これに従事しています、それを全額やってくださいというスタイルなのか尋ねました。","respondent":"市岡企画財政課長","answer":"基本的には理論的に言えば、全額措置されるはずですが、若干超過負担がございました。各区の対応がいろいろある中で、明らかになったことですけれども、品川区の場合には財調を含めたトータルでは持ち出しはないという状況になりました。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問・要望","question":"行政評価システムが稼働し始めたわけですから、前向きで付加価値を付けるからいいんだという、そういう考え方でやる。アウトソーシングにしたらどうなったということを比較しなければ行政評価にならないわけですから、その答えをひとついただきたい。","respondent":"市岡企画財政課長","answer":"人件費、これは容易に縮減ができなくて、そのことで財政構造を非常に硬直化させるということが財政運営上あります。こういうふうに業務の見直しを進めているわけでございまして、成果というものの検証ということも続けてやっていきたいというふうに思ってあります。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"それは大変なことなんですから、その付加価値をどう評価するかは別問題で、業務委託の最大の理由ではないかと思います。そこのところがちょっと答えが明確でなかったから、聞いたわけです。","respondent":"市岡企画財政課長","answer":"全く同じ業務を外注しても、全く単純に同じようにできるのであれば、委員がおっしゃられるとおりだと思います。私どもは、ほんの少しそれを拡張して考えているです。","id":"exchange-018"},{"speaker":"塚本委員","kind":"質問・要望","question":"もう１点、具体的に定数を変えていったということの考え方を聞きたいんです。どういうふうにやっていくか、どういう考え方なのか、聞かしてほしいと求めました。","respondent":"本間総務部長","answer":"先ほど人事課長から説明させていただいたとおり、その大きな二つにそれぞれ技術職員を配置して、できるだけ現場で判断がつくように。さらに進めることによって、実態に合わせていこうという趣旨から、今回定数をこのようにしたというふうにご理解いただきたいと思います。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"事業部制を導入したことによって、現場に即したような設計なり管理監督ができるようにしたということです。そのほかにも実際にはもう少し分かれているのか、それとも見えないところにそういうことが起こっているのかということをお聞きしたいと思います。","respondent":"本間総務部長","answer":"委員ご指摘のとおりでございまして、実際には、これは定数上の配置でございまして、これにプラスして過員で付けてあります。将来的に考えた場合には、実際の配置は、これにプラス過員を付けているというふうにご理解いただきたいと思います。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"庶務課が２プラスというふうに伺ったんですけれども、そういうような実態はどうなるのかなというのがちょっと心配なんですけれども、そこら辺のイメージがどうなるのかということを説明ほしいと求めました。","respondent":"岡田施設課長","answer":"それ以外の部署については、従来どおり経理課に残ります施設部隊に執行委任を受けて実施する。先ほどの話で、これを委託化しながら進めていくという構想のもとに、これだけの人数でも十分こなせるという出発点で平成１４年度から始めるです。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問・要望","question":"こういう機能というのは実際どういうふうになっていくのか。この間新しいやり方が導入されたんですけれども、そういうところが果たしてどうなっていくのか、教えてほしいと求めました。","respondent":"岡田施設課長","answer":"今まで区が発注するもろもろの工事ですが、仕様関係、あるいは単価、その他いろいろ統一をとってやってきてあります。各事業部のほうにいく、こういう連携をとりながら統一していく、このような考えです。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問","question":"施設設計、管理事務が民間委託にいくんだと。これに基づいたものだというふうなお話だったので伺ったんですけれども、これをまた管理をするのも民間で委託するということになるんか尋ねました。","respondent":"本間総務部長","answer":"１級建築士、有資格者できちんとその部分については対応をしていくというのが、今回の組織改正の一番の基本にあるというふうにご理解いただきたいと思います。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"質問","question":"民間委託化の方向というのと、ベテランを配置しておるという話と、ピンとこないところがあるんですけれども、一応今の説明で聞いておきます。ひまわり荘のところの中身では、児童虐待の相談なども受けることになるというふうに聞いているんですけれども、それは確かか尋ねました。","respondent":"古川人事課長","answer":"２４時間の体制を持って生活支援、こういうことで伺ってございまして、そのときに品川区子育て支援センターというものが構想の中にあるようです。児童課の２人増やしていただいたということについても、その中で考えるというふうに聞いております。","id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問","question":"それが民間委託という前提でいくというのがどうしても私は解せないんですけれども、そういう心配が実際にはどうなのか。そういうことで何か知っていることがあれば、お伺いいたします。","respondent":"古川人事課長","answer":"児童虐待に関しましては、児童施設だけでなくて、さまざまなところ、あるいは保健所、教育、さまざまな分野でも連繋が必要だと思ってあります。全国的に公設支援施設、２４時間体制も含めてということでありますと、社会福祉法人で実施しているのが現状です。","id":"exchange-025"},{"speaker":"宮崎委員","kind":"意見","question":"実際にこういうふうになっているから。今回、二葉保育園が増設になるんですけれども、全体で見ると、保母がこの部分が増えるのかどうなのか、どういうふうになっていますかとの意見を述べました。","respondent":"古川人事課長","answer":"ただいまお尋ねの保育園につきましては、今回増減はございません。さまざまな事業が実施される中で、人事異動等の中でやるというふうに考えております。","id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"保母全体を変えないということになると、その中の保育士を変えないということになると、どこから持ってきてそこに充てるか。要するに、ほかのところに影響が出てくるということになるわけか尋ねました。","respondent":"古川人事課長","answer":"そうすると、新規採用を今のところ１０人を考えてございまして、保育士の定数は、今回は変更してございません。今３７園ありますが、その中での保育士の全体の調整を図りながら、新しい実施園での体制を考えております。","id":"exchange-027"},{"speaker":"三上委員","kind":"質問・要望","question":"そこのところを簡単でいいですから教えてほしいと求めました。特に組合に関係している方もいらっしゃるので、今までそういう質問が出なかったのでしょうけど、お伺いいたします。","respondent":"古川人事課長","answer":"６０歳以降も、その人の能力を把握していく。申し込みが６５名という状況でございましたが、最終的に６名不採用ということで、５９名の採用の考えを持っております。","id":"exchange-028"},{"speaker":"三上委員","kind":"意見","question":"そうすると、再任用をお願いしたいと希望する方たちは、基準ということを明確に受け止めた理由ということとしていいですねとの意見を述べました。","respondent":"古川人事課長","answer":"後任からも申し込み、それから、所属長による推薦、それから、私のほうで全員と面接を行いました。採用の経過については、これは具体的に申し上げることはできませんが、採用に当たっての基準は示しております。","id":"exchange-029"},{"speaker":"三上委員","kind":"意見","question":"所属長から一言だけ、だめだったとか、何とかというような、結果があると。内容がどうだとか、決してそういうふうな形でその人に対して冷たい扱いをしたということではないというふうに受け止めていいのかなとの意見を述べました。","respondent":"古川人事課長","answer":"その状況も聞いているわけですが、所属長の対応できる範囲でそれぞれに対する不採用者については一定の配慮はしているというふうに考えてあります。非常勤のうちで、人事課のほうで答えられる範囲で答えてあります。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ほかのところから集めると、ほかのところがまた減ってくるということになるわけですから、かなり現場のところも大変だという声があります。マンパワーですから、ここのところをきちっと持ち続けていかないと、私はまずいんじゃないかなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問","question":"この、特別な勤務というのと、第１６号議案に特殊勤務手当というのがあります。片方は「特別の勤務」、片方は「特殊勤務」とありますけれども、つまり第１４号議案の「特別な」というのは、何に当たるんか尋ねました。","respondent":"古川人事課長","answer":"例えば夜の巡視、それぞれの夜の勤務時間、それ以外の部分の開庁時間の業務としております。特別の勤務を命ずるというのは、必要な休憩時間を与えることができる、こういうふうになってあります。","id":"exchange-032"},{"speaker":"林（宏）委員","kind":"質問","question":"こっちは時間を与える。あるいは第１４号議案のほうの特殊勤務というのに、特殊勤務なんだから、時間は必要だというような話にはならないですかね。","respondent":"古川人事課長","answer":"ですから、本来の業務に付随している報酬的なものは、特殊勤務手当で対応するですけれども、これは時代とともに傾向が変わってきているかと思います。今回もそういう観点からかなりのものを整理したというふうに考えてあります。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問・要望","question":"第１６号議案のほうから伺います。そのところの削減効果というのをどういうふうに見ているのか。","respondent":"古川人事課長","answer":"７,０００万円をほぼ３,０００人の職員が、平均化をした場合１人当たり２万円程度の減になります。対象者については年に１回、全体としての事務経費としては関係するところを特定してですので、それほどの事務量ではないというふうに考えてあります。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問・要望","question":"２３区の中で品川区は先んじて特殊勤務手当を見直しているということです。その特徴といいますか、この部分の考え方があるかもしれませんが、２３区と比較してのところでお話をほしいと求めました。","respondent":"古川人事課長","answer":"このときは５％減ということで新聞報道されておりますので、４０％は大規模な見直しだったなというふうに考えます。今回もこの部分につきまして、品川区としては踏み込んだというふうに考えてあります。","id":"exchange-035"},{"speaker":"塚本委員","kind":"質問","question":"こうあるべきだといいますか、そういうことがないと、どんどん官に対する見方が大体できてしまう恐れがある。この報告も、よくなるということをどういうふうに考えるかという、そこのところをどう見ているかということを教えてほしいと思います。","respondent":"古川人事課長","answer":"私ども民間と国等の感覚の違いを認識し、必要によっては、運用を厳しくしていく必要があると考えます。あくまでも民間との関係も基本にしながら、適正な取得、適正な承認をしていくということに注意していくという考えです。","id":"exchange-036"},{"speaker":"塚本委員","kind":"意見","question":"ぜひそうしてほしいのと、それから、資格をとるいろいろな制度が、勤めているところでとるわけですけれども、実態はどんなに変わってきている。従前どおりの比較をとって、それで良しとするようなことがあってはいけないということだけ申し述べておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"土井副委員長","kind":"質問","question":"第１４号議案、第１５号議案は官民そろっての中身ということですから、いかなる労働組合でもこれは賛成するだろうと思うんです。最後に、そういうこともさまざまあったけれども、その状況を労働組合等も理解をされておるというふうに考えてよろしいんですね。","respondent":"古川人事課長","answer":"この４年間、条例改正をするに当たっても、社会環境の変化に対して、双方の立場に立って主張してきました。一つ一つの問題につきましては、いろいろ考え方の相違はあろうかと思いますが、こういうふうにご説明があったというふうに私は感じております。","id":"exchange-038"},{"speaker":"土井副委員長","kind":"質問","question":"当然のことながら、どこかの時点で何らかの文書的な意味を含めてやられていたものが、平成１０年の条例化のときにどうなったのか。そして今回はどうなるのか、そのときに実施するわけですから、今どのようになっておりますか。","respondent":"古川人事課長","answer":"この時点でもかなり見直しがされたと考えていますけれども、その後の変化の中でさらなる見直しが今回実施をする。社会環境が大きく変化する中で、必要の都度今後とも見直していきたいというふうに考えてあります。","id":"exchange-039"},{"speaker":"土井副委員長","kind":"意見","question":"問題なのは、その裏付けがちゃんとなっているんですねと。とんでもないけれども、豪腕でやられちゃったんだというだけの話だと話が違うよというところを、ちょっとどのようになっているのかを聞きたいとの意見を述べました。","respondent":"古川人事課長","answer":"本来業務に加えて特殊の必要性を、専門職ですので、当然その中に入っているという私どもの考えです。状況の変化についてはある程度認識している、こういうふうに考えてあります。","id":"exchange-040"},{"speaker":"宮崎委員","kind":"確認","question":"確認しておきたいんですけれども、そのときは１.５倍の賃金ということになっておりますけれども、２,０００円というのはどんなものか。それと固定しているからから一人ひとりによって違うんだろうけれども、税金でどんな感じなんか尋ねました。","respondent":"古川人事課長","answer":"月に１回、不規則性があるという考え方に立った２,０００円ですけれども、不規則性にかんがみた定額の性格を持っております。現時点では２,０００円が相当であろうというに考えてあります。","id":"exchange-041"},{"speaker":"中島委員","kind":"質問・要望","question":"民の立場を感じているところがあるものですから、そのこと自体に、いいんじゃないかなと思いました。委員の立場で見たときに、これからできればなくす方向で努力をしていただきたいという、意見だけ述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]},{"id":"topic-04","title":"の第１７号議案、品川区職員住宅資金融資基金条例の一部を改正する条例","agenda":"の第１７号議案、品川区職員住宅資金融資基金条例の一部を改正する条例","exchanges":[{"speaker":"三上委員","kind":"質問・要望","question":"お伺いしますけれども、通えるわけがないわけですから、区民の願いであるということは当然のことですよね。１人でも品川区に居を構えてもらうという考え方を持っているんですが、そこらあたりのお考えをお聞かせほしいと求めました。","respondent":"古川人事課長","answer":"当然そこには利子補給というものが入ってまいりますから、今回全体を見渡す中で、休止という一定の考え方をしたものです。そういう中では、職員の福利厚生をどこまで公金を投入するかという大きな問題にも当然係わってまいりますけれども、こういうふうに判断したものです。","id":"exchange-043"},{"speaker":"三上委員","kind":"意見","question":"しかし、職員の定住策ということをどう考えるのか、これについての基本的な考え方を区当局も考えていかなければならないんじゃないかなと思うんです。","respondent":"古川人事課長","answer":"答弁漏れがございまして、職員の区内在住者はどのくらいかというお尋ねですけれども、平成１３年３月時点で１,２６１名、全体が３,３１３人ですので、率から申し上げますと約３０％です。","id":"exchange-044"},{"speaker":"宮崎委員","kind":"質問","question":"こういうところではどういうふうな意見になっているかというと、借りられない原因はどういうふうに考えているのか、そこのところはどうか尋ねました。","respondent":"古川人事課長","answer":"委員会を設置してございまして、当時募集の時期が年４回でありましたのを、一定の利用しやすい制度に少しでも近づくような努力はしてきました。こういう中で、しかも利用者がいないという中で、２億数千万円基金として継続する意味は非常に薄い。","id":"exchange-045"},{"speaker":"宮崎委員","kind":"質問","question":"先ほど審議会で、希望があったときにいろいろ条件を審議する会というのがあったと思うんですけれども、そこで、問題点というか、指摘されていたんか尋ねました。","respondent":"古川人事課長","answer":"平成１２年度、平成１３年度、予算で１回計上いたしましたが、あっ旋件数は０でございましたので、この状況についてのご説明をいたしました。平成１１年度においては、改善するため、利用しやすい制度に向けた努力はしていきたいというふうに考えております。","id":"exchange-046"},{"speaker":"北野委員","kind":"意見","question":"第５条のところに、新たに処分ということをうたっている意味というのは、そこをどういうふうに考えておられるのかとの意見を述べました。","respondent":"古川人事課長","answer":"予算で定める前提が、貸付残高に対する一定の担保という意味合いがありますので、８分の１相当額を納める。要は、これにつきましては、年度ごとに前年度の末尾の貸付額の全額が必要であるということで、制度上処分についての規定を設けたです。","id":"exchange-047"},{"speaker":"北野委員","kind":"質問","question":"なくなってきたらば、結局廃止ということになるんでしょうか。やはり早過ぎるというんですか、原資というんですか、なるんか尋ねました。","respondent":"古川人事課長","answer":"預託額の８割相当額を融資の上限ということで定めて、昭和５３年度から制度を、若干改正はございましたけれども、行ってまいりました。こういうことにも着目いたしまして、必要な額を貸し付けております。","id":"exchange-048"},{"speaker":"北野委員","kind":"質問・要望","question":"利息がまた上がってきて、先が見えない状態でありますけれども、そのときにはまた復活ということもあり得るんですよね。ある程度分かりましたけれども、休止というところの時点は先は見えませんけれども、制度は継続していただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問","question":"第４条の運用益金の処理、第５条の処分のところで、本来のねらいは第４条あたりなのかなと。すぐには復活できないなどというようなことが将来的に起こり得るのかどうか、その辺は想定されているのかどうかということをお伺いしたいと思います。","respondent":"古川人事課長、市岡企画財政課長","answer":"廃止を前提に考えているわけではございませんが、休止、廃止を前提に検討を加えていたところです。しかも、この制度の必要性等も判断しながら、予算で見定めるというのが現時点で最善の策ではないかというように考えてあります。 こういう状況にありますと、今回は処分できるように、ほかの目的に有効にその財源を使うという形をとらせていただきたいです。新しい制度として選択をするということになりますので、財源もそのときに考えたい、こういう考えです。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"復活をするという際も、それが新しい制度になるということで、金融情勢に対する早急な対応をしてほしいと求めました。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"土井副委員長","kind":"質問","question":"ですから、何か既得権が取られたなどという発想になっては困るものですから、そこら辺は。そこはきちっと、そういう形のものは進めていただくような仕組みみたいなものはどうなのかなというふうに思うんですが、その点だけお伺いします。","respondent":"古川人事課長","answer":"広く２３区の中では、区の共済あるいは都の共済、こういう制度をさまざまな角度から検討をしながら、対応しております。そういう意味では、まさに窓口については、職員の相談にはいろいろな形でやってまいりたいというふうに考えてあります。","id":"exchange-052"},{"speaker":"宮崎委員","kind":"質問","question":"今日は、前副理事長、事務局長が来るのかなというふうに思ったんですけれども、今後、その機会というのはできるんでしょうか。これはお願いしておきたいなと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"宮崎委員","kind":"意見","question":"何で買わざるを得なかったか。例えばこれだったら何で黙ってやったのか、そこのところが何でアルゼンチン国債をしたのかというところが、ここからだと見えないんですねとの意見を述べました。","respondent":"中尾根企画部長","answer":"格付けの問題も、経済的なそういう仕組み等も考えますと、今のような時代になるというのは非常に考えにくい。そのように自分としては判断したんだです。","id":"exchange-054"},{"speaker":"宮崎委員","kind":"質問","question":"元金や、実効期間、このときはどういうふうにこれを認識していたのか。アルゼンチンの国が歴史があるとか、ないとかでなくて、ここのところはどういうふうに認識したんか尋ねました。","respondent":"中尾根企画部長","answer":"少なくともより有利な運用資産をというふうに純粋に考えられたというふうに私どもは受け止めております。理事会にも報告をされていない、こういうことでございまして、これだけに限ってこういう手続きをあえてしたんだというわけではございません。","id":"exchange-055"},{"speaker":"宮崎委員","kind":"質問","question":"よかれと思ったということであれば、何で全体に諮らなかったんだと。そこのところは言っているんか尋ねました。","respondent":"中尾根企画部長","answer":"先ほども言いましたように、この部分だからこういうふうにしたというわけではなくて、この間の財産運用についてはそうしている。この手続き違反は明確だと、このように調査会としては指摘させていただいているということですので、そのようにお答えいたします。","id":"exchange-056"},{"speaker":"塚本委員","kind":"質問","question":"そして最後には個人が責任を負うか、負わないかという話、慎重を期して調べていかなければいけないと思います。最初に伺いたいのは、先ほどちょっと触れられましたけれども、どういう権限でもって調べているのかということをもう一回はっきりとお知らせ願いたい。","respondent":"中尾根企画部長","answer":"必要があるときは、書類および帳簿を提出させ、および実施について事務をさせることができる。この条例の中でも第６条でも取り決めがあるということで、したがいまして、この権限に基づいて私どもが調査をする。","id":"exchange-057"},{"speaker":"塚本委員","kind":"意見","question":"それに対して品川区としてはそんな認識では甘いと考えるか、自己検証をどういうふうに我々がまた判断をしたのかという話が聞こえてこない。その件に関してとの意見を述べました。","respondent":"中尾根企画部長","answer":"第１点目の、やはり調査が必要という考えですから、そういう立場ではございません。２点目の件ですけれども、先ほど言いましたが、補助金等も出す立場から調査をさせていただいたということです。","id":"exchange-058"},{"speaker":"塚本委員","kind":"確認","question":"理事会がこの間２回あったと思うんですけれども、２回の理事会の様子はどのようであったかと、理事会がどういうふうに展開していったのか。どういう対応をとったのかということに関して、財団が調査して、理事会の中で確認をしなければいけないと思うんです。","respondent":"中尾根企画部長","answer":"これは財団内部の財産運用の問題ということで認識は出発しておりますが、補助金、そういうことの考え方です。財団内部としては本年の２月１９日の中に報告をしようと、こういう考え方で準備をしていたというのが経過、いきさつです。","id":"exchange-059"},{"speaker":"宮崎委員","kind":"質問","question":"ほかの金利がいいのでやったらどうかというふうな質問があるんです。先ほどから、よかれと思った式ということだと、何で表に出さなかったのかということ。","respondent":"中尾根企画部長","answer":"翌年の平成１３年のときには、こういう点では、統一的なところの取り扱いにはその時点の中ではなっていない。「債券」と表現したり、「国債」という表現をしたりしているということが実態で、そういう認識にあったという報告は受けてあります。","id":"exchange-060"},{"speaker":"宮崎委員","kind":"質問","question":"そういう中身論で、本当のところはどうなんだというのが全くわからないんです。事務局長の決裁というふうになっているんですけれども、そのときの前副理事長の、当時の事務局長に対しての指示はどういうふうなのがあったんか尋ねました。","respondent":"中尾根企画部長","answer":"もしそういうふうにあったとしても、現事務局長がそういう認識で資金を運用するんだということを述べたにすぎないんだというふうに思っております。","id":"exchange-061"},{"speaker":"宮崎委員","kind":"確認","question":"何で安全、確実なんですか。当時これだけの危ないという資料がありながら、それでも問題ないということなんか尋ねました。","respondent":"中尾根企画部長","answer":"ある理事から、「財産目録の流動資産の中にはＭＦは金利が非常に低いので、金利のよい国債を検討されたらどうか」というご質問です。さらに安全、確実、有利なもので検討をしておりますという、この三つですね。","id":"exchange-062"},{"speaker":"宮崎委員","kind":"質問","question":"言っているのをそのまま当てれば、こんな事態にならないんじゃないですか。そうじゃないんか尋ねました。","respondent":"濱野助役","answer":"事務局長が嘘をついているというようなお話がありましたけれども、嘘をついているというようなことはないと思います。ＭＭＦは利率が低いから、もっと有利な運用をしたらどうかという質問に対する答えだということを認識していただきたいと思います。","id":"exchange-063"},{"speaker":"宮崎委員","kind":"質問","question":"アルゼンチン債も問題ないんですか、私はアルゼンチン債が、こんなことでなかったら、これから外国債をどんどん買いますよと。今でもアルゼンチン債を購入したということは全然問題ないというふうな認識なんか尋ねました。","respondent":"中尾根企画部長","answer":"非常に安全性が高くて、利率が高い外国債がもしあるんだとすれば、それはそれでいいわけです。ただ、それぞれ関係者は関係者なりの確信を持って買われたんだと思いますが、結果論としてはいいというふうには言えませんということです。","id":"exchange-064"},{"speaker":"土井副委員長","kind":"意見","question":"ここがなぜこんな形のものが決まっているのか、どう言うべきか、買わないんですね。その辺についてちょっとお聞かせをいただければ、それが法的にどうのというところの若干のお答えになるのかもしれないなと思いながら聞くんですとの意見を述べました。","respondent":"中尾根企画部長","answer":"国との関係の中で、財政も含めてかなり独立したというものにならないと、いろいろ自主的な運営というものの確保はできない。しかしながら、まるっきり株式会社と同じように、自分たち独立ではできない。","id":"exchange-065"},{"speaker":"土井副委員長","kind":"意見","question":"そこに自主性、使わないんですけれども、そう書いてない限りはやれるんだなという判断に移っていく流れもあったやに思えてならないんです。","respondent":"中尾根企画部長","answer":"ですから、一つの省で、こうすべきと判断したとしても、ほかの省では、こういう解釈もあるというふうに、意見はいろいろ当然ながら違ってくる。関係閣僚会議、幹事会申し合わせという、今委員が指摘されたようなことが内蔵されているのではないかというふうに推測はしています。","id":"exchange-066"},{"speaker":"北野委員","kind":"質問","question":"投資についての考え方というんですか、妥当だということで考えてこられたと思いますけれども、今後はどういうふうな形で考えていかれるんか尋ねました。","respondent":"中尾根企画部長","answer":"投資についての考え方ですけれども、理事長がちゃんと提案をして、どういうふうにすればいいのかが決められるべきだというふうに思っております。したがいまして、今後についてはそういう新しいルールを事業団内部でお決めになってやられるというふうに私どもは思ってあります。","id":"exchange-067"},{"speaker":"北野委員","kind":"質問","question":"しかし、これがあるからこそ投資に対しての判断が本当に判断されてやられたのかなというところの疑問が残るんですね。結構個人的な見解というか、その点については調査の中からどういうふうにお考えか尋ねました。","respondent":"中尾根企画部長","answer":"そういう点からすると、これは違反にはなっていない。運用の仕方、そういう姿勢の中で調査の結果をまとめてありますので、その点をお汲み取りいただければと思います。","id":"exchange-068"},{"speaker":"北野委員","kind":"質問・要望","question":"品川区の中では、アルゼンチン債が１億６,０００万円ということですけれども、他の自治体でもあるわけですね。そしてまた、そういう面でどういう動向かというのが分かったら教えていただきたい。","respondent":"市岡企画財政課長","answer":"委員おっしゃられるとおり、地方公共団体が直接買うということは法律上もできませんので、あとは外郭団体が幾つか報道されている。ＩＭＦや、一方ではアルゼンチンの国内情勢もそういうような状況であるという情報があって、極めて流動的です。","id":"exchange-069"},{"speaker":"北野委員","kind":"質問","question":"アルゼンチン債の保有期間というのが、平成１５年と１７年ということで、まだありますね。そういう中ではまだ現状のまま現在は進めていく、世界の動向も含めて、このまま持っているというままなんか尋ねました。","respondent":"中尾根企画部長","answer":"その点に関して私のほうもどうなのかと考えています。お金が入らないなら入らなかったときに、その欠損額が確定する、こういうことになります。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問・要望","question":"今日でなくてもいいですから、予算特別委員会での審査の過程もあるわけですから、その時点で分かるようにしていただきたい。だから確認書を取るということだというもの。","respondent":"中尾根企画部長","answer":"それから、国債、そういったことの幅広い検討はした。国の債券ということで一定の格付けはついていたし、できるだけ安定するはずだという、そういう考え方だったです。","id":"exchange-071"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは別に不都合な話でないわけですから、その当時の資料を調べれば出てくる話ですから、それを調べてほしいと求めました。格付けがどうで、流通量がどうだ、そこまで調査しなければ調査のうちに入らないでしょうということを言っているわけです。","respondent":"中尾根企画部長","answer":"私どもも資料を持ってお答えできるものがありませんので、この点については、購入して分かる範囲で調査をさせていただきたい。分かった時点で、先ほどの１,９００億円のアルゼンチン債の問題と一緒に提出させていただきたいと思います。","id":"exchange-072"},{"speaker":"林（宏）委員","kind":"質問","question":"基本的なところからお聞きしていきたいんだけれども、ファンドになるのは２種類あるということで、出資した基本財産は元本は使えないわけですね。それに対してそれぐらいに足りない分を補助金を付けていきますよという姿勢だと思うんだけれども、それについて考え方を説明するよう求めました。","respondent":"濱野助役","answer":"平成１０年度でしたか、たしか予算にもかなり満たなかったということがあって、こういう高利の利回りの債券を購入したのではないか。ちょっと質問とずれましたけれども、そういう形で果実を運用してきたというふうに理解しています。","id":"exchange-073"},{"speaker":"林（宏）委員","kind":"意見","question":"５億円で２,０００万円というと４％ぐらい必要になってくるわけですね。だから、そのぐらいのものは生むように努力せよという話が、区から財団のほうに伝わっていたということはありませんかとの意見を述べました。","respondent":"中尾根企画部長","answer":"財団の基本財産からの収益が減っているという認識は私どもも持ってはいましたが、２,０００万円は何とかしてくれとか、こういうものを言ったことはございません。","id":"exchange-074"},{"speaker":"林（宏）委員","kind":"質問","question":"そのような議論はされないんですか。予算をつくったり、決算をしたときに。","respondent":"中尾根企画部長","answer":"だから、認識はしておりましたけれども、ないしはこうあったらいいというルールの詰めは現実問題としては行っていないというのが実態です。そういう中で予算の査定をしてきたです。","id":"exchange-075"},{"speaker":"林（宏）委員","kind":"質問","question":"角度を変えて聞きます。どの役職の人ですか、寄附行為や処務規程にも出てこないんだけれども、だれができるということになっておりますか。","respondent":"中尾根企画部長","answer":"それで２,０００万円以上の契約をする場合は理事長決定、１００万円未満が課長決定で、その中間は事務局長。基本財産運用は、現実的には事務局長の権限、管理で行っております。","id":"exchange-076"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、財産運用についてのチームというのはないんですか。５％だ、６％だ」、運用の考え方は個人で決めていけるということか尋ねました。","respondent":"中尾根企画部長","answer":"問題は、そういうふうに規定をしているにもかかわらず、それをしていないです。どうなのかという議論をしていくという、制度的にはそういうことですけれども、運用上はそれをしていないです。","id":"exchange-077"},{"speaker":"林（宏）委員","kind":"質問","question":"例えば定期的に１週間に一遍、これだけのお金を動かすわけですからね。これだけのお金を動かすのに、どういう方法を用いてきたかというのは、毎年やるべきだ。","respondent":"中尾根企画部長","answer":"それを継続しようと、ほかの銀行にやろうと、理事会に諮れということになるんです。少なくとも文化振興事業団については、そういう判断のもとでやっていって間違いないんだという考え方に基づいてされたというのが、私どもの推測です。","id":"exchange-078"},{"speaker":"林（宏）委員","kind":"意見","question":"あるいは運用する前に理事会の承認をもらうという形ができているけれども、極論からすると、この４億７,０００万円は区の金なんです。もう一回きちんと見直していくということの決意みたいなものを聞かしてほしいとの意見を述べました。","respondent":"濱野助役","answer":"区の財団の資金運用について報告を継続的に求める、あるいは出捐金の用途についてチェックしていくということが必要だと言っております。これは委員のご指摘のとおりにして、私たちも改善をしていかなければならないと思います。","id":"exchange-079"},{"speaker":"三上委員","kind":"質問・要望","question":"１人で物事を行うということの危険性というのはこういう形で表れてきたのかなという感じがいたします。継続されてきているわけですから、それはまた考え方が変わってくると思いますけれども、そこらあたりのところをお聞かせいただきたいんです。","respondent":"濱野助役","answer":"理事会を開催する前に預金として適正金が入っていて、そして登記をして理事会を開くというような手順だったのではないかなと思います。満期がくれば、それを継続していくというような、そういう程度の決裁であったと思います。","id":"exchange-080"},{"speaker":"三上委員","kind":"質問","question":"品川区はそういう意味でも東京都との絡みは全くないということなのか。それについてのどの程度東京都から是正命令、指導とか、そういう部分というのはすでにガンガンきている部分というのはあるんか尋ねました。","respondent":"中尾根企画部長","answer":"監督官庁の都との関係では、それは許可されている財団と都との間でやりますから、区はその間に介入するということはありません。それについてお答えはしていますが、その結果どういうような指摘、ないしはお話があるのかというふうに思っております。","id":"exchange-081"},{"speaker":"三上委員","kind":"質問","question":"新年度予算をやっている、そこらあたりが修正されているのかどうかわかりませんけれども、そこらあたりの動きというのはどうなんでしょうか。１年間の事業団の事業の影響というのは当然起きてくるだろうと思うんです。","respondent":"濱野助役","answer":"財団の来年度予算では、基本財産収入を２００万円近く減額をしているんじゃないかと思います。幾つかそれに対応する事業の縮小なり、あるいは仕事の縮小というのは、予算の中で出ております。","id":"exchange-082"},{"speaker":"三上委員","kind":"意見","question":"あくまでもマイナスはマイナスという中から、事業運営をやらないんだと。区民の理解は得られていくわけはないと私は思っておりますので、その点よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"宮崎委員","kind":"質問","question":"今までの説明ですと、そこのところは今後どういうふうに反映するのかというのがわからないので、そこの考え方をお聞かせほしいと求めました。事務局長、当事者の調査はどういう形でやられたのか、ここのところを改めてお聞きしたいと思います。","respondent":"中尾根企画部長","answer":"１番目の、その当時アルゼンチン債についてはＢＢの格付けであったとしても、それは大丈夫だと判断して購入した。そのとおり私どもで答弁をしていますので、別にその点は私が推測して言っているわけでなくて、そういうことです。","id":"exchange-084"},{"speaker":"宮崎委員","kind":"意見","question":"例えば事実経過のところで、より有利な資金運用を図るためというふうに言っておりますけれども、図ることをしなければいけなかったというのは、どういうふうに言っていますかとの意見を述べました。","respondent":"中尾根企画部長","answer":"八年頃から極端に少なくなって、設立当時よりも財産運用の足を引っ張って、きつくなった。そのことを認識されているんだというふうに思ってあります。","id":"exchange-085"},{"speaker":"宮崎委員","kind":"意見","question":"そのときに前副理事長が、こっちのほうにしか手が出せなかったというのは、何かあるのか。そこのところは何か言っていますかとの意見を述べました。","respondent":"濱野助役","answer":"それがなくなったから補助をくれという、そういうことではないと思います。基本財産収入が減った、したがって，区のほうが補助金を云々という、そういう関係にはないというふうに思っております。","id":"exchange-086"},{"speaker":"宮崎委員","kind":"質問・要望","question":"当事者、先ほどのマージンの差額の問題が出ておりましたけれども、ここのところは調査されたのかどうか。そこのところをお聞かせほしいと求めました。","respondent":"中尾根企画部長","answer":"ただ、それはお聞きして、そういうことには確認をしただけで、別に司法でもないですから、どうだというそれ以上の調査はできません。大きくできるのか、それぞれ事業団の中で一つの収入がないからといって、すべて補助金に結びつくんだという構造にはなっていないということです。","id":"exchange-087"},{"speaker":"田中委員","kind":"質問・要望","question":"お聞きしたいんですが、平成１３年８月８日に基本財産を運用財産に置き替えているというのは、なぜそういう置き替えをしたのか。よりデフォルト、８月８日の時点ではもうほぼそういう方向になりつつあるだろうという判断で、基本財産から運用財産に置き代えたんか尋ねました。","respondent":"中尾根企画部長","answer":"前段３点のご質問につきましては、私どももそういうふうに受け止めて、今後対応をしてまいりたいと思います。その他の運用財産として６,０００万円分を持っていたわけですけれども、この１億円の基本財産につきましては、そこで付け替え作業を行っているです。","id":"exchange-088"},{"speaker":"田中委員","kind":"質問","question":"２７日の報道で、８月８日の付け替えの作業を行いながらも、まだそこまで至らないという判断を踏んだんか尋ねました。","respondent":"濱野助役","answer":"ＩＭＦが一定の条件を付けて支援に乗り出すということで、政府もそれを受諾して、メモとしてはかなり確実です。明らかになったということで調査会をつくりましたけれども、時期としては、これはやむを得なかったのではないかというふうに思います。","id":"exchange-089"},{"speaker":"田中委員","kind":"質問","question":"事実経過の1)の、平成１３年春頃から国際的経済事情に変化が出始めたため、これはどういうことなんか尋ねました。","respondent":"中尾根企画部長","answer":"公金は当然ですけれども、そこをきちんと維持していくという物の考え方がないと財政運営はできませんので、そういうことも強く働いている。先ほど副理事長である助役がご説明しましたとおり、相場のそういう関係の中では、かなり割り込んでいる状況の中ではできない。","id":"exchange-090"},{"speaker":"田中委員","kind":"質問","question":"平成１３年１月にアルゼンチンでストライキが起きて、国債の評価がそこで下がったために、ある意味アルゼンチン債が売れない状況に至ってしまった。機会を見過ぎてしまったがために、７月の事件が起きた後の処理にならざるを得なかったということはどうなのか、その辺はどうか尋ねました。","respondent":"濱野助役","answer":"結果としては、そこをアルゼンチン自体で何とかＩＭＦの支援をきちんと受け入れていれば、それはまた違った結果になったのではないか。これは結果論でありますけれども、そういう感じを持っております。","id":"exchange-091"},{"speaker":"塚本委員","kind":"質問・要望","question":"もう一度基本的にどういう展開であったのか、基本財産というものはどういうところで、こうあるべきだとされたのか。穴があくのは同じなんですから、その行為の、どういう考え方でやったんだということをもう一度説明してほしいと求めました。","respondent":"濱野助役","answer":"これはご納得いただけないということについては、私どもこれ以上ご説明のしようがないんですが、そういう理由で付け替えたです。こういったものは、当面今年、来年すぐ必要になるというものではありませんので、そういう運用財産のほうに転換をしたです。","id":"exchange-092"},{"speaker":"塚本委員","kind":"質問","question":"なぜ付け替えを判断したということになっていない、もう一度説明を加えて、どういう判断をしたのかということをお願いいたします。あるいは事業を運営して利益を上げることを目的としていないわけですから、この財団は、そういうことが知りたい。","respondent":"中尾根企画部長","answer":"したがいまして、基本財産は、その財団、事業団の存続する一番基本的な財産であるという認識があります。これについては確実であるという１項を、それに照らし合わせると、原価を維持できない不安が十分ある。","id":"exchange-093"},{"speaker":"塚本委員","kind":"意見","question":"つまり、単純であったのではないかという心配がある。財団の運用というものの改善策の中で、その辺が課題ではないかというふうに思いますけれども、指摘をしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-094"},{"speaker":"宮崎委員","kind":"質問・要望","question":"新聞では、実際にはどういうふうに認識していたのかというのがちょっとわからないので、教えていただきたい。それを知って、どういうふうな対応をしたのか、そこら辺の事実関係を教えてほしいと求めました。","respondent":"中尾根企画部長","answer":"今話しましたので、ああいう認識だったろうというふうに思っております。これは１０月に交代しておりまして、その冬に事業団のほうからいろいろ説明されたときに、知ったということです。","id":"exchange-095"},{"speaker":"宮崎委員","kind":"質問","question":"平成１２年のときは見過ごしたというご説明があったんですけれども、平成１３年になると証券会社からの書類が添付されていたから気がついたと。そうすると、平成１２年のときには証券会社からの書類が添付されなかったということか尋ねました。","respondent":"中尾根企画部長","answer":"３月から５月までメキシコ、５月１７日に経済課の監査があったんですが、その監査のときにはそういうものがなかったです。特段に説明もなかったために、監査として分からなかったです。","id":"exchange-096"},{"speaker":"宮崎委員","kind":"確認","question":"確認したいんですけれども、平成１２年のときには書類が添付されていなかったというのは、債券そのものも添付されていなかったということですか。例えば資料の１７ページのアルゼンチン共和国債、これはＢ１とＢ２だよという格付けがあるということですけれども、どっちか尋ねました。","respondent":"中尾根企画部長","answer":"財団側の対応についても、その点については、結果としては購入しているというのは見過ごしているということです。その時点では購入しているという事実を確認していたです。","id":"exchange-097"},{"speaker":"宮崎委員","kind":"確認","question":"驚くような経過だなというふうに思ったんですけれども、それはそれで別に確認したいんですけれども、先ほど助役は、平成１２年の冬に知ったと。単に報告したというんですけれども、報告したのはいつだったのか。","respondent":"濱野助役","answer":"従前は高利回りのものを運用するというのが方針であったんだけれどもということで、２月の時点でのものは、たしか安全なものにしたと思います。したがって、満期の古いものについてはそういうものに切り替えていこうということで、方針を事務局長のほうに伝えました。","id":"exchange-098"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどアルゼンチンの国情についての、前副理事長はどういうふうに考えているかと質問をしたんですけれども、同じ質問で、助役は、当時はどういうふうにお考えになっておりましたか。","respondent":"濱野助役","answer":"これは満期到来まで持つのは難しいということで、一定の機会を捉えて処分すべきだという判断で、理事長に報告をしたところです。したがいまして、アルゼンチンについては、その時点では必ずしも良好な経済状態ではないというふうには感じておりました。","id":"exchange-099"},{"speaker":"土井副委員長","kind":"質問","question":"ここのところがあるものですから、すなわち実態は今までこの建前どおりにはやられていないというのがずっと続いていたということなんですね。そこら辺での流れとしては、そういうものというのは可能性はあるとお考えなのか、あるいは前の副理事長がどんなふうに思っていらっしゃったのか。","respondent":"中尾根企画部長","answer":"なお、定款の寄附行為の変更ということについては、どうしたらそういうことについてより良い会計処理方法があるのか検討はしてまいりますけれども。ただ、だれもが分かるような仕組みをきちんとつくらないと、今回のような問題になるという反省に立ってあります。","id":"exchange-100"},{"speaker":"林（宏）委員","kind":"質問","question":"今日のところは、皆さんからそれぞれ質疑があったわけですが、さらに続ける場合には、一般質問のフォローという手法もあると思いますが、委員長の運営のしかたにおまかせします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201900?Template=document&Id=1572#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":93286,"voices":250}},{"id":"h14-20020305-6","meetingId":"h14-cm03","date":"2002年3月5日","dateIso":"2002-03-05","committee":"区民委員会","time":"午前１０時０８分～午後２時２０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"金高委員","kind":"質問","question":"一つスペースがあいているのは、増設するからということなんですけれども、なぜあけておいたんですか。どうせつくるんなら、一緒につくってしまったほうが、需要の問題点も含めてと思うんですけれども、その辺はどうなんか尋ねました。","respondent":"宮地区民課長","answer":"炉の数ですが、当初の予定で、人口の予測、それから、高齢化率等を換算しまして、５区の需要等の中では、当分の間、８基でいけるということです。設備的には、全部想定して、煙突の部分も全部用意はしています。","id":"exchange-001"},{"speaker":"金高委員","kind":"意見","question":"待合室が８室になっていますけれども、増設したら、全部で１０になりますね。そうなったときに、時間調整をしながら使うんでしょうけれども、その辺のところの見通しというのはどんなもんなんでしょうねとの意見を述べました。","respondent":"宮地区民課長","answer":"ピクチャーレールと書いてある下のところに、待合室９と書いてあります。まだ全体にスペースの余裕がありますので、そういった意味では、そのときにあわせて間仕切りを変えられるようになっております。","id":"exchange-002"},{"speaker":"原委員","kind":"意見","question":"乗用車で行った場合は、どういう形で入れるのか。大森のほうから行った場合に左折して、あるいは、品川のほうから行ったときには右折してとなると思うんですねとの意見を述べました。","respondent":"小栗区民生活事業部長","answer":"第一京浜と環状７号線の交差点を通りますと、水道局と港湾局の縁を通りまして、入っていただく。こういうルートが一般的なルートかと思います。","id":"exchange-003"},{"speaker":"原委員","kind":"質問","question":"そうすると、大森のほうから、環状７号線で勝島橋のほうから入ってきて、左折できないんか尋ねました。","respondent":"小栗区民生活事業部長","answer":"環状７号線のところを切れないかという交渉をしましたところ、近距離なんで、間が切れないということで、どうしてもできないということです。こちらから入ってきたときには、やむを得ず、１回迂回をしていただくというルートになりますので、ご了解いただきたいと思います。","id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"今のアクセスですが、じゃあ、敷地内にバス停をつくるんですか、今の話だと。","respondent":"宮地区民課長","answer":"ただ、増発のほうは、何とか調整の余地があると聞いています。この真ん前につくるというのは、ちょっと難しいんではないかと、事務局のほうでは、そう話しております。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"特に我々は近接地ですから、もしつくってもらわないと、スタジアムのほうのバス停では遠くから来た人は困るんじゃないですか。今のコースで、ちょっと中に入ってもらえばいいだけのことなんだから、そういうことはできないんですかね。","respondent":"宮地区民課長","answer":"ただ、今までのやり取りの中のニュアンスで聞いていますと、新バス停は難しいということと、今あるバス停の中での増発と伺っています。もう一遍、そのあたりの話がどういうふうになっているか、皆様のご意見をまとめまして、伝えるようにいたします。","id":"exchange-006"},{"speaker":"本田委員","kind":"質問","question":"当然、どのぐらいの人が利用するかによると思うんですが、１日にバスを利用するであろう人たちの数を出しているのか、どのぐらい見ているのかにもよるんだと思うんですけれども、その辺はどうなんですか、予測は十分に計算しているんか尋ねました。","respondent":"宮地区民課長","answer":"このあたりはほとんど住宅地がありませんので、一番寄りついたところでも大井中央海浜公園あたりなんです。この需要を見ませんと、もう１回ちょっと事務局とも、利用者数をどういうふうに把握しているかという話を聞いてみたいと思います。","id":"exchange-007"},{"speaker":"本田委員","kind":"質問","question":"せっかくここは広い敷地なんですから、私は、敷地の中にバス停をつくって循環させたらどうなのかと思いますので、よろしくお願いしたいと思います。それから、隣の東側はまだ決まってないんか尋ねました。","respondent":"宮地区民課長","answer":"それから、右側の水道局用地は、水槽６ｔとポンプ場の建設の計画があります。今のところは、すぐに着工の予定ではないんですけれども、そういう計画になっているということです。","id":"exchange-008"},{"speaker":"本田委員","kind":"質問","question":"そうすると、この後はコンテナの倉庫みたいな格好で、しばらくは何年か使われるということなんか尋ねました。","respondent":"宮地区民課長","answer":"今の段階では、そういうことです。","id":"exchange-009"},{"speaker":"原委員","kind":"質問","question":"今の関連でいいですか、申しわけないんですが。バス停を使うのは、大田スタジアムのほかに、環状７号線のこちらにもバス停があるという話をしていましたね。","respondent":"小栗区民生活事業部長","answer":"その次が、モノレールの流通センター前なんです。ですから、流通センター前の人は、環状７号線を渡った角ですから、やはりここの横断歩道というと、ここだけですね。","id":"exchange-010"},{"speaker":"原委員","kind":"確認","question":"そうすると、環状７号線のほうには、流通センターまで行かないと特にバス停はないんですか。確認で申しわけないんですけど。","respondent":"小栗区民生活事業部長","answer":"一番近いのは、橋の上に流通センター前のバス停があるんですよ。ですから、そこで降りていただいて、この縁をぐるっと歩いていただいて、ここからお入りいただくという形になります。","id":"exchange-011"},{"speaker":"原委員","kind":"質問","question":"ここを真っ直ぐ渡れるように、横断歩道はつくれないんか尋ねました。","respondent":"小栗区民生活事業部長","answer":"横断歩道はないんですね、ここは。","id":"exchange-012"},{"speaker":"原委員","kind":"意見","question":"やはり、今のお話ですと、全然数字的なものはわからないというお話なんだけど、やはり建てればそれなりに利用は高まるはずですよね。これからまだ時間があるんだと思うので、交通アクセスをもうちょっとお考えほしいと求めましたねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"プラモデルを見ますと、煙突がないんですけれども、今の火葬の仕方を教えていただけますか。","respondent":"宮地区民課長","answer":"今は、都市ガスを使ってご遺体を火葬します。そのあたり、さらに詳しくはちょっとまた事務局に確認しますけれども、そういうやり方だそうです。","id":"exchange-014"},{"speaker":"菊地委員","kind":"意見","question":"夜に行ったことがないのでよくわからないんですけれども、周辺部分の照明についてはどう考えていられるのかとの意見を述べました。","respondent":"宮地区民課長","answer":"ここは歩行者がほとんどありませんので、工事がこれから入るところですので、少なくともここの区画にはまったくありません。これから、全体の歩行の運線等を含めまして、考えていくということです。","id":"exchange-015"},{"speaker":"堺委員","kind":"確認","question":"確認をしておきたいんですが、昨年１２月２６日の区民委員会でも、どうか。たしかあのとき、平成１４年５月着工、平成１６年４月供用開始という説明だったと思うんですが、その辺をまずお尋ねします。","respondent":"宮地区民課長","answer":"工期ですが、ただいまのところは、６月着工を予定しています。予定どおり、平成１６年４月にはオープンということになっております。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問・要望","question":"２年後に完成するに当たって、こういうところによく出入りする業者と言っていいんですか、そういう業者の選定というのもこれからなんですか。その辺のことはどう決まるんか尋ねました。","respondent":"宮地区民課長","answer":"運営につきましては、ちょうどこれから５区の課長会、部長会等の中で検討しているというところです。基本は直営方針ではなくて、個々の業者をどう選んでいくのかというのは、ちょうどこれからということです。","id":"exchange-017"},{"speaker":"堺委員","kind":"質問","question":"５区で共同してやる関係ですから、５区の中のいろいろな業者の人たちも、それぞれうちを使ってくれということがあるでしょう。これからの検討ということなんですが、参考までにちょっと、イメージがあるかどうか。","respondent":"宮地区民課長","answer":"そこら辺もそれぞれのやり方を出して、メリット、デメリットを挙げて検討していくという段取りになろうかと思います。おおむね、今年の９月ぐらいまでには固めていきたいとは、事務局から聞いております。","id":"exchange-018"},{"speaker":"堺委員","kind":"質問","question":"９月ぐらいということは、ここの料金についても、その時期には出ますという考え方でよろしいんか尋ねました。","respondent":"宮地区民課長","answer":"運営に関して、大体、そのスケジュールでということですので、使用料を含めまして、委託の方法とか詰めていく予定になっております。","id":"exchange-019"},{"speaker":"堺委員","kind":"質問","question":"そうすると、利用料については、まだそれ以降ですか。供用開始直前にならないと、料金設定は出ないんか尋ねました。","respondent":"宮地区民課長","answer":"委託をする方法にもよりますし、どういった形で運営するかにもよりますので、全部一括して、大体９月までです。ですから、使用料も含めましてです。","id":"exchange-020"},{"speaker":"石田副委員長","kind":"質問","question":"２年に１回来るかとかいうことで、しょっちゅう行くところではないわけですから、そこら辺はどうお考えなのかというのが１点です。年に１回来るかどうかわからないような場所ですから、よく地方のほうに行くと、ここは入口だとかいう大きい看板が立っている。","respondent":"宮地区民課長","answer":"霊柩車等の回り方を考えますと、それにつきましては、専門的に事務局のほうで検討していると聞いています。基本的には６人乗りということで考えていますから、こちらのほうも、仕出し関係の業者の使い勝手も考えて設置しているということです。","id":"exchange-021"},{"speaker":"菊地委員","kind":"質問","question":"一つだけ。少なくなるんでしょうけど、その辺の配置の状況で、今考えていらっしゃるところを教えてほしいと求めました。","respondent":"宮地区民課長","answer":"６月の繁忙期には、窓口を５時までやっていますと、その中での対応という形になります。かえってマイナス面も出てきますので、効率的なやり方を、この３カ月間ぐらいを試行期間としてやっていきたいです。","id":"exchange-022"},{"speaker":"原委員","kind":"確認","question":"一つ確認だけさせてください。あの場所なのか、要するにどこを考えていらっしゃるんか尋ねました。","respondent":"宮地区民課長","answer":"原委員の言われた、休日、夜間受付窓口というのが防災センター２階のところにありますが、それはそれで従来どおりです。ただ、毎週火曜日には、正面から入って、それぞれ昼間やっている課のところに行っていただければ、そこでの受付けができますという話です。","id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"正面玄関を開ける形をとるのか、あるいは、出入口をつくらなきゃいけませんよね。それと、ほかの警備上の問題もいろいろ入ってくるんじゃないかと思うんですけど、その辺はどういうふうに考えていらっしゃるんか尋ねました。","respondent":"宮地区民課長","answer":"警備の関係にも係わってきますので、３階でしたら３階の戸籍住民課はやっているとか、ご案内にできるようにスタッフがつくということになります。同じく第１、２、３火曜日とセッティングしたものです。","id":"exchange-024"},{"speaker":"南委員長","kind":"確認","question":"ないようなので、私も確認したいんですけれども、３階から入ってということですが、税務課と保険年金課はカウンターが４階ですよね。それから、今の説明でちょっとよくわからなかったんですけれども、第３、４火曜日は、今までも夜間は残っていたんか尋ねました。","respondent":"宮地区民課長","answer":"４火曜日にやっている状況を見まして、これまでも庁内を歩き回るという例はなかったと考えていますので、おおむね大丈夫だろうということです。ただ、いずれにしましても、これは初めてのやり方ですので、やはり、しっかり見て、今後の対応を考えていきたいと考えております。","id":"exchange-025"},{"speaker":"本田委員","kind":"質問","question":"他区は他区の中でやっているのかどうなのか。品川区内の医療機関のみ、委任払いという新しい方式なんですが、他区でもできればなお結構なんだけれども、その辺はなぜできないんか尋ねました。","respondent":"太田保険年金課長","answer":"区についても、先ほど申し上げましたように、昨年４月から一定の所得基準がありますけれども、そのもとで貸付制度は実施をしてきてあります。","id":"exchange-026"},{"speaker":"本田委員","kind":"質問","question":"わかりました。東京都の場合多いわけですから、何かの機会にその辺の話は詰めていただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"原委員","kind":"質問・要望","question":"そうすると、現実に、退院時にその金額を引いてオーバー分を払うという形ですか。そうすると、組織については、そういった得点は使えないということになってしまうんか尋ねました。","respondent":"太田保険年金課長","answer":"区内の子育て支援、あるいは大学病院等のご協力を得て実施するものですので、区内の保険医療機関ということで限定をします。なお、先ほど申し上げました区外で出産される場合には、貸付制度というものもありますので、そういう制度もご案内をしていきたいと考えております。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"２７万円でも、申請した方が１００％借りられるんですか。金額じゃなくて、人数的に申請した方は１００％借りられるんか尋ねました。","respondent":"太田保険年金課長","answer":"先ほど申し上げましたように、一定の所得基準というものを設定していますが、その資格要件に該当すれば、貸付けは１００％ということが言えるかと思います。","id":"exchange-029"},{"speaker":"堺委員","kind":"提案","question":"私は、昨年の第３回定例会の一般質問のときに、この委任払いについて提案させていただいた記憶があります。ですから、その辺も検討を加えて、よりわかりやすい周知の方法ということでお願いしたいと思うんですが、いかがか尋ねました。","respondent":"太田保険年金課長","answer":"進めているところですので、当面は、それで対応していきたいと思います。「国保だより」の中で知らせる場合には、委員の趣旨を踏まえて、わかりやすい形でＰＲを継続的に実施をしていきたいと考えています。","id":"exchange-030"},{"speaker":"堺委員","kind":"確認","question":"既にもらっている人にも、ということでいいんですか。その辺はどうなんか尋ねました。","respondent":"太田保険年金課長","answer":"ご指摘の方の部分については、病院のほうと、来週に最終打合せをする予定です。病院のほうに、今、お手元に配付しているチラシと申請書一式、それから、病院の窓口にポスターを掲示していただくように準備をしています。","id":"exchange-031"},{"speaker":"堺委員","kind":"質問","question":"そうすると、何らかの形で、対象となる人については伝わるようになりますと理解していいんか尋ねました。","respondent":"太田保険年金課長","answer":"４月に入ったときに、大変小さいんですけれども、そういったものも一緒に入れて送付をする予定です。正確に伝わるのはちょっと難しいかなと思いますけれども、制度がスタートするということについては、わかっていただけると思います。","id":"exchange-032"},{"speaker":"堺委員","kind":"意見","question":"ほんとうに、心配ないように受け取れたんで安心しているんですが、漏れのないように、みんなにわかりやすくきちっと伝わるように、ぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"石田副委員長","kind":"質問","question":"括弧で「６カ月未満の場合は、２カ月ぐらい前に品川区で国民健康保険にぽんと入った場合には、これは認められるということですか。６カ月未満の場合は、他の健康保険から分娩費が支給されていない方はいいということですよね、これは。","respondent":"太田保険年金課長","answer":"退職されて、加入期間が６カ月未満であれば、前に入っていた社会保険から出産費が出るんで支給はされませんという部分を言っているところです。委員、ご指摘の部分の、里帰りをして、その期間だけ国民健康保険に加入という……。","id":"exchange-034"},{"speaker":"石田副委員長","kind":"質問","question":"もう１点変なうがった見方をしたいんですけれども、認めという意味合いで、何でもいいですと。法律的にこれはだめだとか、そういうところがあるんですか、現実的に。","respondent":"太田保険年金課長","answer":"今、社会通念上、委員のご指摘の部分はあろうかと思いますが、通常、私どもでシャチハタではなかなか難しいだろうと。それと、会計処理の段階で、シャチハタはまだ認められてないという状況かと思います。","id":"exchange-035"},{"speaker":"石田副委員長","kind":"質問","question":"それというのは、何か法的根拠というのがあるんか尋ねました。","respondent":"小栗区民生活事業部長","answer":"継続的に判の確認がまずできないということで、品川区では、シャチハタは認めてないということです。そういった一環で、間違って使うといけませんので、あえて、シャチハタはご遠慮いただきたいということでＰＲさせていただているところです。","id":"exchange-036"},{"speaker":"菊地委員","kind":"質問","question":"１点だけお伺いしたいんですけれども、これは評価の結論ということで、東京二十三区清掃一部事務組合から出されてきている。それとも、同じところが事後調査もやるのか、ちょっとそこを。","respondent":"金井環境課長、中山清掃リサイクル課長","answer":"基本的には、環境影響評価、見解書、住民の意見、あるいは評価書としていろいろ自治体の意見も入れてつくってきた事業者が、事後も責任を持ってやるということになっています。事業の考え方を、平成１７年度末を目途に、東京二十三区清掃一部事務組合から各区の地域処理を予定しています。","id":"exchange-037"},{"speaker":"菊地委員","kind":"質問","question":"違っていた部分とか、内容的にも、皆さんに人体に大きな影響を与えませんという部分が明確になるような事後調査であってほしいと思うんです。これは質問じゃないですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"本田委員","kind":"質問・要望","question":"万一延期というようなことになりますと、どういう責任体制でこの事業が執行されていくのかというのが１点。当議会でいろいろ議論をしたわけですので、具体的にどういうふうに最終効果のところで取り入れられているのか、教えてほしいと求めました。","respondent":"中山清掃リサイクル課長、金井環境課長、野本環境清掃事業部長","answer":"平成１４年９月の着工予定から計算しますと、ちょうど４２カ月目が平成１８年３月、平成１７年度末という計画になります。地域処理の検討の中で、再度… どういう内容のものをつくっていますかというのは、ずっと説明をされています。私のほうで細かく説明させていただきたいと思いますが、私どもの意見として… こういう格好で対応しているんで問題ないと認識しているとかになっていますので、見解書のほうでご説明をすべきかなと思いますので、必要があれば。","id":"exchange-039"},{"speaker":"本田委員","kind":"質問・要望","question":"話を伺えば難しいですから、事後評価との関係が大事ですから、それはいただきたいなとほんとうに思っております。委員会としていただければ一番いいと思いますので、そういうことでお願いしたいと思いますが、いかがか尋ねました。","respondent":"中山清掃リサイクル課長、金井環境課長","answer":"今回の地域処理の枠組みの検討を踏まえて、どのようにこれを２３区で負担、継承していくかという検討がされます。どういうフレームでどうなっていくかというのは、正直言って、まだ来年度以降に検討していくことです。 委員会として、全員のご要望があれば、その分をお出ししますし、希望者だけということであれば、それなりの配慮をします。いずれにしても、何ら拒否するものではございませんので、言っていただければ、私どもは提出します。","id":"exchange-040"},{"speaker":"本田委員","kind":"質問・要望","question":"区レベルで執行されていくということが一番大事なわけですから、十分、そこのところは円滑に対処してほしいと求めました。皆さんがいただくということであれば、皆さんがいただくということで、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"石田副委員長","kind":"確認","question":"すみません、今の確認だけさせてください。だから、そのことがおくれることによって、解散までがおくれてしまうという判断はないと思うんですけれども、そういう判断でいいのか。","respondent":"野本環境清掃事業部長","answer":"今、清掃リサイクル課長が答えたのは一部真理だろうと思うのは、なぜかというと、１５％というのがありますよね。そういうような意味で、清掃リサイクル課長がお答えしたんだとご理解いただければ、ありがたいと思います。","id":"exchange-042"},{"speaker":"石田副委員長","kind":"質問","question":"１点だけ、４００m2というのは、もう東京都の議会が始まっていますよね。その中で出てきた動きとか、そういうのを何か把握されているんか尋ねました。","respondent":"松崎税務課長","answer":"おそらく、東京都全体で２６０億円ぐらいの、この部分での減収になると言われています。おそらく私どもの区でも、調整三税の中の取り扱いがどうなるのかというのが大きなことになろうかと聞いてあります。","id":"exchange-043"},{"speaker":"石田副委員長","kind":"質問","question":"もう１点だけいいですか。今の２６０億円に対して、新聞だと１０９億円と書いてあって、どうお考えなんか尋ねました。","respondent":"松崎税務課長","answer":"財調の説明があったのが１月中のはずで、多分すべてで２６０億円で、財調で回ってくるのはそのうちの５８％ぐらい。それがこのとおり出るかどうかは、今後の推移を見なきゃわからないです。","id":"exchange-044"},{"speaker":"本田委員","kind":"質問","question":"これは何も３多摩だけじゃなくて、２３区だって、財調財源ですから、区のレベルにそれなりの相談があってしかるべきだと、私は思うんです。全く区には話がなかったんですか、今度は。","respondent":"松崎税務課長","answer":"１月３０日に税務課長会がございまして、その段階では、税務課長に対する財調の説明がございました。少なくともそのときに、東京都の行政局からの説明の中では、全くございませんでした。","id":"exchange-045"},{"speaker":"本田委員","kind":"質問","question":"自治体に大きな影響を及ぼす制限ですから、やはりこういう地方分権の時代ですから、これはやっぱり本筋を外れているんじゃないかなと思うんです。区のほうも、言うべきことはきちっと言ってもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"金高委員","kind":"意見","question":"現在、約２８、１０５店舗あるという数字なんです。あるいは、これは産業振興課で持っているのかどうかあれなんですけど、この金融機関がどうかというのがやっぱり出てくるような気がするんですけどねとの意見を述べました。","respondent":"市川産業振興課長","answer":"どう対応しているんだですけれども、収入役室のほうを通しまして、事務手続を進めてあります。特に私のほうで独自に、金融機関の情報を取っているということはございません。","id":"exchange-047"},{"speaker":"藤原委員","kind":"質問","question":"今、課長のご説明で、制度融資の大半は保証協会ということだったんですけど、言葉尻になっちゃうかもしれないんですけれども、大半じゃなくて。","respondent":"市川産業振興課長","answer":"残り４％については、保証協会を使われていないということは、保証人なり、物的担保なりを提供されて融資を受けている。推測ですけれども、信用金庫、信用組合の利用者については、それこそ大半、ほとんどが信用保証を利用されているという状況にあると見てあります。","id":"exchange-048"},{"speaker":"菊地委員","kind":"質問・要望","question":"パーセンテージが変わってくる、その辺についてよくわからないので、教えていただきたい。その中身というか、これをどういう形で決めてこられたかということを、お聞かせ願いたい。","respondent":"市川産業振興課長","answer":"ただ、ペイオフの影響を受けるかもしれないということで、預託金をそのものをペイオフとの関係でどうこうと考えたような経緯はございません。昨年４月、平成１３年度の預託金を預けるときに、注意をいたしました。","id":"exchange-049"},{"speaker":"菊地委員","kind":"意見","question":"実際に、区内の中小業者の方が借りようとすれば、信用金庫あたりが主体になるんだと思うんです。基本的には、自己資本比率で考えたときには、当然、都市銀行のほうが高いということですよね、単純に見たときにはとの意見を述べました。","respondent":"市川産業振興課長","answer":"いわゆる都市銀行に適用される自己資本比率のガイドラインと、信用金庫、信用組合に対するものは、８％と４％という違いがあります。ですから、都市銀行が必ずしも中小企業に対して冷たいとかいうのは、一概には言えないと思います。","id":"exchange-050"},{"speaker":"菊地委員","kind":"質問","question":"もう１点だけお願いしたいんです。例えば、きのうの審査でも、小さな数字ですけれども、あれを引き抜いたときの影響というのはどういうふうになるのか。","respondent":"市川産業振興課長","answer":"預かり総額がどのぐらいになっていてという、事業規模によって、影響の大小が出てまいります。ですから、一律にこうだということは申し上げられないところです。","id":"exchange-051"},{"speaker":"原委員","kind":"質問・要望","question":"せっかく、制度融資の話もされましたので、ちょっと現況だけ聞かせていただきたいんです。担保を増やしてくれとか、現状の中では、そういう話が来ていますか。","respondent":"市川産業振興課長","answer":"現に借りている中で、そういうことをされることがないというのが、制度の建前です。追加融資を受けるときには、ちょっとケース・バイ・ケースによって違ってくるということは、よく言われていることです。","id":"exchange-052"},{"speaker":"原委員","kind":"質問","question":"今、現状の中では、特にはそういったケースは出てきていないんか尋ねました。","respondent":"市川産業振興課長","answer":"私どもの制度融資の場合には、比較的融資を受けている金額が小さいということがありますので、委員がご指摘になるようなケースというのは、もう少し大きい案件でよく起こることだと思います。","id":"exchange-053"},{"speaker":"菊地委員","kind":"質問","question":"原委員が質問したところで、課長が言われた不良債権とか、そこでまたもう一度吟味をされるという形になるんですか。それとも、受け皿機関そのものが、不良債権は最初から受けないという感じになるんか尋ねました。","respondent":"市川産業振興課長","answer":"引き受け手のほうの銀行は、要は傷がついている債権はなるべく受けたくないということで、営業譲渡を受ける際に振り分けをいたします。これは不良債権だからといって国の債権回収機構のほうに、後から面倒を見てくれという形で回すことは、制度上ない話です。","id":"exchange-054"},{"speaker":"菊地委員","kind":"意見","question":"ということは、もし信用金庫なり、信用組合なりがつぶれて、その時点では通常に取り引きが行われていたものが、その時点で、不良だと判断されたときには、そこで一括返済なり何なりという、ＲＣＣに送られる状況というのが、形としてできちゃうわけですねとの意見を述べました。","respondent":"市川産業振興課長","answer":"ただ、いきなり一括返済を求められるかどうかというのは、債権回収機構といえども、一律の保証のもとですべて処理しているわけでございませんので。","id":"exchange-055"},{"speaker":"菊地委員","kind":"質問・要望","question":"ジャスコと、コウズのときにはそういう問題があれば、教えていただきたい。大井町駅周辺でこれを考えたときに、どういうものが想定できるのかというのを、ちょっと説明を求めました。","respondent":"市川産業振興課長","answer":"あそこはカード制になっていましたので、そういう意味で、会員の方の比率として説明を受けた経緯があります。商店街と大型店との連携、そういった意味で、大井町駅をお客様が回遊できるような商業集積といったものをひとつ目指していきたいなと考えております。","id":"exchange-056"},{"speaker":"菊地委員","kind":"意見","question":"集客装置としては、これらが考えられるということですが、では、回遊させるために新しい周辺の商店街の魅力づくりというのはどういうふうに。先ほど課長が言われたことのようなことだとは思いますけれども、今ある地域性をどう考えるのかとの意見を述べました。","respondent":"市川産業振興課長","answer":"それから大井銀座商店街といったものが、アーケードの改修等に、今まで取り組んでまいりました。まず商店街独自で取り組まなくちゃいけないはありますが、連携できるところは連携して取り組んでいこうという機運があると、私ども見てあります。","id":"exchange-057"},{"speaker":"石田副委員長","kind":"質問・要望","question":"そういう場所、場所に合った展開をぜひ図っていただいて、その中でやっていただきたい。１００人が１００人、こっちの方向でいいということはないわけですから、政策誘導的にやっていただければというのを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"南委員長","kind":"確認","question":"私から基本的なところをまず伺いたいと思っているんですが、そんなものなのかなと、ちょっとわからないんです。先ほど申し上げた１,０００m2以下のところが、そういう部分に入るのかどうかというのを、改めて確認しておきたかったんです。","respondent":"市川産業振興課長","answer":"説明の冒頭で、１,０００m2以下といっても、もともとが５００m2を超えている店舗ということです。ちょっと、一般としてどうだということは、なかなか言えない分野だと思います。","id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/345074?Template=document&Id=2320#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":53235,"voices":177}},{"id":"h14-20020305-7","meetingId":"h14-cm03","date":"2002年3月5日","dateIso":"2002-03-05","committee":"厚生委員会","time":"午前１０時０４分～午後２時２１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"サービス利用者の意思の確認、知的の障害者もいらっしゃるでしょうから、本当にその業者と結びたいかどうかわからない場合があります。何となく不安定になる気があるんですけれども、それはどうなっていくでしょうかという、その三つを説明するよう求めました。","respondent":"日下部障害者福祉課長","answer":"社会福祉法の中で、苦情に対する適切な対応ということも、これも支援費制度を進めていく上での重要なポイントになってまいります。これを新年度に策定していく予定になっておりますので、事業者自身の対応とあわせて、区のほうとしてもどう対応していったらいいのか。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"だから、その辺の整合性をどうとっていくかということで、今成年後見センターの話がありましたけれども、もう少し答弁をいただけませんでしょうか。もしくは契約になったわけですから、外に出た立場だから、考え方を改めて説明を求めました。","respondent":"日下部障害者福祉課長","answer":"先ほど申し上げました福祉サービスの利用についての支援の仕組み、より客観的な形で知的障害者の意思の確認がしっかりできるように進めていきたいと。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"例えば議会も間に入った、こういうふうなオンブズマン制度をつくってほしいとか、いろいろ要望が来ているんです。その措置から契約の制度移行を進めていっていただきますように、改めてお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須藤委員","kind":"確認","question":"意思の確認ということを非常に追いかけられているんですけれども、その辺の意思の確認ができない状況が知的障害者だろうと思うんで、そうすると。こういったサービスを加算しての対応をして、利用者のいろいろなニーズにこたえられるようにということですから、その辺についてはいかがか尋ねました。","respondent":"日下部障害者福祉課長、小沼福祉事業部長","answer":"区のほうとしての考え方ですけれども、その後のいろんな対応についても、やはり市町村がいろいろな形で関与をすることになります。直接の増大ではありませんけれども… これは従来の措置制度から支援費、そういうような言葉なり概念で説明されますけれども、保障だとか制度の変更がありましても。","id":"exchange-004"},{"speaker":"須藤委員","kind":"質問","question":"そのほうがいいのかどうかというのは、利用者の負担の支払いというのが増大してくる傾向はあるんですか。それとも、サービス自体が増大してくれば、それに伴って支払う形も増大するよという形になってくるのかどうか、その点を。","respondent":"日下部障害者福祉課長","answer":"結論から申し上げれば、国が明言しておりますのは、公費負担の水準は変えないと。ということは、具体的に利用者負担についても従来どおりの水準を、基本的には変えないということを明言しています。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一つは、これは具体的にどういうされ方で支給決定が行われていくのかということをお聞きしたいんですけど、ひとつ教えてほしいと求めました。先ほど言われていたところでは、そういう仕組みにはならないのかどうか、そのことについてとりあえず教えてほしいと求めました。","respondent":"日下部障害者福祉課長","answer":"最初に、地域福祉計画の策定に間するご質問ですけれども、これにつきましては１４年度中に策定をするということで予定をしております。全体の、地域での支え合いを中心にして、どう進めていったらいいのかといった意味での基盤の整備ということで具体的な検討を進めていきたいと。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういうふうな支給の人はここまでのサービスが受けられるとか，そういうふうなサービスの中身というか、例えば上限だとか、そういうふうなところまであるものなのかどうなのかをちょっと教えてほしいと求めました。","respondent":"日下部障害者福祉課長、小沼福祉事業部長","answer":"今考えられておりますのは、例えば２０時間とか３０時間とか、そこまで支給決定で決めていくと思うんです。見直しの目安が３年とか、在宅のサービスであれば１年だとか、このような形で一応市町村が決めていくということになります。 そこのところを分けて説明しないと、なかなかつかみにくいと思うんですが、施設サービスというのは３ページにあります。その辺のところの問題というのは、今後どういう形で整理するというか、対応するのかと。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"このサービスはこれぐらいまで、というふうな形で、決められた形で支給決定がされるということで理解していいんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"ご指摘のとおり、個別具体的に決めていくということになります。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、本人が選べるというのは、選択できるというのは、そこの、決められた中での業者の選択というふうな形になってくるんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"これは、本人のご希望、これを受けて、それに沿う形で支給の決定を進めていくと、そういうことです。何も本人の意向を全く度外視して決めていくとか、そういうことではございません。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、そこの本人が、支給の申請をした段階で区のほうが、ケアマネジャーじゃないけど、ケアプランのような形の役割を果たして、ある程度のサービスの中身もそこの場で相談をしながら、そして、じゃここら辺までという形で支給決定がされる、そういうふうな仕組みか尋ねました。","respondent":"日下部障害者福祉課長","answer":"ですから、一番大事なことは事前の相談ですよね。情報を提供していくという、事前のしっかりした、そういう体制づくりが重要だということで承知をしております。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区としては、今回の制度の変化で、メリットというのはどういうふうに考えられているかについてちょっとお聞かせいただきたいんです。今回の制度が変わることによってのメリット。","respondent":"日下部障害者福祉課長","answer":"これは１ページ、先ほどご説明をさせていただきましたけれども、それが反映された仕組みになっていると。その辺がある意味での一番の大きなメリットではないかと考えています。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうふうなところに対して考えられている部分があるのかどうなのかということを一つと、あと、世帯主の収入ということで考えていいんでしょうか。そこら辺のところを説明するよう求めました。","respondent":"日下部障害者福祉課長","answer":"１点目の、これについては東京都も、この制度の実施に向けてどうするかということで今検討が進められているです。ただ、どうしても本人が難しい場合に、補完的に扶養義務者がこれを負担すると。","id":"exchange-012"},{"speaker":"船波委員","kind":"質問","question":"今現在東京都から施設認可を受けているところは、自動的にというか、そのまま支援費制度でも指定を受けられるということになっているんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"実は、現行で今認可を受けているものは、そのままみなし指定ということで、その後は指定に移行するということになっています。","id":"exchange-013"},{"speaker":"船波委員","kind":"質問","question":"わかりました。その指定を受けるときに、どれくらいの広さがないとだめですよというような、基準は現行と変わらないレベルでいくんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"指定の基準につきましては、ついこの間、国のほうから、国としての基準が示されたですけれども、基本的にはいろいろ施設の規模であるとか、あるいは、それに応じた設備であるとか、運営の体制であるとか、そんなには大きく変わっていないということで承知をしております。","id":"exchange-014"},{"speaker":"船波委員","kind":"確認","question":"わかりました。もう一回確認のためにお伺いしたいんですけど、例えば、その内容は本人の気持ちを尊重して決定されるということか尋ねました。","respondent":"日下部障害者福祉課長","answer":"先ほどもちょっとご質問にありましたけれども、別に金額でそのサービスの提供を決めるわけではありません。それが適当であれば、その辺は変更も可能だと、そういう決定もできるというふうに思います。","id":"exchange-015"},{"speaker":"船波委員","kind":"質問","question":"その適当であればというのは、相談の段階で区の側と本人の側と相談してということか尋ねました。","respondent":"日下部障害者福祉課長","answer":"政省令という国の示した基準に基づいて、市町村が基準を決めます。ですから、その基準に合っていればサービスの変更も当然可能だということです。","id":"exchange-016"},{"speaker":"船波委員","kind":"質問","question":"すいません、なかなか理解力が及ばないようで、いつまでも聞いてしまって何ですけれども、では、その基準というのは、こういったレベルの障害者、あるいはその人といいますか状況を見れば、その人にはデイサービスがいいでしょうとか、そういった内容についての基準があるということなわけか尋ねました。","respondent":"小沼福祉事業部長","answer":"そういう作業は当然私どものほうで、あるいは関係者のほうでの話になっていくと思います。あるいは選択なりと、こういうふうな手続ということで、その基準なら基準の一つの考え方ということをご理解いただきたいと思います。","id":"exchange-017"},{"speaker":"船波委員","kind":"質問","question":"これくらいがいいだろうというものでしょうから、こうしたらどうですかと言われても、そういったケースはどうやって対応するんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"その辺の意見調整をちゃんとしっかりした上で、最後は基準に照らして一番適切と思われるサービスを提供すると、そういうことになってくる。そんなに私は、大きなそごが出てくるということはないんではないかと、このように考えます。","id":"exchange-018"},{"speaker":"嶋委員","kind":"質問","question":"障害者７団体への説明のことなんですが、やはり品川区内でも、この７団体に入っていない障害者の方のほうが大変多いと思います。そういう方たちへの、いわゆる広報、啓発というのは、どのような方法でされていかれるのか、お聞きしたいと思います。","respondent":"日下部障害者福祉課長","answer":"支援費制度の導入、いろいろと作業もふえてまいりますけど、基本的には現在の体制で進めてまいりたいと。既に７団体の皆さん方には、制度のあらましについては、２度ほどご説明をさせていただきました。","id":"exchange-019"},{"speaker":"嶋委員","kind":"質問","question":"１回で流れてしまってリピートされていない部分があったりとか、１回では聞き逃してしまうことが大変あるようです、今までも。受ける前の１日からスタートしますが、３月だったら３月の初めにいろんな予定が入ってしまったという場合なんかは、そういうのはあるんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"期限を切るという意味ではありませんので、そういう一つの目安ですので、ご理解をいただきたいということです。これから建設に入ってまいりますし、そういうことで区のほうとしても努力をしてまいりたいと、このように考えます。","id":"exchange-020"},{"speaker":"嶋委員","kind":"質問","question":"最後の、この申請なんですが、やはり今までどおり、窓口に来て申請をしなくてはならないのか尋ねました。","respondent":"日下部障害者福祉課長","answer":"基本的には窓口に来ていただくということで考えています。いろいろなご意向とか、そういう前提の上に立って申請をいただくという点からしますと、やはり窓口に来ていただくということになろうかと思います。","id":"exchange-021"},{"speaker":"鶴副委員長","kind":"質問","question":"平成１５年の４月から移行するというのが大きな特徴だろうというふうに思うんですが、今回の、どういうふうに把握をされていらっしゃるでしょうか。把握というのは、どういうふうにとらえて、こういうことで不安を持っていらっしゃるというふうに担当課としては考えていらっしゃるか尋ねました。","respondent":"日下部障害者福祉課長","answer":"関係者の不安ですけれども、先ほどもご説明させていただきましたけれども、準備の期間が非常に短いと。そうは言っても、基本になるものがなかなか出てこない、その辺が今一番不安なところです。","id":"exchange-022"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"その事業者が、障害者が求めるサービスにこたえるだけのサービスを提供する事業者であればいいなというふうに思うんですが、障害者の団体の方々は。向上、アップというのは、どこがやっていくべきだというふうにお考えになっていらっしゃいますか。","respondent":"日下部障害者福祉課長","answer":"西大井の６丁目の施設建設も含めまして、やるべきことはやっぱり、しっかりサービスの拡充に向けてやっていきたいというふうに考えております。それから事業者が、それぞれの立場でサービスの拡充ができるように努力をしていきたいと、このように考えております。","id":"exchange-023"},{"speaker":"鶴副委員長","kind":"意見","question":"もう１年ちょっとしかない段階で、例えば負担につきましても、こういうような示唆があるのではないかというふうに思うんですね。その点はどうなっていますかとの意見を述べました。","respondent":"日下部障害者福祉課長","answer":"所得にかかわらずサービスが受けられる、それから、公費負担の水準については維持すると。前提の考え方、準備を進めていきたいと、このように考えております。","id":"exchange-024"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"どこに負担能力の判断を求めるかということについて、それから、おのずと負担能力の判定方法が異なってくるというふうに思います。要するに、施設サービス本人は、前年度の所得という、扶養家族も前年の所得税額によって負担の割合が現行では行われているんじゃなかったか尋ねました。","respondent":"日下部障害者福祉課長","answer":"一定の金額を控除した所得税額相当分、これに応じた形で負担をすると、そういう仕組みになっております。","id":"exchange-025"},{"speaker":"鶴副委員長","kind":"質問","question":"あるいはその扶養義務者についても、所得税等による認定方式がいいのではないかと、こういうふうに言われてありますね。どういうお考えでやられたんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"副委員長がご指摘になったような方向で検討が進められているというふうに、このまま継続をしていくということが望ましいのではないかと、このように考えています。","id":"exchange-026"},{"speaker":"鶴副委員長","kind":"意見","question":"品川区としてはどうするのかという点。あればいいんですけれども、考え方はどうでしょう、基本的にとの意見を述べました。","respondent":"日下部障害者福祉課長","answer":"実はケアマネジメントのいろんな研修なんかも、これは昨年からですか、進められております。ケアマネジメントの基本的な考え方を、できるだけ反映できるような、そういう形で取り組んでいきたいというふうに思います。","id":"exchange-027"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"それはもう、広域的な領域でサービスを受けなきゃいけないというような、あるいは遠方になってしまうというようなことも出てくる。３,３００自治体の中でも、一層の工夫と努力をしていただきたいなと、いかがでございましょうか。","respondent":"小沼福祉事業部長","answer":"やっぱり広げていきたいと、こういうふうな形で臨むつもりでおりますので、よろしくご理解のほどをお願いできればと思います。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その対象者の人数について一つ教えていただきたいのと、そこの相談に応じる方の資格ですとか、その体制というものはどういう状況になっているかということを教えていただきたい。","respondent":"日下部障害者福祉課長","answer":"ですから、このケースワーカーを中心にして相談に対応していくということで考えております。この職員については、そういう形で相談への体制をつくってまいりたい、このように考えております。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これから委員会の中に最低こういうふうな形で報告をされていくということでわかっているところがありましたら、具体的に時期と内容というところで、ありましたら教えてほしいと求めました。","respondent":"日下部障害者福祉課長","answer":"委員会の報告についての具体的な手順については考えてはございませんけれども、ただ、先ほど申し上げました、国とのいろいろ兼ね合いもありますけれども、今後準備が進んでいきますので、それに応じて適宜適切にご報告をするということで、考えております。","id":"exchange-030"},{"speaker":"嶋委員","kind":"意見","question":"今の近隣住民に対する説明ということの４番目の工事車両の通行なんですが、ここも周りが大変道幅が狭い、立会道路ぐらいなんです。実は今、なるべくそこの道路を使う方たちに迷惑がかからないようにしていただけたらと思いますので、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"鶴副委員長","kind":"意見","question":"かんべ土地のほうの駐車場のほうと、今までの中庭に相当するところの樹木というのは、どういう運命になりますか。消滅してしまうのか、移設できるものは移設するのかという点ですとの意見を述べました。","respondent":"日下部障害者福祉課長","answer":"その辺も含めて、３月中に実施設計の中で設計業者、その辺も含めて調整していくという予定になっております。最大限緑は生かしていきたい、こういうふうに考えております。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この３０名の対象というのがどのように考えられているのかについてお聞かせいただきたいんですけれども、重度の方が入れるのかどうなのかということで、そこら辺の知的障害者の方の３０名の対象者について説明を求めました。","respondent":"日下部障害者福祉課長","answer":"この入所施設といいますのは、正式に申し上げますと、知的障害者の入所更生施設ということになっておりまして、そういった意味で、比較的重い知的障害をお持ちの方が入所するということで考えております。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、車いすで重度の方とかもこの対象になるということで考えられるんでしょうか。１６年の４月から入居開始というふうなことで、これはいつぐらいにどういう形で、この対象の方が決まっていくのかについて説明を求めました。","respondent":"日下部障害者福祉課長","answer":"それから、入居の開始が１６年４月になりますから、そういうものは１５年度には行っていくということになると思います。そういうことで予定しております。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"お聞きしているんですが、そういう方の施設というものの計画についてはどう考えられているかについて、説明を求めました。","respondent":"日下部障害者福祉課長","answer":"まさしく車いすをお使いになる重度の重複の方も含めて、品川の総合福祉センターさつき園、そちらがあります。比較的柔軟な対応もしておりますので、それぞれの状況に応じて適切な施設で対応できるように、今私ども今努力をしているです。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"意見","question":"２階の平面図ですが、都営住宅のエレベーターが２階にはとまらないというのを、もう一回言いましょうか。例えば２階で災害が起きた場合にこのエレベーターを使って避難するときに、その辺の考え方についてお聞かせいただければありがたいんですがとの意見を述べました。","respondent":"日下部障害者福祉課長","answer":"一応今回の設計に当たっての前提の考え方は、エレベーターも含めて、それは分離をするという前提で考えています。施設の場合は２方向避難と言われていますけれども、そういうことで対応できるような仕組みになっています。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"質問","question":"平常時はとまらないようにしておいて、非常時に２階にとまれるような仕組みも、エレベーターの操作で簡単にできる話ですよね。万が一の場合には使えるような仕組みを考えていったらどうですかということを言っておりますので、その辺の検討はいかがか尋ねました。","respondent":"日下部障害者福祉課長","answer":"今の緊急時の対応ということで、実は施設の設計に関しましては、私も今回携わってわかったんですが、いろいろ法的な制約条件とかがあります。ということで、今のご指摘を受けまして設計業者のほうにも当たってみたいと思います。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区営住宅のところで、障害者住宅が４戸ありますけれども、ここのところは非常時に車いすで避難できるようなスロープというか、そういうふうな避難路みたいなのは入っているのかどうか説明を求めました。","respondent":"日下部障害者福祉課長","answer":"こちらにつきましては、特にスロープとかそういうものは設けてございません。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"車いすの方も入れるようにということで全部設計されていると先ほどご説明がありましたけど、非常時の避難についてはどういうふうにとの意見を述べました。","respondent":"日下部障害者福祉課長","answer":"車いす専用ということになりますと、いろいろ条件が厳しくなりまして、例えば原則１階とか、いろいろ制約条件も出てまいります。エレベーターが使えれば当然エレベーターを使いますけれども、あとは避難階段をご利用いただくという形にならざるを得ないのではないかと思います。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ障害者の方が安全に避難できるような体制を検討してつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"土曜日をもっと開いてほしいという要望が障害者の方から出されていたのか、そこら辺の理由について１点お聞きしたいのと。もう一つは、委員会のほうには報告がされるということはきちんとしていただくということになるのかどうか、そこのところを３点説明を求めました。","respondent":"日下部障害者福祉課長","answer":"それから、支援費の制度に変わりましてもこの辺の基本的な仕組みは変わらないのではないかというようなことも言われております。ですから、基本的には現行どおりの仕組みがそのまま継続できるのではないかと考えております。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"なぜ社会福祉協議会なのかというのが一つわからないのと、それからさっきの知的障害者の、支援費制度と組み合わせて使う場合ですよね。このことについては向こうに申し込みということになっていくのかどうかを教えていただきたいんですけど。","respondent":"日下部障害者福祉課長","answer":"それから、支援費との関係ですけれども、これはあくまでもサービスの組み合わせということになります。は日時とかその内容が折り合うかどうかということで、電話の調整が中心になりますので、その辺のご心配は要らないというふうに思います。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"知的障害者のことで言えば、申し込みの時点で区に来た上に、なおかつ向こうにも行かなきゃいけないのかと。今までだったら区の窓口１カ所で全部済んでいたものが、なおかつ向こうにも行かなきゃいけないのかということがあるのかなと思うんですけれどもとの意見を述べました。","respondent":"日下部障害者福祉課長","answer":"支援費に関しましても、そんなに頻繁にこちらの窓口、私どもとしましてはそういう形での心配はしておりません。土曜日の窓口での対応とか、そちらのウエートのほうが高くなるんではないか、このように判断をしております。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は頻繁にということではなくて、そのときにこちらにも来、一つの窓口で全部対応できるようにということもぜひ考えていただきたいなと思います。今後こういうふうな形でほかに窓口を移していくということが、例えばほかの事業で考えられることがあるのかどうか、ちょっと説明を求めました。","respondent":"日下部障害者福祉課長","answer":"今回は、先ほど申し上げました、できるだけ身近なところで対応できるようにということも含めて、こういう形で移行することになりました。ということで、当面はこの３事業について移行するということで進めてまいりたい、このように考えています。","id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今、こういうふうなところも区民がどんどん区のかかわるところが見えなくなっちゃうというのがあるんじゃないかと思うんです。区民が見えるというところ、障害者の方が直接見えるというところからもぜひ区でやるべき事業なんではないかなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"鶴副委員長","kind":"質問","question":"より便利で利用しやすいサービスということで社会福祉協議会ということに、この三つの事業を移行するということでございました。ところで、この申請に当たって、電子申請というのはどうなのか尋ねました。","respondent":"日下部障害者福祉課長","answer":"電子申請ですけれども、時代の流れもありますし、そういった意味ではこの電子申請ですか、いずれはこの辺を導入する形になろうかと思います。今年の４月の時点では、基本的にはそういうことで、準備が整えば電子申請ができるように進めていきたいと考えています。","id":"exchange-046"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"この仕組みを教えていただけませんか。これはどういうふうになるのか。","respondent":"日下部障害者福祉課長","answer":"そうすると、５年後にもう一度再交付ということになります。特段、最初に交付させていただいてから５年以上たっているか、そういう形で簡単に交付をさせていただけるような仕組みになっております。","id":"exchange-047"},{"speaker":"鶴副委員長","kind":"質問","question":"その承諾書みたいなのをもらったら、認知証というんでしょうかね。そしてつえを借り受けると、こういう仕組みになっているんではないですかね。","respondent":"高橋総務部副参事","answer":"これにつきましては、区の補助金とかそういうことではなくて、私どもの会費等で運営しています。７５歳以上の高齢者で虚弱ということで歩けない方、民生委員さんが私どもの窓口に来て、ご自宅までお届けするという制度であります。","id":"exchange-048"},{"speaker":"鶴副委員長","kind":"意見","question":"今までは最高５年間で１度、高度障害者の件ですね。ここで言う白いつえとＴ字型のつえというのは行かなきゃいけないとの意見を述べました。","respondent":"日下部障害者福祉課長","answer":"障害者のＴ字と白杖につきましては、窓口に来ていただくことになります。ただし、手帳を提示していただければその場でお渡しをする、そういう仕組みになっています。","id":"exchange-049"},{"speaker":"鶴副委員長","kind":"質問","question":"極端な言い方をすると、その人にだれかに一緒に連れてきてもらいなさいとか、あるいは一人で頑張っていらっしゃいということになるのですか。いや、そうじゃなかったらそうじゃないというふうに言ってほしいんです。","respondent":"日下部障害者福祉課長","answer":"一応すべての仕組みを統一して実施をしておりますけれども、これはまた民生委員の皆さん方とのいろんな調整も必要になってまいります。ということで、この辺については少し検討させていただきたいと思います。","id":"exchange-050"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"心配になるのは、社会福祉協議会の代表の方が来ているから、社会福祉協議会の体制のほうはどうなんですか。ちゃんとそういう配慮は社会福祉協議会の中で案件として検討されて体制は万全なのかどうか、そこあたりわかる範囲で結構ですが、どちらでも結構です。","respondent":"日下部障害者福祉課長","answer":"今回の窓口の移行についても、基本的にはそういう観点も含めて移行するものです。今後は、先ほどの前段の報告の中でもご説明させていただきましたけど、来年度地域福祉計画の策定ということにも取りかかってまいりますけれども。","id":"exchange-051"},{"speaker":"鶴副委員長","kind":"質問","question":"計画の中に盛り込みたいというのは、その人員の体制を含めての話か尋ねました。","respondent":"日下部障害者福祉課長","answer":"計画の中で今後の社会福祉協議会の役割、体制がどうあるべきかという基本的な方向性をまずしっかりと形づくってまいります。それに基づいて具体的に何をどうしていくのか、具体的な体制の問題も含めて次のステップでしっかりと詰めていくということになろうかと思います。","id":"exchange-052"},{"speaker":"鶴副委員長","kind":"質問","question":"そうすると、現在の社会福祉協議会の体制という中で、中枢の職員体制というのはちなみに何人か尋ねました。","respondent":"高橋総務部副参事、小沼福祉事業部長","answer":"今局長が１名、介護学校の事務長が区から派遣されて、それが管理職としております。各係に係長が４名、それと職員ということで、大体３５名の運営でなっております。拡大なり、そういう問題も含めまして人的、物的なバックアップ体制というのを私どものほうでも当然しています。","id":"exchange-053"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"小さなことにこだわるようですが、つえというのは「転ばぬ先のつえ」というほど大事なものであります。お願いしないは別問題として、届けてあげるというような配慮を含めて前向きにぜひ検討をしていただきたいと、これはお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"嶋委員","kind":"質問・要望","question":"車っていろんなことをしているんですから。ですので、すぐにはできないと思いますけど、将来的に向けて社会福祉協議会がもうちょっと使いやすいような建物になるといいなと思います。","respondent":"日下部障害者福祉課長","answer":"ということで、まちづくり事業部のほうにも確認をいたしまして、安全対策のほうについては支障のないように考えていきたいと考えています。","id":"exchange-055"},{"speaker":"嶋委員","kind":"質問","question":"今３５人いらっしゃるということにびっくりしたんですが、何度かお伺いをさせていただいていますが、受付がどこかはっきりわからない。先ほど言ったように、区役所みたいにすぐ声をかけてくださる方があると大変うれしく感じておりますので、その辺ぜひ。","respondent":"高橋総務部副参事","answer":"窓口対応ですが、人数が少ない中でできる限りやっておりますが、来庁者によくできた窓口と言われるように努力してまいりたいと思いますのでよろしくお願いいたします。","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ますますなぜ社会福祉協議会なのかというふうなところがよくわからないんですけれども、両方でできるというふうなことのご検討はいただけないかなと思うんですけど、いかがか尋ねました。","respondent":"日下部障害者福祉課長","answer":"その辺の役割分担を進めていこうと、また土曜日も含めたサービスの向上ということで考えておりますので、そちら１本に絞るということでいきたいと思っています。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"じゃ、自分がどういうふうなサービスを受けられるのかというのは、つえとかということもだんだん出てくるというようなこともあると思うんです。つえは向こうというんだったら、本当に大変じゃないかなと思うんですけど、そこら辺のところはどう考えられているんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"先ほど申し上げましたように、つえにつきましては、最初交付してから５年たたないと再交付はしないんです。ただ、それ以降は５年に１遍でもありますので、大きな負担になるということでは私どもでは受けとめておりません。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、福祉タクシー券については２６日からということですが、その点が一つと。それから、業務委託ということになるのかな思うんですけど、そこの委託費についてはどの程度になるのかを説明するよう求めました。","respondent":"日下部障害者福祉課長","answer":"先ほどもご説明させていただきました広報誌での周知、そういうことも含めましてＰＲについては混乱しないように徹底してまいりたいと考えています。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"移行期間は設けられないということなんですが、多分もうこれだけの周知で周知徹底というのは難しいと思うんです。だから、障害を持った方にわざわざ向こうまで行っていただくということがないような方向でぜひご検討いただきたいと思うんです。","respondent":"日下部障害者福祉課長","answer":"移行期間の問題につきましては、とにかくサービスの低下を招くようなことになってはいけませんので、それについては混乱のないように私どもなりにしっかりと対応してまいりたいと考えています。","id":"exchange-060"},{"speaker":"須藤委員","kind":"質問","question":"もし、電話１本で持ってこいとか、それは先ほど課長がお話ししたように融通をきかせて対応していきますという話をしていただかないと。ですから、今後いろんな問題点が出てこうようかと思うので、その辺を考えてお願いしたいと思います。","respondent":"日下部障害者福祉課長","answer":"私ども本当に利用者の方に一番いいような形で進めていくということが基本ですので、最大限頑張っていきたいと思います。","id":"exchange-061"},{"speaker":"伊藤委員","kind":"質問","question":"こういうようなことを具体的に始めていくわけですから、看板の表示とか、そういうふうにハード面でも考えていく必要があるんではないでしょうか。その辺の決意といいましょうか、考え方といいましょうか、改めてお願いいたします。","respondent":"日下部障害者福祉課長","answer":"表示の問題、あるいはアクセスについてのしっかりした対応、それから、道路条件の問題も含めましてしっかりやるべきというご指摘をいただきました。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほども、他に社会福祉協議会の窓口が移っていくことがあるのかというふうなことでお聞きしたんですが、先ほど出ましたように、支援費の窓口が社会福祉協議会のほうに変わっていくということも将来考えられることってあるんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"ですから、そういった意味では、そういう基本的な窓口が社会福祉協議会に変わるということはありません。支援費制度ということではなくて、これからはその辺の整理をしっかりやっていく必要があるだろう、そういうことです。","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、委託先が大崎ホームヘルプサービスと日本福祉ということなんですけれども、なぜここの２カ所に決まったのか。もう一点は、それから介護支援センターに対しての運営費補助というのが、国と都と区のそこら辺のところがどうなっているのかを説明するよう求めました。","respondent":"早津高齢福祉課長","answer":"１地域センターに１カ所ということで進めてまいりましたが、支援センターのケアマネジャーの人数を増やすという必要がまず生じてまいりました。","id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"運営費補助は、基本的に国から４分の３ということですが、区からとかは全く入ってなくて、国から運営費の４分の３が入るということなんでしょうか。この総額が、一在宅介護支援センター当たり、およそどれぐらいの運営費補助が出ているのかをちょっと教えてほしいと求めました。","respondent":"早津高齢福祉課長、新美保健高齢事業部長","answer":"支援センターの運営費、基本と申しますと、私、補助金のような形を言いましたけれども、介護報酬です。介護報酬以外の事柄につきましては、４分の３の補助が国から出るという形で、区の持ち出しが１カ所について、大体３００……。 １カ所当たり在宅介護支援センターは、通常の居宅支援以外の業務を行うということで、１カ所３６０万円ぐらいが定額です。それの４分の３が国、都から補助で出て、４分の１を区が負担すると、そういう関係です。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今後はとりあえずは１９カ所で、そちらのほうにもケアプランが平等に回るような仕組みの方向にぜひ変えていただきたいなというふうに思います。それと、この介護支援センターで、今ケアマネジャーの方が１９カ所で合わせてどれくらいになったのかについて、ちょっと説明を求めました。","respondent":"早津高齢福祉課長","answer":"現在ですと１７カ所です。９月現在で申しますと、７２名です。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このケアマネジャーという方は、実際にケアプランを立てている方で７２名ということで考えていいんでしょうか。そのことを一つ確認をお願いしたいのと、実際に、品川区は具体的にどういうふうな形でされているのかを説明するよう求めました。","respondent":"早津高齢福祉課長","answer":"さまざまな形での開催というものが考えられるわけですが、地域ごとでのケースを題材としました、ケースの検討会議です。そのほかに、同じくケースと申しましてもかなり専門性が必要な、痴呆に関するケース会議というものを、毎月１回ぐらいのペースで開催をしております。","id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"なかなかこういう報告のときがないので、いろいろ聞いちゃってあれなんですけれども。この地域ケア会議のメンバーについて教えていただきたいんですけれども。","respondent":"早津高齢福祉課長","answer":"基本的には支援センターのケアマネジャーと、私ども高齢福祉課が統括支援センターという形になってありますので、その保健婦及び地区担当の職員がメンバーです。","id":"exchange-068"},{"speaker":"鶴副委員長","kind":"質問","question":"この２つ目、委託する大崎ホームヘルプサービスでしたか、それから日本福祉サービスですね。ここは言うところの大手とか中とか小とか、どのランクに入るんか尋ねました。","respondent":"早津高齢福祉課長","answer":"それから日本福祉サービスは、一応全国展開をしている会社ということになります。日本福祉サービスのほうは、こういう業界の中では大手ということになります。","id":"exchange-069"},{"speaker":"鶴副委員長","kind":"質問","question":"そういうことではないということのあかしでもありますね。そういうことが言えるのではないかと思いますが、いかがか尋ねました。","respondent":"早津高齢福祉課長","answer":"在宅介護支援センター、今回で１９カ所目ということになりますが、地元の事業者は２つ目です。","id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/534819?Template=document&Id=3012#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":61143,"voices":182}},{"id":"h14-20020305-8","meetingId":"h14-cm03","date":"2002年3月5日","dateIso":"2002-03-05","committee":"建設委員会","time":"午前１０時０５分～午後１２時３５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"平成１４年請願第１号 大崎駅東口・西口自転車等駐車場に関する請願","agenda":"平成１４年請願第１号 大崎駅東口・西口自転車等駐車場に関する請願","exchanges":[{"speaker":"上山委員","kind":"質問","question":"今は親御さんもなかなか大変な中ですから、どのぐらい減額するかは別問題にしまして、何らかの形でできないものなのかと思うんです。今度東口だとか西口第三などは高架下になっていて、それなりの場所ですからいいかもしれませんけれども、人がいるところからすればね。","respondent":"中村交通安全担当課長","answer":"ただパンクをさせられるとか、部品を持っていかれるとか、そこまでについては対応のしようがないわけです。やはり基本的には、やはり学生にはできるだけ健康のためにも歩いていただくということで、よろしくお願いいたします。","id":"exchange-001"},{"speaker":"辻委員","kind":"質問・要望","question":"ですから、一つの趣旨を酌んで、課題として防犯上の対策に取り組んでもらいたい。これは地元の方ですから、それを当然わかった上で言ってくれているんだと思いますので、その辺をお願いしたいと思います。","respondent":"中村交通安全担当課長","answer":"今、防犯対策は照度等を含め、またパトロール等をできる限りの部分を対応していかなければいけないと考えております。三丁目、遠くから利用いただく方に回していただければと我々は考えておりますし、広報等もこれからも引き続きしていきたいと考えております。","id":"exchange-002"},{"speaker":"辻委員","kind":"質問","question":"このときに定期利用の人というのはどんな状況なんですか。今電磁ロックになっているものを取り外せというのは大変な話ですから、１０７台のうち何割か、この辺はどうなんか尋ねました。","respondent":"中村交通安全担当課長","answer":"現在西口第三がスペース的に余裕があるということで、こちらのほうに当日利用を設けられないかということで、現在検討中です。できるだけ早急に設置できる方向で、今、話を進めているところですので、よろしくお願いいたします。","id":"exchange-003"},{"speaker":"本間委員","kind":"意見","question":"有料駐輪場になってからどうかね」という話を尋ねてまいりましたら、これまでにひと月に一、二件あるかないかというような自転車事情でした。それからでよろしいのではないかなと考えていますので、以上の２点について触れさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"築舘委員","kind":"質問","question":"質問としては、防犯上の問題で、防犯カメラをつけたということですけれども、これはかなり高価なものなのかどうかという費用的な面が一つ。それから、７日間で撤去ということが書いてありましたけれども、撤去をするような状況が有料駐輪場をつけてからどの程度あるのかということ。","respondent":"中村交通安全担当課長、中谷まちづくり事業部長","answer":"７日間で撤去という関係ですけれども、そこに放っておかれるということが考えられるということで、こういうものについて規定しています。７日間放置されていると電磁ロックの場合… 先ほどの７日間の撤去の関係ですが、通常７日間で撤去を条例上できることになっておりますが、これまでの実態です。正確な数字ではございませんが、大体そういうようなことで進んでいるところです。","id":"exchange-005"},{"speaker":"築舘委員","kind":"質問","question":"ただし、今後の防犯上の対策と使用料の減免ということですから、これは山手線を使うから自転車で行っております。責任を持って秩序正しいものを自分の責任でやっていくということが大切なことですから、私としてはいいことではないかというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"それをあえて無料だったものを有料にするわけですから、確かに整然となっていますから、なるべく低廉にすべきだという思いが一つあります。民間がやれば１００円で公のところは１５０円、やっぱり料金体系全体を、やっぱり見直していくべきときなのではないかというのが一つ。","respondent":"中村交通安全担当課長","answer":"現在のところ電磁ロックも定期利用のラックのほうも間隔は同じで４０cmになってありますので、電磁ロックに変えても台数は変わりません。","id":"exchange-007"},{"speaker":"沢田委員","kind":"意見","question":"そういう点からすると、やっぱり照明を明るくする問題と、防犯的に盗難は絶対にないようなシステムを取るべきではないのかなと思います。この請願はいろいろありましたけれども、うちの党としては賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"全体に賛成の方向ですから、あえていいんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"築舘委員","kind":"意見","question":"ただし今後の問題として防犯上の対策、学生に対する使用料の減額ということですので、実際上は防犯もよくされていると思います。学生に対する使用料減額に関しても、総体的に見ていかなければいけない問題だと思いますが、趣旨としては賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"辻委員","kind":"意見","question":"それから、これからりんかい線あるいは２６号線等の東西の交通網、費用と利用者負担というものを考えてやっていったらいいかと思います。私は今回の請願を一つの大きなきっかけにして、今後の課題とするということで、趣旨採択でやってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"沢田委員","kind":"質問・要望","question":"ですから、ぜひこれは区内全域に対して検討を加えてほしいと求めました。皆さんが趣旨採択であれば、趣旨でもかまいません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"本間委員","kind":"質問・要望","question":"特に、非常に雨風をおうことがあるものですから、統一していただきたいという将来的な課題も含めてお願いしておきたいと思います。利用料については、もう少し状況を見守っていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"平成１４年陳情第５号、ゲートボール場新設の陳情","agenda":"平成１４年陳情第５号、ゲートボール場新設の陳情","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"「天然芝で決めています」と言ったときに、ゲートボール協会の方は何と言っておられたんでしょうか、「わかりました」と言ったんか尋ねました。","respondent":"岩田管理工事課長","answer":"そのときは「ゲートボールを競技する場所に困っておられるので、区として「非常に、現在のところは難しいです」というふうにお答え申し上げました。その後、こういった署名を添えて陳情という形で出されたものです。","id":"exchange-014"},{"speaker":"沢田委員","kind":"意見","question":"天然芝ではだめなんだということになると、陳情の趣旨とはどうなのかなと大変迷うんですけれども、これを課長に聞くのも何か変な話になってしまうのかなとの意見を述べました。","respondent":"岩田管理工事課長","answer":"ただ、天然芝ですときちっとある程度の維持管理を行いましても、不利益というのが人工のものと比べましてどうしても出てまいります。いろいろ人工芝と比べるとかなり違うことは事実ですけれども、競技としてできないということはないだろうというふうに認識しております。","id":"exchange-015"},{"speaker":"沢田委員","kind":"意見","question":"昨日の屋上緑化の話ではないですけれども、それを地上緑化で、私は人工芝より天然芝を拡大したいなというふうに思います。ただ、これはこの陳情と全然違ってしまうとなると大変悩むんですけれども、少し難しいかなという気がするんですけれども、態度を決めかねていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"辻委員","kind":"質問・要望","question":"高齢者は大体ウイークデイの早朝にやっているわけですから、ここを３面でも４面でも使えれば大いに利用していただければいいかなと。２０ｍで８０ｍの四隅を９０度にかけて打ち込むか何かという道具を、天然芝ですからラインを引くというわけにいかないから、意見表明を含めて。","respondent":"岩田管理工事課長","answer":"現在まだ検討中でございまして、多目的広場をどういう貸し出しをするかということは、これから検討してまいります。そういったものを考えていかなければいけませんし、また町会とか青少年団体とか、これから検討をさせていただきたいと思います。","id":"exchange-017"},{"speaker":"辻委員","kind":"質問","question":"草っ原の上を自由に走れるという形になるわけですから、競技の部分と普段の利用の部分というのは、八潮の多目的とまた違う使い方ができる。今回やるときに、ゲートボールの使用を考えたときに、無料、有料を考えるとどうなんか尋ねました。","respondent":"岩田管理工事課長","answer":"そういう考え方のスポーツ施設の場合は当然考えなければいけませんので、減免の方法についてはいろいろ工夫をしていかなければいけないだろうと。団体とは別に一般の個々の方が来られて、ある特定団体が独占的にお使いになる場合は、基本的に有料というふうに考えております。","id":"exchange-018"},{"speaker":"辻委員","kind":"質問・要望","question":"ここの使用方法等については、具体的に決まったら教えていただきたい。さまざまな使用グループが出てくるかと思うんですけれども、そこに対しては周知して、きちっとしたルール作りが必要かなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"築舘委員","kind":"質問","question":"ですから、ゲートボールだけというのではなくやるような形の運用の仕方をしてもらえればいいのかなという感じはするんです。最初からだめということではなくて、そういう趣旨を汲み取りながらやってもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"本間委員","kind":"質問・要望","question":"「品川中央公園にゲートボール場を設置していただきたい」という部分が最初なんですが、これはおそらく想定していたのは人工芝だと思うんです。十分この趣旨が得られるようなものにしていただけるのではないかと、あるいはその趣旨を取り入れていただきたいというふうに思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"築舘委員","kind":"質問・要望","question":"先ほども言いましたように、今後のことですので、この中央公園がみんな楽しく地元の方がそれぞれのスポーツをして、また楽しい１日が過ごせるようにという部分で工夫をしていただきたいということで、この趣旨には賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"辻委員","kind":"質問・要望","question":"ここの多目的広場とかテニスコートとか、今回資料をつけていただいたわけですけれども、今後区民に対するＰＲの中でうたっていただきたい。この性格というのは達成されたと思いますので、それは陳情に対して受けたという形になると思いますので、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-03","title":"平成１３年請願第５号 住友不動産による「仮称大崎５丁目マンション」超高層、高さ１００ｍ、３０階建てに対する請願","agenda":"平成１３年請願第５号 住友不動産による「仮称大崎５丁目マンション」超高層、高さ１００ｍ、３０階建てに対する請願","exchanges":[{"speaker":"上山委員","kind":"確認","question":"一つだけ確認ですけれども、１２月１０日に東京都へ総合設計の何をしたと言われたんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"１２月１０日に総合設計の許可がおりました。それに対する審査請求です。","id":"exchange-024"},{"speaker":"上山委員","kind":"意見","question":"囲むような感じでやっているんですけれども、たまたま都営住宅の皆さんの説明会に出たんですが、地元のほうでも全体としてはしようがないと。工事協定を結ぶ調整中と聞いていますので、もうちょっと様子を見たらどうかと思うんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"辻委員","kind":"質問","question":"その辺の傾向をどうお考えになっているのか、ちょっとお聞きしたい。この問題に関係ないかもわからないけれども、ただ非常に大きな課題になりつつあるなという印象を持ったものですから。","respondent":"浜脇住環境整備課長","answer":"今回もその辺についても、少しでも減らすような努力をすべきだということで、周りの建て方とか植栽についてもご意見は申し上げさせてもらいました。","id":"exchange-026"},{"speaker":"辻委員","kind":"質問・要望","question":"建てる前がどうであって、被害を元に話し合いしても、けんもほろろに言われても困るというので住民も心配している。これは検討をお願いしたいと、要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/807981?Template=document&Id=3714#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":27483,"voices":79}},{"id":"h14-20020305-9","meetingId":"h14-cm03","date":"2002年3月5日","dateIso":"2002-03-05","committee":"文教委員会","time":"午前１０時０５分～午前１１時５９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"非常に１０名選ぶという選び方の基準というんでしょうか、この１０人の方とこの１０人の方という、多分違うんじゃないかと思うんです。ですから、こうした点についてどうかということですね。","respondent":"青木指導課長","answer":"学校の教育方針が保護者にわかりやすく説明されているだろうかとか、そういう学校総体として評価していきたい、こういう項目で考えております。こういうところに力を入れていきたいという形で説明をすることをもって公表していきたいというふうに考えております。","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問・要望","question":"個別学習にしても七つのメニューですか、そういうのをやって教育委員会サイドで一定のプランニングをしたというのがやや傾向が強いですよね。より強化をしていくとならば、もっと積極的に条件整備を確実にやっていくというのが私は前提だと思うんですけれども、それはどうか尋ねました。","respondent":"若月教育長","answer":"先ほどちょっと指導課長が説明していましたけれども、学校評価だとかといったようなものを専門にされている学識経験者の方がいらっしゃいます。こんなふうに考えておるところです。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"１点だけちょっと、質問じゃなくて要望です。考え方のところはきっちりしていくことが学校の自主性、自律性を尊重していくという、そこを強調したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/547087?Template=document&Id=4432#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":9611,"voices":16}},{"id":"h14-20020305-5","meetingId":"h14-cm03","date":"2002年3月5日","dateIso":"2002-03-05","committee":"総務委員会","time":"午前１０時０４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件整理しています。","topics":[{"id":"topic-01","title":"昨日の議案審査に引き続き、３月１日の本会議で当委員会に付託されました第３１号議案","agenda":"昨日の議案審査に引き続き、３月１日の本会議で当委員会に付託されました第３１号議案","exchanges":[{"speaker":"三上委員","kind":"確認","question":"ちょっと確認させてください。そういうものというのは本来やらないものなんですか、やって終わったときには、仕上げ工事もやっていくという工事にはなってはいないんか尋ねました。","respondent":"西島経理課長","answer":"ただ、この工事は東京都の下水道局からの受注工事ということで、東京都からの発注が分割して区のほうに来たということがあります。ある部分では計画的に順次発注をしている、そういう中で、当然こういうふうな形で分割で発注をされてきたというふうに聞いてあります。","id":"exchange-001"},{"speaker":"三上委員","kind":"質問","question":"段取りとして、そういうふうに分けても形式的には加算されていくということはないんですかね。","respondent":"西島経理課長","answer":"その設計の段階で2,０００万円ほど、まずシールド工機とか、その分については2,０００万円ほど設計の段階で金額を単独発注よりはカットしている。さらに、契約の段階でまた２％ちょっとカットして契約というふうな方法をとってあります。","id":"exchange-002"},{"speaker":"三上委員","kind":"質問","question":"今回発注する下流工区ということになるんでしょうね。図面で言うと、取り込み工区推進工となっていますが、そちらのほうでということで発注されているんか尋ねました。","respondent":"西島経理課長","answer":"その右に西五反田五丁目から五反田大橋のわきまで来る下流工区シールド工というのを、その３、その４工事でまた発注をする。それから、最後に取り込み工区推進工をその後工事で発注というふうに聞いております。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"すごく親切に全部教えていただきましたが、でき上がった仕事で、プラス2,０００万円かけてやる仕事がこの図のどこなのと聞いているのです。仕上げの水が通らないようにするのは、この図のどこですかと聞いているのです。","respondent":"北村下水道河川課長","answer":"この４ページの図面で、赤でマーキングしているところですけれども、この区間全部です。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"この区間、今度工事やるんじゃないの。この３億幾らの工事は、この図でどこか尋ねました。","respondent":"北村下水道河川課長","answer":"３億円の工事の中で、赤でマーキングしました範囲の全線について、そのコンクリートで仕上げをやっていくという工事です。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"意見","question":"くどいと思いますが、もう一回、１期工事は済んでいるわけでしょう。その１期工事の分の内装というのかな、内装を施すのと、この図ではこのピンクの中が二つに分かれるということなんでしょうとの意見を述べました。","respondent":"北村下水道河川課長","answer":"トンネルを掘り上げるという格好がその１工事でございまして、その掘り上がったトンネルの全体について仕上げをしていくというのがその２工事ということで、若干わかりにくい……。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"ああ、そう。その内装工事だけで３億円かかるということなんか尋ねました。","respondent":"北村下水道河川課長","answer":"相当延長もありますし、コンクリートのボリュームとしましては相当なものですので、それぐらいの工事規模になるということです。ただ、この中で分水人孔というものが２カ所あるかと思いますが、これは地上から数十メートル下のトンネルに向かってドリルで穴をあけまして……。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"どのところはどういう仕事をするのかというのは、３億円から金かけるのに、聞く身になって説明をしていただきたいというのをお願いしておきます。それから、今言われた真ん中の特殊のところは、内装できないから次にやるわけね。","respondent":"北村下水道河川課長","answer":"そうです。","id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問","question":"とすれば、ここはどのぐらいかかるのですか。わからないか尋ねました。","respondent":"西島経理課長","answer":"最初のご質問ですが、恐れ入ります、２ページ目の下の欄に、ちょっと説明が不足で申しわけございません。それから、二つ目のその３工事にかかるんですけれども、今の段階で幾らということはちょっとお答えしかねます。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"質問","question":"高低差はどういうふうになっていて、目黒川に放水する高さが決められていますよね。そうすると、山手通りをくぐっていくというか、高速道路の上を通るんですか、下を通るんか尋ねました。","respondent":"北村下水道河川課長","answer":"ここの山手通りのところは非常に深くなってありますので、下を抜けまして、今度目黒川に向かってずっと上っていくというような勾配になってあります。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"意見","question":"その辺の、例えば大雨が降ったときに、調整池の下流にこの水は出てくるわけ。どういうふうにとらえて、計算上というのかな、皆さんプロとして雨量をどういうふうにとらえられていますかとの意見を述べました。","respondent":"北村下水道河川課長","answer":"東京都の河川部のほうで管理している川でございまして、当然放流に当たりまして、河川部の協議が必要になってまいります。協議をしていく中で、これを流すことによって問題はないというふうなことで今調整が図られているところです。","id":"exchange-011"},{"speaker":"田中委員","kind":"確認","question":"最終的な平成１６年の完成に向けて、スケジュールどおりその１が進んだのか、当初の予定どおり完成が間に合うのかどうかというのを確認したい。","respondent":"北村下水道河川課長","answer":"基本的には今年度末ないしは次年度の４月早々にはトンネルが堀り上がるということで順調に進んですので、全体の工程につきましてはほぼ予定どおり１６年に完成できるということで、今進めているところです。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"今回取り上げるべき質問ではないかとは思うんですが、建設業界のほうは大変厳しい状況で、一時は株価が額面を下げているような傾向があった。今、把握されているのかどうか、個々の企業の経営内容をどれだけ把握されていらっしゃるのかどうかというのをお聞かせほしいと求めました。","respondent":"西島経理課長","answer":"ただ、それをじゃあ具体的に入札の条件の中に取り込めるかどうかというのは、かなり慎重に検討しないと難しい問題かな。いろいろ出てまいりますので、今のところは状況をつかんでいる、つかもうとしているというような状況だというふうに思います。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"入札ですから、難しいとは思うんですが、ぜひその部分を研究対象としてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問","question":"今の最後のほうの減税補てん債についての関係で、僕の聞き違いかもしれないんですが、３カ年度としてこれを盛り込んできたということは、１７０億円余りのお金が３カ年に分けてくるというのか、ドーンと来て、それぞれ区で３カ年分に充てなさいよということなのか、どっちか尋ねました。","respondent":"市岡企画財政課長","answer":"ちょっとご説明申し上げますと、１６年で、それぞれ算定されなければおかしいんですね。品川区では多分六億七、八千万円になると思いますけれども、これはそっくり減税補てん債に積むということになろうかと思います。","id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問","question":"その仕事というのは、１３年度、１４年度あたりにやりたいんだという意欲を持ってプランニングしたものがカットされているわけですよね。それをカットされた分に充てていく、投資的経費に充てていくという考え方は、話し合いには出ないんか尋ねました。","respondent":"市岡企画財政課長","answer":"私の説明がちょっとあまりよくなかったのかもしれないんですが、４分の１は、その分財調で埋めるということなんですね。この再調整で来たお金をどう使うかはまさに各区の財政運営の考え方次第なので、委員おっしゃられるとおり、その辺は少し慎重に考えていきたいなです。","id":"exchange-016"},{"speaker":"林（宏）委員","kind":"質問","question":"話が後ろから行って申しわけないんですけど、この４ページの説明のときに、再調整についてのお金が１６０億円余残されていた。それは、こういうふうに後で再調整するために、いわゆる算定の外側に置いてあったお金というふうな考え方でいいか尋ねました。","respondent":"市岡企画財政課長","answer":"例の特別交付金の２％、これは９８と２に分けてあらかじめ取っておきますが、これはあくまで見込み差です。言ってみれば、見込み差が１９０億円あるだろうと思っていたのが、それが減ったという関係になります。","id":"exchange-017"},{"speaker":"林（宏）委員","kind":"質問","question":"前回２６０億円ぐらいなんだけど、そのことと、石原知事が区のいわゆる中小企業対策なんだから考えて協力せよというようなこともコメントされている。２３区側はコメントを発しているんだけど、読むほうが勝手に憶測をしているのか、その辺を整理して教えてくれますか。","respondent":"市岡企画財政課長","answer":"中小企業支援、現下の厳しい情勢の中では、政策としては理解を十分できると。財政全体に対する影響について、都側に説明を求めたい、こういうコメントが出ている段階です。","id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"東京都の予算が決まってくると、きちんとした話になってくると思うんで、そういう段階でまた教えていただきたいというふうに思います。これは抜粋した言葉だから、そんなに厳密な言葉じゃないだろうけど、そういう方向性を品川区としたら望んでいきますか。","respondent":"濱野助役","answer":"それから基準財政需要額という考え方から成り立っていますから、これは想定として基準財政収入があるはずだということで算定します。いわゆる２３区がいろいろなカラーを持ってきたとしても、根幹としてこの財調というのは今の形で持っていくというふうなことです。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"意見","question":"だから、２３区で統一方式でいくから、財調の中で含めて見ますよという話になっている。清掃事業もそういう部分に引っかかってくる性格だと思うんだけども、そういうようなことになっていくのを望みますかとの意見を述べました。","respondent":"濱野助役","answer":"やはり、しかるべき時期には２３区が独自の考えを持って国保の負担の量を決めていくべきだと考えます。ただ、これもちょっと技術的なことになってまいりますが、長期的な財調も技術的な面でも変わってくる必要はあるというふうには思っております。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと伺いたいんですけども、区のほうとしては、当初予想していた部分もあったんじゃないかと思うんですけど、違いはあるのか。","respondent":"市岡企画財政課長","answer":"これを一つの１３年度末までの財源見通しとして、その後の法人２税の落ち込みの状況を考えると、当初の見込みどおりはいかないなということは十分盛り込んで財政運営に取り組んできた都です。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"これはどういう、先ほど成人式のイベントを例に出されたんですけども、どういうものに影響が出てくるか。どのぐらい、何種類ぐらいあるのか、そこら辺はどうか尋ねました。","respondent":"市岡企画財政課長","answer":"各区が見直さなければいけないということではありませんで、最低のカウント上、この際少し見送るかということで協議が整いました。例えば国民年金の事務なんかは、これも事務が変わるわけですから、当然この需要額については大きくなりましたというふうなことがあります。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問","question":"先ほど全部で６億円ぐらいになるということで、これは減債基金を積み立てしておりまして、いろいろ事業にも影響してくるということをやりながら、減債基金に積み立てるという、ちょっとそこら辺のところはしっくりこないんですけども、改めてちょっとお聞きしたいんですが。","respondent":"市岡企画財政課長","answer":"これはまた別の問題ですけれども、財政運営の物の考え方として、そういう資金の色分けをしておいたほうがいいだろうです。新しい仕事にも積極的に取り組んでいて、今度予算委員会で詳しくご審議いただきますけれども、こういう状況です。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"質問","question":"そういうようなことは、品川区としてはＪＲとは折衝できないんですか。特別に整備をしているわけではないんだし、直接ＪＲとは話ができないんですか、品川区としては。","respondent":"桑村政策担当課長","answer":"これから調査をすると言っていましたが、二、三年にはセンター全体の閉鎖も検討したいというような基本的な意図だろうというふうには受け取りました。検討はもちろんされるんだろうと思いまして、ＪＲのほうが考えられるのかどうか、ちょっと正直言いまして疑問な部分があります。","id":"exchange-024"},{"speaker":"林（宏）委員","kind":"質問","question":"人道的な立場から１回部長がやってあげればいいんじゃないですかね。できれば、やってあげてほしいなと思うんだけど、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"土井副委員長","kind":"質問","question":"これを使うか使わないかは、それぞれの自治体等に委ねられているというふうに、今のお話しから判断できたということが１点ですね。では、しないの判断のところがどういうことからそうするのかというところをちょっぴり、もう少し何か説明していただけないか尋ねました。","respondent":"古川人事課長","answer":"その派遣法が予定している派遣のあり方はと申し上げますと、先ほど申し上げました団体に対する人的な支援を行い、派遣法が予定している部分は。これは先ほどの派遣法は相手団体に人的支援をし、しかも３年余の期間の中で、こういう考え方に今立っているところです。","id":"exchange-026"},{"speaker":"土井副委員長","kind":"質問","question":"そうすると、今までは特に派遣法というものはなかったわけですから、そのうちの研修派遣とも何ともつかない形で派遣をされていたと。要するにもっと自主的にやるためには、そういうものもあわせて入っていくことによってのみ実現するわけなんですが、その辺は。","respondent":"古川人事課長","answer":"ちょっと説明が不足しました。業務としては研修を行って、その成果をまた区のほうに、こういう関係です。","id":"exchange-027"},{"speaker":"土井副委員長","kind":"質問","question":"ということは、今の行っている皆さんについては、今は職免派遣で派遣をされているというのが、法との関連の中で、今度は研修派遣というふうに切りかえますということも今のお話の中には入っているというふうに理解をしてよろしいんか尋ねました。","respondent":"古川人事課長","answer":"基本的な考え方はそのとおりで、研修派遣に切りかえ、３年余の中で、それを送って、なくしていくという考え方です。","id":"exchange-028"},{"speaker":"塚本委員","kind":"質問","question":"品川区の場合は、今２５人を研修派遣ということですから、待遇の上では職員と全く同じということですね。２５人の考え方なんですけれども、どういう層の人が、今までの派遣の推移状況をまず示すよう求めました。","respondent":"古川人事課長","answer":"スポーツ協会に１名、社会福祉協議会には２名ということで、いわゆる管理職を１名出しています。それから社会福祉協議会に１名、これで全体２５名になろうかと思いますが、一応こういう形です。","id":"exchange-029"},{"speaker":"塚本委員","kind":"質問","question":"今お伺いして、実態を聞きますと、どこまでのレベルの人が転勤すべきかというようなことですね。このことも、研修で出すということで間に合っていたのかどうかということに多少の疑問を感じますけれども、いかがでしょう。","respondent":"古川人事課長","answer":"それぞれの団体の、３団体の、今までの経過の中での区の人的な支援というのもまるっきりなしというだけじゃありません。できるだけ相手団体の自主的、自立的な運営を前提に、区としては一定の期間は縮小していきたい、こういう考え方です。","id":"exchange-030"},{"speaker":"塚本委員","kind":"意見","question":"各区それぞれ対応、今後設定をしてといういろんなものがあるんでしょうけれども、品川区の派遣の規模とか実態ということからいって、これなら間に合うということなんだと思うんですけど、整理すべきものは整理するという考え方を意見として申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"土井副委員長","kind":"提案","question":"研修派遣に今度切りかえるというのが本質的な中身なのに、なぜこんな形で出てきたのかという、多少の不満を思いながら伺ったんです。本質の話でご提案、ご提起をいただけないかというふうに思いますけれども、そこら辺についてはどうなんでしょうとの意見を述べました。","respondent":"古川人事課長","answer":"この案文が報告の中で検討された時点で、行政改革特別委員会でも皆さんにご説明をした経緯がございましたけれども、派遣法についてもご報告するものです。","id":"exchange-032"},{"speaker":"北野委員","kind":"質問","question":"この金額は、区に、どこへ入ってくるんですか、補償額というのは。","respondent":"西島経理課長","answer":"区のほうに入ってくる金額がこの金額です。","id":"exchange-033"},{"speaker":"北野委員","kind":"質問","question":"算定というのは、地価というんですか、土地の値段とかはどういうところで金額が出てきて、算定されたんか尋ねました。","respondent":"西島経理課長","answer":"1)は右側のほうでございまして、2)が左側のほうです。小さなところ、区域の点です。","id":"exchange-034"},{"speaker":"三上委員","kind":"意見","question":"どうなっているの。説明をする予定のところが入ってきちゃっているわけでしょうとの意見を述べました。","respondent":"西島経理課長","answer":"ちょっともう少し午後にわかりやすい図面を……。午後にもう一度お配りするときに、公図だとちょっとわかりづらいと思いますので、現況図とちょっとあわせてそれも配らします。","id":"exchange-035"},{"speaker":"土井副委員長","kind":"確認","question":"そうすると、都のほうにも、その持ち分に相当する補償が行っているんですか。だろうと思うんですけれども、確認を。","respondent":"西島経理課長","answer":"ちなみに、国のほうが１０万分の1,８８１でございまして、１４万6,０００円余が参ります。この小さく塗った三角分、この部分が共有持ち分です。","id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問","question":"順番にちょっと詳しく聞きたいんだけど、この区分地上権の設定をすると、例えば区としては何か制約を受けるんですか。デメリット、あるいは制約の部分と鉄道会社のほうの法的な責任みたいな部分等、その辺をかいつまんで話していただくよう求めました。","respondent":"西島経理課長","answer":"その下を使うとき、今の法律で大深度地下法では、地下４５メートルまでが対象の範囲になる。他人の土地を通過するということで、区分地上権を設定しなければ、こういう工事はできないという形になります。","id":"exchange-037"},{"speaker":"林（宏）委員","kind":"意見","question":"ただ、下に電車が通るから、この設定をして金が入ってくればいいやという話じゃない。きちんと説明を求めました。","respondent":"西島経理課長","answer":"これを貸し付け、またはこれに地上権を設定することができる」と、こういうふうに記載されてあります。ＪＲ、同じ地続きでＪＲとのほうの関係も出てまいりますので、ＪＲのほうと１回内容を詰める、方法から、どういう計算でやるかということを詰める。","id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問","question":"あのときも報告だったんだけど、それはどういうふうに理解しておけばいいんですか。そうすると、議会の承認というところは、どういう形でここに出てきますか。","respondent":"西島経理課長","answer":"朝一番のところで話しました地方自治法第９６条第１項第５号の規定というのがございまして、それには当たらないというふうに解釈しております。今回計上していますので、そこでご審議いただくということもございまして、事前にご報告ということにさせていただきました。","id":"exchange-039"},{"speaker":"林（宏）委員","kind":"質問","question":"意味合いはわかりますが、ただ、例えば２億7,０００万円の土地を買う、あるいは土地を売り払うというときは、こうはいかないですよね。これからいろいろそういうソフトの部分というのが出てくると思うんだけども、明らかに地上権というのは議会の議決は要らないと書いてあるんか尋ねました。","respondent":"西島経理課長","answer":"予定価格１件4,０００万円以上の不動産、土地については１件5,０００平米以上の土地のものに限る」というふうに記載されてございまして、今回この区分地上権はそれには当たらないです。","id":"exchange-040"},{"speaker":"林（宏）委員","kind":"意見","question":"今の説明だと、金額は当たりますよね、広さは当たらないけど。その辺、これからもいろいろ出てくる可能性はあると思うんで、はっきりしておいてくださいとの意見を述べました。","respondent":"西島経理課長","answer":"これは私ども、今のソフトの部分に当たるので、当たらないという解釈ですが、この辺、文書とも確認をしまして、当たらないと。ただ、金額が大きいということがございまして、ご報告をしたです。","id":"exchange-041"},{"speaker":"林（宏）委員","kind":"意見","question":"下の権利は、事前の交渉みたいなものをできるようにしておかないと、いわゆる区の財産が第三者に渡っていくという可能性があるわけですよね。その辺、先々のことをきちっと見据えておかないとというふうに思うんですけども、いかがでしょうとの意見を述べました。","respondent":"西島経理課長","answer":"区から協定を結んだときに登記をする、設定登記をするという形になりますので、そこのところはちょっと難しいんではなかろうかというふうに思います。","id":"exchange-042"},{"speaker":"林（宏）委員","kind":"意見","question":"午後に、じゃあ、時間があれなんで、議会の承認の要るか要らないか。要るんだったら、この報告で済まされないし、総務委員会で承認がなければ、補正予算の審議ができなくなるとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"宮崎委員","kind":"質問・要望","question":"どういう制限が加わるのか、どんな条件なのか。鉄建公団はどういう面があるのか、これによって出てくるのか、そこのところをもう一度教えてほしいと求めました。","respondent":"西島経理課長","answer":"例えば何階以上の建物が建ちませんよ、仮にそういう柱になったときには、そういうところの部分が出てまいります。それは先ほど言いました阻害率というところでございまして、何もなければそのまま使えるわけですけども、その辺で出てくるです。","id":"exchange-044"},{"speaker":"宮崎委員","kind":"質問","question":"じゃあ、建物を建てるには、特に制限がないということなんですか。だから、これは地下になければ制限がないんだけど、あるがために出てくるものというのはあるんじゃない、そこのところ。","respondent":"岡田施設課長","answer":"一緒に打ち合わせに入りましたので、私のほうからご説明いたします。ただ、技術的には十分今後の建物というものは、この部分であっても、その上に建てることは十分できると、こういうことです。","id":"exchange-045"},{"speaker":"林（宏）委員","kind":"質問","question":"とすると、さっき言っていた他人に渡るということはないということですね。所有権はあくまでも区にあるわけだから、犯罪的に渡ることはあるにしても、正規のルートで渡るというのは、所有権者が貸し付けをするわけですから。","respondent":"西島経理課長","answer":"貸し付けといいましても、債権として貸す場合と物権として貸す場合がありまして、地上権は物権として貸す場合ですので譲渡は可能である。ただし、要するに使用収益の対価として、一定期間区切って使用を許可するわけですから、その対価として貸し付け代として……。","id":"exchange-046"},{"speaker":"林（宏）委員","kind":"意見","question":"使用料だから、その補償額であって、売却ではないということなの。東京都とは期限が区切ってあるよね、３０年、これは無期限？との意見を述べました。","respondent":"西島経理課長","answer":"これは２０年です。","id":"exchange-047"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"じゃあ、くれぐれも大事にしてほしいと求めましたので、よろしくお願いします。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"三上委員","kind":"意見","question":"指定金融機関の変更ということで、議会の議決を要するという話で、今報告ありましたよね。そうすると、現時点で議案を出せないですよね、そうすると、どの時点で出ますか、最終本会議という形になりますかとの意見を述べました。","respondent":"南副収入役","answer":"先ほど日程のところでちょっと申し上げましたが、３月の中旬ぐらいに正式認可がおりる予定というふうに銀行側から聞いております。それを受けまして、議案の提出自体は３月２８日、最終本会議の日になろうかということで調整をしています。","id":"exchange-049"},{"speaker":"林（宏）委員","kind":"提案","question":"それを言ってもしようがないと思うんで、みずほとみずほコーポレートの書き方はこうじゃないんです、ほんとうは。３月中旬じゃないと認可がおりないという事情があるんだろうと思うけど、その辺は少しお考えになったらいかがでしょうか、と提案をしますとの意見を述べました。","respondent":"南副収入役","answer":"私どもも３月２８日に議案を提出するということで、１月２２日に第１回目の報告をさせていただきまして、２８日については委員会に付託された中でご審議をちょうだいしたいというふうに思っているところです。","id":"exchange-050"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっと確認したいのは、印鑑を押されて、そこにいろいろ書いているわけですよね。通常、この印鑑というのは、どういうふうな保管をされているのか、どうでしょう。","respondent":"中尾根企画部長","answer":"事務局長およびその下の局員の間で現実的には保管し、決裁のおりた部分についての具体的な公印を押すという行為は、その事務局の中で行われているです。","id":"exchange-051"},{"speaker":"宮崎委員","kind":"質問","question":"その判この関係が勝手に使われる状況にあったのか、通常のそういう判こを押すときにはどういうルートで、どういう許可を得て判こが押されるんですか。それで、今回の場合は、そういう手続が踏まれていないというんだったら、どういうことがあったのか、そのところはどうなんでしょう。","respondent":"中尾根企画部長","answer":"５ページをちょっと見ていただきたいんですが、ここに判こ、理事長の印というのがありますね。これの表書きの２ページのところの決裁ですね、確認書として相手方の証券会社に送付をしている、こういうことです。","id":"exchange-052"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、この資料の２番目のところは、決定の特例、当時事務局長ですよね。逆に２ページのところで局長の決定があれば、勝手に使われると、それは可能だという仕組みになっているんか尋ねました。","respondent":"中尾根企画部長","answer":"昨日もご説明しましたけれども、例えば２００万円の契約でしたら、この決裁権限は事務局長が持っています。そのことを事務員が気づかなければ、そのまま命令されれば、理事長印は押されていくです。","id":"exchange-053"},{"speaker":"宮崎委員","kind":"質問","question":"それが、この２ページのところ、２ページだけじゃないんですよね。その他全部そうなんですけども、この仕組みは、このときに初めて理事長が気がついたんか尋ねました。","respondent":"中尾根企画部長","answer":"こういう購入だけではなくて、この間の資金運用のことについては、そういうことで運用されていたというふうにご答弁します。今回、初めてこのことがあったというわけではございません。","id":"exchange-054"},{"speaker":"宮崎委員","kind":"質問","question":"それは前から承知していたんじゃないですか。そこのところは、要するに、それを承知していたの、以前から。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"塚本委員","kind":"質問","question":"議事進行。区長がこれは勝手にやったという発言を聞いたという発言をされましたけれども、それはどこで、どういうふうに聞いたんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"塚本委員","kind":"質問","question":"そういうふうに書いてあるんですか今の発言だと、あなたが聞いたように……。不適切な発言です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"宮崎委員","kind":"意見","question":"新聞報道ではそういうふうに言っていますし、とりあえず、これはこれで確かめないと。何だってねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"宮崎委員","kind":"意見","question":"新聞報道によると、元助役が自分の独断でやったというふうに言っていますから、これはそれを……。これを指摘してくれなかったのかというのは、この報告書にも書いていないんですけども、どうでしょうとの意見を述べました。","respondent":"中尾根企画部長","answer":"そのことを運用上には違反しているというふうに認識していたかどうか、私のほうの調査の中では確認しておりませんので、そこはお答えはできません。知ったのは平成１３年の春、新しく副理事長が交代しましたときに、報告があって知ったです。","id":"exchange-059"},{"speaker":"宮崎委員","kind":"確認","question":"私は、この報告書のところでも、外国債の購入自体は問題ないんだというふうなまとめになっていますよね。すぐ買っていいよと、例えばそういうふうな指示があったのかどうなのか、そこのところは確認していますか。","respondent":"中尾根企画部長","answer":"去る２月１９日の理事会および評議員会の中で、その点については知らなかった、ほんとうにそういう事実だというふうに受けとめてあります。","id":"exchange-060"},{"speaker":"宮崎委員","kind":"意見","question":"アルゼンチン債を買ったかどうかというのは、いいものがあったら買いなさいとか、そういうふうな指示があったのかどうか。ところが、自分の考えていたのと全然違うものを買ったんだというふうなところなのか、そこのところは何か聞いていますかとの意見を述べました。","respondent":"中尾根企画部長","answer":"そういうふうに評議委員会等でご説明したとおり、考え方を持っていなかった、どういうふうにしろとかという指示はしてございません。指示したのは購入した事実を知って、それをどうすべきかというときに初めて指示をしているです。","id":"exchange-061"},{"speaker":"宮崎委員","kind":"意見","question":"外側から見たら、そういうふうに見えるんです。ところで、理事長から副理事長への何らかの下命があったんではないかとの意見を述べました。","respondent":"濱野助役","answer":"そのことと、指示があったかないかというようなことと全く関係のないことです。指示がなかったということについては、先ほど企画部長からお答えしたとおりです。","id":"exchange-062"},{"speaker":"宮崎委員","kind":"質問","question":"今までは理事長の係わりというは、昨日は出なかったものですから、そこのところを少し。それは何でそういう気持ちが動いたのか、どういう話になったのかというのがわからない。","respondent":"中尾根企画部長","answer":"現在の新光証券の中で、最もその当時おそらく高い利益を得られる商品として、その話を具体的に進めていったです。それから、公金、そういうものについてもどうすべきかという非常に研究や当時の状況の中で新たなつき合いができたというふうに聞いてあります。","id":"exchange-063"},{"speaker":"塚本委員","kind":"確認","question":"資料１９ページの債券の格付に関する確認書については、だれが、どんなふうに押したのか。だれがどういう手続のもとで、この判こは押されたのか。","respondent":"中尾根企画部長","answer":"お金を払うという決裁をやったのは３月の次の日の８日で、決定が３月１４日となっていますけれども、こういうふうに指示をしていったものです。それがずれておりますが、具体的な事務の流れというのは、そういうことです。","id":"exchange-064"},{"speaker":"塚本委員","kind":"質問","question":"副理事長は、そのときは事務局長だった、じゃあ直に係長ということか尋ねました。","respondent":"中尾根企画部長","answer":"事務局長は、このとき兼務ですから、事務局長の下に課長はおりますが、事務的な手続のところについては、実際上は係長がやっておりますから、そこに直接指示をしております。","id":"exchange-065"},{"speaker":"塚本委員","kind":"質問","question":"通常、理事長印が必要な決裁の種類というものを教えてほしい。この場合には、事務局長決裁になっていますが。","respondent":"中尾根企画部長","answer":"一般の決裁部分につきましては、処務規程の資料の４８ページのところにあります。そのほかの部分につきましては、通常は原議の決裁の欄の中で理事長が自信を持って意思を示す、こういうことになると思います。","id":"exchange-066"},{"speaker":"塚本委員","kind":"質問","question":"先ほどの説明の中に理事長印、本人が意思を示しさえすれば、判こがつくのだよと。この場合は、本人が意思を示していなかったという皆さん方のご判断ですから、どういう違反が生じているのかということを説明するよう求めました。","respondent":"中尾根企画部長","answer":"そのことは報告書の中で本来決められていた寄附行為および処務規程に明らかに違反している、こういう指摘の部分が一つです。もう一つについては、別の切り口の問題でございまして、私どもはそのことを指摘させていただいたです。","id":"exchange-067"},{"speaker":"塚本委員","kind":"質問","question":"もう一度時系列にということで、だれがどうして何を紛失したかということを知りたいです。１３年の春に副理事長がかわって、それからすぐ理事長のほうへ、こういうものを所有していますということをすぐ報告したんか尋ねました。","respondent":"中尾根企画部長","answer":"初めて、そういう意味から、副理事長および関係者以外が知りましたのは、現副理事長が交代したとき、しかもそれは１０月でしたけれども、それの冬のときに具体的な財団内部のいろいろな内容を財団の……。","id":"exchange-068"},{"speaker":"塚本委員","kind":"質問","question":"この間、タイムラグがあると思うんですけど、持っていることに対する認識、デフォルトが起きる前ですから認識が違っていいわけですけど、その間はどういう認識でいられたというふうに調査委員会では承知していますか。","respondent":"濱野助役","answer":"アルゼンチン国債なり、ほかの国債についても、満期の到来をもって別の種別に取りかえるべきだというふうに認識しております。これは満期到来前に処分をすべきではないかという判断をして理事長のほうに報告し、これは処分すべき内容であるということで指示をいただいたです。","id":"exchange-069"},{"speaker":"塚本委員","kind":"意見","question":"この件は５月９日に理事長が存在を知ったわけで、副理事長、事務局長から理事長に事実の報告があったわけですけれども、それを受けて、それからしばらくしてと思いますが、理事長が、そのことに関する認識というものを、どういうふうに示されたのか。","respondent":"濱野助役","answer":"報告いたしまして、こういうものについては処分をする必要があるということです。それはアンダーで売るということはできませんので、ある時期を見計らって、そういう時点を見計らって売れということで指示をもらったです。","id":"exchange-070"},{"speaker":"林（宏）委員","kind":"質問","question":"知らないですか。自治体はそれには引っかからないか尋ねました。","respondent":"中尾根企画部長","answer":"今の件については、はっきり商法の改正に基づいて一般の会社はそう見せなくちゃいけなくなるというふうには認識しております。今のところ、そのようにすぐ必要があるというふうには認識をしてございません。","id":"exchange-071"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、どういうふうに表記をするんでしょうね。もし、品川区がこういう凍結された財産、債券を持っていたとしたら、どういう表記をされるんか尋ねました。","respondent":"中尾根企画部長","answer":"このアルゼンチンの国債の部分については、市場性のない保有目的の債券ということに該当して、買ったときの価格をもって、そのまま計上していくということになるです。","id":"exchange-072"},{"speaker":"林（宏）委員","kind":"確認","question":"こういうＳ＆Ｐから半年前に出ていますよという情報をもとに安全性を確認したんだろうと思うんだけど、直近の情報ではないというのは確かですよね。億の金を動かすにはちょっと古過ぎるんじゃないのかなという、感想を持ちますが、調査のメンバーとしてはいかがか尋ねました。","respondent":"中尾根企画部長","answer":"実はこの５回のときにも、この今委員がご指摘になった２５ページ、この時点で第７回の応募債のときにもつけてきたということなんです。したがいまして、初めて半年前のここのところで知ったというわけではないというふうに理解しております。","id":"exchange-073"},{"speaker":"林（宏）委員","kind":"質問","question":"だって、アメリカの経済だって、１年を４等分してあるわけじゃないですか。６カ月前というのは今の世の中で言うと１０年一昔ならいいけども、後になってみての思いでしようがないんだけども、思いませんか。","respondent":"中尾根企画部長","answer":"ただ、これは購入のときにつけられていた証券会社からの資料でございまして、一つの確かに根拠にしていたんだろうというふうに思います。個人的な見解はありますけれども、一応資料としては、これがついているということにさせてください。","id":"exchange-074"},{"speaker":"林（宏）委員","kind":"質問","question":"じゃあ、個人的な見解だけは伝えておきます。公印の使い方というのは、失礼な言い方だけど、品川区ではできているんか尋ねました。","respondent":"太川総務課長","answer":"初めて押せるというものですので、区役所のほうにつきましては、公印の管理はきっちとできいるというふうに思います。","id":"exchange-075"},{"speaker":"林（宏）委員","kind":"意見","question":"その間違いのないという方法をなぜしなかった。それをなぜしなかったかということですとの意見を述べました。","respondent":"中尾根企画部長、濱野助役","answer":"なぜしなかったのかということですけれども、規程は、そういうふうにしなきゃならない、それから、財団内部でも、公金についての管理規程はある。そのことを実践しなかったということについては… これは先ほどご答弁申し上げましたように、要するに決定権者でない者が決定をして、それでそれに基づいて公印を使用しているということであります。そこのところの誤りだというふうに私は理解しております。","id":"exchange-076"},{"speaker":"林（宏）委員","kind":"意見","question":"今回も１億円の取り引きがその判こを押されたことによって遂行されていくわけですよね。と、なぜそれができなかったかとの意見を述べました。","respondent":"濱野助役","answer":"その決定原議がしかるべき決定権者によって決定されたものかということをチェックした上で押すべきだったということはおっしゃるとおりです。","id":"exchange-077"},{"speaker":"林（宏）委員","kind":"意見","question":"使用方法、あるいは管理まで入ってくると思うけど、それにも間違いがあったというふうに指摘せざるを得ない。そういうことが品川区の中ではないということを聞かされましたので、安心して一たん終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"宮崎委員","kind":"質問","question":"実際にどういうふうな係わりがあるのかというのはよくわからないんですが、そこのところはどういうふうな段取りでやられているのか。今理事長がなっちゃうんだけど、実際にはそうなっていなかったのかなというふうに思うんですけど、そこはどうなんか尋ねました。","respondent":"中尾根企画部長","answer":"実際はどうつくるのかということですから、原案については、事務局で１年間のその動きの部分をまとめてつくります。こういうことでよろしいかというふうに説明をし、評議員会および理事会に提出する、こういう具体的な事務手続です。","id":"exchange-079"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、この出された決算書というのは、やっぱり理事長が目を通していたということでいいわけか尋ねました。","respondent":"中尾根企画部長","answer":"そのとおりです。","id":"exchange-080"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、平成１２年度の決算については、国債とかアルゼンチン債、ここのところの記載というのは無理なんか尋ねました。","respondent":"中尾根企画部長","answer":"特別な説明でもない限り、これを見ただけでは、いわゆるこれは円貨建て外国債券だというふうに理事長も気がついてはございません。これをあわせて両方6,０００万円、説明を受けなければ、監査でなければわからなかったということの経過です。","id":"exchange-081"},{"speaker":"宮崎委員","kind":"意見","question":"そうすると、実際上は今のお話だと、事務局でつくったものをそのままうのみせざるを得ないというか、実際上はそうなっていたと。そうなると、じゃあ決算書に対しての委員長の責任というのは一体どうなっているのかとの意見を述べました。","respondent":"中尾根企画部長","answer":"このことを報告しました平成１４年２月１５日の事業団の理事会、自分自身で責任を考えていくというふうにお答えしたというふうに聞いてありますので、そういう責任は理事長として受けとめられているというふうに思っております。","id":"exchange-082"},{"speaker":"塚本委員","kind":"質問","question":"この事態がどういうことであるかということを初めてお聞きし、我々が、議会がどう認識していくのかがこれからの課題であります。なお、この事態に対しての議会意思の形成をお願いするというようなことでまとめていただければというふうに私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"三上委員","kind":"意見","question":"私どもも、今塚本委員が述べられことと同様に思います。２日間にわたって詳しく質疑をしてきましたが、いろいろ検討していっていただければということで、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、私は前副理事長、あとは実際にこういう決定をしたというところに判こを押しているもう一人の事務局長ですね、直接話を聞いてみたい。どういうふうなことを考えて、どういう認識だったのかというふうに思いますので、今後どこかで取り計らっていただければというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"北野委員","kind":"意見","question":"その間にどういうことが起きてくるかという、予算の集中審議の中でやるべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"田中委員","kind":"意見","question":"昨日資料要求がありました１点目の資料等も今後見させていただきながら、今後の取り扱いについては、先ほどの塚本委員と同様の扱いでいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"土井副委員長","kind":"確認","question":"仕事として、調査報告の詳細にわたってお聞きをし、さらにそれに加えて幾つかのことを確認ができたというふうに思っております。そして、あと、この質疑の内容等を議長に報告するというところの塚本委員の内容に賛同しておくという形でよろしいんではないかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"林（宏）委員","kind":"意見","question":"この佐藤工業（株）と同時に造園で東京都ならびに国から指名停止というか、しようというか、されている業者があるよね。そこも品川区の係わりを持っているところがあると思うんだけど、何社で、どのぐらい、どういうような状況になっていますかとの意見を述べました。","respondent":"西島経理課長","answer":"やはり２業者ほどありまして、その分につきましては、国のほうでやっぱり営業停止の処分をした。これもほぼ今日が４日ですので、ちょっと２、３日ずれていましたので、今週中には多分解除になるというふうにたしか記憶しております。","id":"exchange-089"},{"speaker":"林（宏）委員","kind":"質問","question":"区として、主体的にしておくということはしないんですか。それの対応というか、考えていらっしゃるんか尋ねました。","respondent":"西島経理課長","answer":"佐藤工業（株）としては継続をしたいですので、その２工事は何とか間に合うのかなという、感想は持っております。その３工事につきましては、その辺をどうするかというのは、これから主管ともう一度詰め直さなければいけないなと。","id":"exchange-090"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"年度末でもあるし、情報をさっきの話じゃないけど、的確に早くいただきたいなというふうに思います。正式な委員会が開かれているわけですから、非常に影響の大きいところですから、ぜひそれはお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201900?Template=document&Id=1574#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":60897,"voices":243}},{"id":"h14-20020306-13","meetingId":"h14-cm03","date":"2002年3月6日","dateIso":"2002-03-06","committee":"清掃・リサイクル特別委員会","time":"午前１０時１６分～午後１２時００分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"学校、これは区の事業でやっているところですから、出てくる量も一定程度まとまってごっそり出るわけですからやりやすいというところで実施すると。ですから、だから、できるだけ地域を限定してでも継続をするというふうにしていただきたいと強くお願いしたいと思うんです。","respondent":"中山清掃リサイクル課長","answer":"これはこのままの使用はやはり行政としては問題があるという認識なんですけれども、最近、こういった市場も徐々に出始めている。そういう中で、合理的なものというふうになった段階での実施というものを考えるべく、区民の方にも情報を還元していきたいと考えております。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"それはそれとして伺いたいんですけれども、しかし一たんは切れちゃうわけですから、やっぱり模索していただきたいというふうに思うわけです。ですから、そこのところについてもう一遍ご答弁をお願いします。","respondent":"中山清掃リサイクル課長","answer":"連携というご質問でございましたけれども、こういった市場に参入しようとするような事業者も含めて見える形で情報をある種のオープンにしていく。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここのコスト面の部分でちょっとお聞きしたいんですけれども、平成１２年度と平成１３年度のコストの差が随分ありますよね。現在やっているのは直営方式と委託というものがどういうふうになっているのかというのをちょっと教えていただきたいのと、例えば集合住宅のほうだと。","respondent":"中山清掃リサイクル課長","answer":"ちょっとその下りの説明もわかりにくかったかなというふうに思いますが、１ｋｇ当たり約５９円、条例において上限額を定めております。こういう説明をちょっと簡略に書いてしまったんでわかりにくかったと思います。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それをいろいろなところを見ながら、拡大できるところを少しずつ拡大していくというふうなことで、ぜひご検討いただけないかなというふうに思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中島委員","kind":"質問","question":"さっきちょっと聞き漏らしたところが、モデル事業をこれまでやってきた特別な予算がとれていたと思うんですが、どのぐらいか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"各年度約２５０万円ずつですので、両年度で５００万円余というのが総経費です。","id":"exchange-005"},{"speaker":"中島委員","kind":"質問","question":"戸別のところが夏場、秋口ですか、行われて、確かに私もこれを読んでいて、自分が夏場、モデル事業の地域にあったらどうしたかなと。それとともに、予算も今後はないということで伺っております。","respondent":"中山清掃リサイクル課長","answer":"今は基本的には市場に流れておりますが、サンプルとして学校のほうに一定の袋を戻しまして、教材として活用していただくという取り組みはしています。","id":"exchange-006"},{"speaker":"中島委員","kind":"意見","question":"そういう再資源化をしている、これまでの指導とあわせてやっていくということで、かなり区民には普及できるんじゃないかなと私は思うんです。一時、それにかわるアピールをしていくという方向で進んでいくほうがいいんじゃないかなという意見を申し上げておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"土井委員","kind":"提案","question":"ですから、発酵させていくことこそが、これから継続してやるべきまず最初のことだろうと思えます。建設なのかわかりませんけれども、そういう提案にまで結びつけていけるようにしなければいけないんじゃないかというふうに思ったのが１つですとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"そういった意味では、門前払いでは話にならないからというところで選定したところの地域に説明に入ったということが１つあります。やはり、協力できない中では、ちょっと勘弁してほしいという声が多かったということが今回出てまいりました。","id":"exchange-008"},{"speaker":"土井委員","kind":"質問・要望","question":"もう１回そこをお伺いしたいと思っているんですが、協力していただける方はもう意識もかなり高くて、大体大丈夫なはずなんですよ。インターネット等々でお知らせするというのも１つですけれども、これからも継続すべきはまずそれだなと私は思いますので、進めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須藤委員","kind":"質問・要望","question":"何点かお伺いいたします。その辺のところをちょっとお聞かせほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"実施をいろいろやっていく中では、あるいは行政だけでなくて、今後こういったケースがある場合についての名称は考えてまいりたいと思います。","id":"exchange-010"},{"speaker":"須藤委員","kind":"質問","question":"ですから、今後の対応ということで、私自身はこの再資源化についての考え方は、いろいろな方向性があるので、これだけ１つ実験をしたと思うんですよ。いろいろと今つくられてきた時期ですから、当面、この点については実施しないという方向性で私自身は結構だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"北野委員","kind":"質問","question":"世帯数としては６７件ですか、違いがあるのが、平成１２年度は学校が含まれているからこの量になるということなんでしょうか。世帯数だけでは、この違いというのはないと思うので、ちょっとお伺いしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"委員がおっしゃるとおりです。８ｔ分は４小学校から出ているものですから、この２集合住宅からの排出量という形になりますから、また単価の値も変わってくるということはあります。","id":"exchange-012"},{"speaker":"北野委員","kind":"質問・要望","question":"学校が入ることによって、やっぱりそういうところでも整理していただきたいなというのがあります。平成１３年度の場合、この間見てきたときと比較してとかありましたけれども、何か肥料化にいかない理由ってあるんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"家庭から出してくるものについて、水分が多いとコンポスト化量の割合が違うと。異物の混入もおおむね問題ないというくくりで説明いたしましたけれども、そういう状況もありますので、そういった違いもあろうかと思います。","id":"exchange-013"},{"speaker":"北野委員","kind":"質問・要望","question":"どうもありがとうございました。やっぱり私たちが生ごみを減らすときの選択肢というんですか、そういう多様性があるような生ごみの減量にぜひ打ち込んでいただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問・要望","question":"それから、１点、コストのところで確認なんですけれども、総価契約という、これはどういうことなのか、契約の方法なんですか。１３年度で２５０万円、合計５００万円ですか、その５００万円という費用をかけて雇用の創出という点ではどういう効果があったのかということです。","respondent":"中山清掃リサイクル課長","answer":"そもそも１ｋｇ当たり幾らという単価で契約するのが通常でございまして、量が多くても少なくても、この額でお願いするという形をとったものです。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問","question":"それは、何でそういうふうにしたんですか。何か根拠があってやっておられるんだったらいいけど、なぜ通常のやり方でなくて、今回このように。","respondent":"中山清掃リサイクル課長","answer":"どれだけのエリアでやるかということを考える以前に、まず２カ年でやっていこうというのが実はあったものですから、逆に言えばこの枠の中でどこまでいけるかというのを見込んで声をかけて決めていったということです。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"１点だけ。ないか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"全保育園３７園と、小中学校のうち機械式のコンポスト機を置いていない学校で実施をしておりますから、機械式もしくは今回の回収型のもので、すべての小中学校及び保育園で生ごみの堆肥化が行われているということです。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"意見","question":"機械式を設置している学校というのはどのくらいと、その辺で問題を抱えてないのかどうかとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"３３校で今回回収しておりますので、２５校の学校に機械式生ごみ処理機を設置しているです。回収についても、これはいわゆる学校給食の素材を運び込む車で搬入の返しの車で農家のほうに戻しているという形になっております。","id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"済みません、先ほどのバイオガス等についてなんですが、研究段階なのか、よくわからないので、どの程度のレベルまで研究が進んできているんですか。あるいは実践がどこにどういうふうにあるのかをちょっと伺って、将来の課題というのはどのくらいの先を見ていらっしゃるのか、お聞きします。","respondent":"中山清掃リサイクル課長","answer":"関西のほうで神戸市、京都市のほうで実験プラントを設置して行っておりますが、それは環境省も補助を行いながらやっているプラントです。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"そうすると、しかし、コストの面からも実施の状況がどの程度のものなのかということをちょっと見きわめておく必要があると思うんですよね。どういうふうなルートで回収されて、そのプラントならプラントの規模にもよるんでしょうけれども、もう少し詳細に説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"実験段階ということですから、収集の関係で言うと、家庭系のものを別途収集してやっている例というのはほとんどないように聞いております。日によっては発電できない、処理だけはできる、こんなふうなときもあるというふうに聞いています。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"このことにシフトをしていくとなかなか生ごみの再資源化というのはちょっと見通しとしては期待が薄いんじゃないかなという印象を私は今持つんです。ですから、ぜひそのことを進めてほしいと求めましたし、その辺は委員長に改めてお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の現在のところと比較してどうなのかというところの評価を教えていただきたいのと、やっぱりここのところが上回るという表現が１カ所ありますよね。ここのところで、低公害車の導入拡大を進めていくこと、その辺もわかる範囲でこの２点のところを教えていただけたらなと。","respondent":"金井環境課長","answer":"その中にはそういう比較の部分も一部入っておりますが、このアセスの考え方はそういう考え方ですので、そんなような形で表には結論として出ています。そういうことでご理解をお願いいたします。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"この案についての発言ということの関係なんですけれども、扱いというのは、これはもう出した意見についての扱い方なんですけれども、この案に盛り込まれるということが可能というふうに受けとめて発言していいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"南委員","kind":"確認","question":"ちょっと改めて確認をさせていただいたんですが、受益者負担については、具体的にメモが上がっているのは２つの会派ぐらいだと思うんです。そういうことですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"土井委員","kind":"質問","question":"こちらの資料は一緒に添付をされる資料ですか。それともここで配付をされるということで、ここに集約されたからということなんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"北野委員","kind":"意見","question":"２番のごみ減量・リサイクルに関することで今後の課題ということでは、私は事業者責任という考えとしてちょっと出させていただいたんです。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"須藤委員","kind":"質問","question":"私ども、この中で、この前話したときには、２３区の清掃一部事務組合に関しても話した。土井委員が言ったように大要はこれで了としているわけですから、事業者責任を含めた区民の意識啓蒙としたほうが、その辺のところはいかがか尋ねました。","respondent":"高木委員長","answer":"ちょっと日にちは認識しておらないんですが、いろいろご意見をいただくと、そういうようなことも考慮しなければならない。骨格に変更を加えるというようなことではなくて、これはご相談はお受けしなければならんと考えていますけれども、特段の……。","id":"exchange-027"},{"speaker":"土井委員","kind":"質問","question":"かつまた、副委員長もいらっしゃる。そういう中ですから、委員会の中でのこれまでの議論も含めた信頼性に欠けることにもなりかねませんので、ぜひそれでお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"堺委員","kind":"質問・要望","question":"削除してほしいとか、訂正してほしいとか、どうしても要望として出てしまうと思うんです。ですから、６つの会派がすべて納得して片づく形というのは、皆さんにご了解をいただいたらどうかなという気がいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、ちょっとしたてにをはとか、その辺のところの意図がストレートに入れてもらえれば。まるっきり受け取り方が違っちゃうと思うので、そんなこともちょっと要望させていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"須藤委員","kind":"質問","question":"ですから、正副でおやりになるというから、それじゃ結構ですという話で終わったんです。ここで今言った、そんなに大要は直さないよということを今前提にしているんですから、あとはまた正副にお任せしますということでいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"南委員","kind":"確認","question":"てにをは１つで意味が全然違っちゃうわけですから、じゃ、この程度だったらみんな了解できるということで確認して直していただくというふうに進めて。ですから、ここで３点になるのか、２点になるのか、その程度のところを確認していただいて、訂正をしていただければいいかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"この部分に関しては、この辺ある程度まとめさせていただきたいと、変更はしたいと私は思っております。ですから、そういう形を諮らせていただきたいと思うんですが、どうか尋ねました。","respondent":"高木委員長","answer":"〔「なし」と呼ぶ者あり〕 なければ、全委員のご意向にかなうような報告書をつくってまいりたいと思いますので、ご一任を賜りたいと思います。しかる後に議長に提出してまいりたいと思います。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=5658#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":31829,"voices":80}},{"id":"h14-20020306-14","meetingId":"h14-cm03","date":"2002年3月6日","dateIso":"2002-03-06","committee":"行財政改革特別委員会","time":"午前１０時０５分～午後０時３５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鶴委員","kind":"質問","question":"やっぱりね、一つは予算枠内ですから、やっぱり活用というのが積極性を持っているというふうに私は思うんですよ。さっきちょっと気になって、昔から私も気にはなっていたんですが。","respondent":"市岡企画財政課長","answer":"この流用という言葉自身は自治法とか自治法の施行規則で科目相互に流用、用立てては、項の間は議決科目ですから項間の流用はいけない。こういう流用という言葉自身が法令で使われておりまして、どうしてもそれに引っ張られておりますが、いろいろな説明の中では例えば。","id":"exchange-001"},{"speaker":"鶴委員","kind":"質問","question":"中、これはいいというふうに思ってきた事業であったとしても、もっと別な角度から見ればこれはやっぱり反省すべきだったというかね。一層進めやすくなったと、こういうふうに私は思っているんですが、どういうお考えか尋ねました。","respondent":"市岡企画財政課長","answer":"こういうものと、それから、それはやはり違うだろうと思うんです。で、これは一朝一夕にできることではありませんけれども、少しずつそういう芽が私どもにも各事業部にも感じられるようになったというふうに思います。","id":"exchange-002"},{"speaker":"鶴委員","kind":"質問","question":"そういうものが大変なことだろうというふうに思うけれども、何かお考えですか。こうしたらわかってもらえるっていう、その努力が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鶴委員","kind":"質問","question":"それを例えば、ある政党は結局直営にすべきだということだけで賛成ができないという人もいるわけですよ。せっかくの努力というものが生かされないということは極めて残念なことだから、お伺いをさせていただいたのはそういう経緯でございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問・要望","question":"今まで特に、よく批判されがちだった縦と横の連携がないというような区民からのたくさんの要望がありましたですよね。抵抗が出るというんですか、その辺のならないという一つの思いとか決意とかその辺がありましたらお願いします。","respondent":"市岡企画財政課長","answer":"政策経費についてはやはりトップも含めてしっかり政策形成をして、区としての政策方針の中で決めていく。そのときの区民の方の税に対するお考え、意識というものをきちんと反映させるような予算編成をしていきたいと考えています。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問","question":"だから、予算の執行のあり方としてもう少し基本線というんでしょうか、それをきちっと確立すべきではないかというふうに思いました。職員のやる気とか自発性とか自主性というのは組織ですから動いているわけですね。","respondent":"市岡企画財政課長、中尾根企画部長","answer":"それから、ちょっと私の説明も不適切だったかもしれませんが、これはやはり不用額として戻すということが財政運営の原則であろうと考えています。こういう意味では… そういう報告を受けてみたりというようなことで、前よりかは職員一人一人のそういう動き、そういうものにやっぱり気を自然と使うようになった。","id":"exchange-006"},{"speaker":"桜井委員","kind":"質問・要望","question":"だから、そういう点ではもう一回、区民にとってどうなのかというところを総点検いただきたいと、これは要望にとどめておきます。もう一方ではこういう区民生活の厳しい側面も抱えているわけですから、そういう部分だから地方自治体としては何かが問われる部分だと思うんです。","respondent":"古川人事課長、中尾根企画部長","answer":"もちろん一人一人の職員がそのことをどう考えているのか、これはまたさまざまな機会でこれからも検証していきたいと考えています。自分を知る人がかなり離れたところにいるのか、より近くにいるのか、それをどう受けとめるか… そういう生活と同じことを考え、実践しなければ区民の方は信頼されないということです。そのことの限度を持ってやるということが、私たちが大きいパイプをつくれる、よりいい区政ができる、このように考えているところです。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問","question":"まだまだ義務という部分ですから、当然都との連携なんかいろいろとあるんだと思うんですけれども、やはりまだコストを下げていく必要がある。けども、その辺の考え方というか、まだ問題点はまだ残っているというような部分でいいんですかね。","respondent":"市岡企画財政課長","answer":"本当にまだ予算編成も新しい体制で１回しか行っておりませんし、これからまさに予算委員会のご審議でいろいろご説明申し上げるところですので。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"多くの課題が残ると思いますが、ぜひよろしくお願いします。適材適所の配置がとれるようになったですとか、そういった方もやはり人事異動についてその辺の考え方というのを改めて教えてほしいと求めました。","respondent":"古川人事課長","answer":"この係長は別ですが、基本的には各部長に部内での一定の人の配置についての考え方をまず求めまして、それを人事部のほうで全体の調整を図ります。一定のローテーションは当然ありますが、そういう点をこれからはより深めていきたいと、こう考えております。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問・要望","question":"１点だけ、確認だけさせていただきたいんですけれども、どんな方向に考えているんですか。それだけちょっとお聞きしたいんですが。","respondent":"市岡企画財政課長、古川人事課長","answer":"単純なスリム化ではありませんが、ものもお金も投入をして、これを不断に続けていくということが大事だろうと思います。そういう意味では、スリム化は今後も行ってまいります。 そのドアをびっちり締めまして、その中で職員はもううちの職員だと、１年間はですね。流動化を進めていく、それを少しでも外すことがこれで可能になる、こういうふうに考えております。","id":"exchange-010"},{"speaker":"嶋委員","kind":"質問・要望","question":"先ほどの区民へのわかりやすさということでお聞きをしたいんですけれども、確認をしてこなかったことなので、現状を教えていただきたいんですが。","respondent":"中尾根企画部長","answer":"ものすごい、基礎がある人はすばらしいものをつくります。区民から聞かれたらそういうことでやっているから、だめなものはだめというふうに言っていただければと思います。","id":"exchange-011"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう意味では楽しみにしていきたいと思いますけれども、やはり字の大きさと字体というのがある程度統一されると、大変区民は見やすいのかなと。区民側からすると字体とか、そこら辺もまた考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"でちょっと質問なんですが、成長していく上では、分散と集中というのを交互に繰り返していくものだと思うんです。そのよさ、逆に今までできていたことが事業部制移行によってできづらくなってしまったなんていうことがあるのかどうか、その辺の考え方は……。","respondent":"市岡企画財政課長","answer":"やはり小数のすぐれたリーダーで対応するのがいいのか、いわばアメーバ的に即時的に柔軟に対応していったほうが新しい政策課題に対応できるのか。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"まだこれからのことなので具体的なことはないかもしれませんが、ここにない、さらなる成果としてどういうことを期待していくのか。もし現段階でありましたら。","respondent":"市岡企画財政課長","answer":"ここにあるのは本当に成果だろうかというところは確かに説明しながらちょっと自分でも疑問を持っております。それがやはり大切だろうと思います。","id":"exchange-014"},{"speaker":"田中委員","kind":"意見","question":"そういう意味で、事業部制をスタートしたことによる成果としてはすごいものがあると思うんですが、まだまだこういった成果を上げる要素というのはたくさんあると思いますので、競い合い等々を含めましてあると思いますので、ぜひさらなるご活躍を期待しておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"金高委員","kind":"質問","question":"１番の住民参加ということでありますけれども、行政がいわゆる選定するというんですか、参加という言葉が果たしてどうかなという感じがいたします。事務事業評価そのもについてはやはり内部のことで、そういう面ではこの全体の１番から６番までの状況で、私はいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"佐藤委員","kind":"質問","question":"私から言わせてもらえば、本当に極端なとらえ方であって、果たしてあれが会派の統一した見解で一般質問をなされておったのかどうなのか。僕はこの１から４、もし必要ならばほかにいろいろな機会がありますから、駅頭ででもひとつご主張なされたほうがいいかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"松澤委員","kind":"質問","question":"この行財政改革の指針となるように、行革という思いの中でまとめてきているものですから、それに沿うような形のものをまとめたいと思います。ですから、単独意見、私たち自民党の施策、考え方とまるっきり相反することもあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鶴委員","kind":"質問・要望","question":"適正な受益者負担を求めることに対しては、重大な、理解してもらえるものではないのではないかという気持ちを私は強く持っています。この予算の４番目のことについては、そういう形であえてまとめなくてもいいのではないか、こういうふうに私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"桜井委員","kind":"質問・要望","question":"単独会派というほうがいいか、小数意見という形でいいのか、それは尊重していただきたいというふうにまず要望しておきます。これは鶴委員が言われたのは当然だというふうにおっしゃられているわけですから、この１から６の前段のところに、例えば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"田中委員","kind":"意見","question":"各会派からまとめられた６項目はそれぞれ十分まとめられていると思うんですが、あえて３番目の議会との関係についての部分の「この際」以下のところの「前年度の評価を参考にするために並列に表示するなど」という部分で、その辺のニュアンスを少しご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、単年度、むしろ、ここではなくて、２番目ぐらいに入ってくるのか、ＰＤＣＡを回す中で単年度の成果及び経年、通年度に、ちょっと言葉が出ませんが、経年的な成果も見えるような評価の仕組みを採用していただきたいというふうに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"松澤委員","kind":"意見","question":"この資料そのものが区民に出るわけじゃないから。議会に対する……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"塚本委員長","kind":"質問","question":"その主張にあえて私も思います。単独会派の意見の扱いをどうするかということがありますので、もとのところを確定するという作業を先にしたいと思うんですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鶴委員","kind":"提案","question":"桜井さんからお話がありました件についてですけれども、Ａ３のほうの３の議会との関係においてというところで、４行目がありますね。前回の資料を全然見ていなかったものですから、後で最初に委員長の提案がありましたし、私はそういうふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"鶴委員","kind":"意見","question":"それで４行目のところです。こういうふうにしたらどうだろうかというのが私の意見でありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"辻副委員長","kind":"質問・要望","question":"将来の満足度、区民が公表されたことについて意見を求められた、単独会派で言う住民参加という形になっていくと思うんです。外部評価のほうで公募区民というのはこういう形で二本立てで動いているわけですから、ああ思うとか、Ａであるべきじゃないかという意見はぼんぼん。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"辻副委員長","kind":"質問","question":"そうじゃなくって、言っちゃうと、ここで住民のどうのこうのってサービスどうの向上とかってあるじゃないですか、評価基準て。それを入れれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"松澤委員","kind":"質問・要望","question":"事前に議会に説明を求めたいということは、これは内部的な予算の問題を事前に議会に説明されたいというようなことですね。私、それを、これそのものの考え方を変えていただかないと文言だけで前に入れるということにはならないんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"鶴委員","kind":"提案","question":"いずれにしても、予算が決まる前に当然プレス発表の前にも各党に説明があるじゃないですか。そういう意味で、その成果については予算上の増減を含めて数値を用いて議会に報告されたいと、こういうふうにしたらどうかということがご提案でしたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"３番に対してはこのままでいいと思うんですが、２番の中の循環経緯という言葉にある種集約されているのかなという、もし集約されているのであれば先ほどの要望は取り下げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"桜井委員","kind":"質問","question":"そういう評価してすぐ予算というその期限というんですか。入れていただければそれはそれで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"辻副委員長","kind":"質問・要望","question":"Ａだ、Ｂだ、どうだとそれで予算編成が動き出すわけです。自分たちで各会派でどう評価するかというのを区長部局、まさしく決算委員会の場でがんがんやって、あるいは予算編成に対する予算要望として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"鶴委員","kind":"意見","question":"もしその各会派の見解ということであれば、何も修正も加えなくてまとめなくて、各会派からこんな意見が出ましたと。今のまとまった段階でとても残念なことだとは思いますけれども、別にこのご意見を切り捨てるということではなくて、採用されなかったということでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"塚本委員長","kind":"意見","question":"ご意見、わかりました。かなり主張の強いところですので、できれば残していきたいなというのが委員長としての願いですけれども、ご理解いただけましょうかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"松澤委員","kind":"意見","question":"鶴委員が言われましたように、答申案というのはある程度小数意見を尊重する形が必要だと思っているんですけれども、特にこういう形での集約の場合には、本当に小数意見というよりは一つの対立する意見、反対意見になってしまっていますので私は要らないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"桜井委員","kind":"質問・要望","question":"あくまで区民サービスと事務効率の向上を求めるものなので、そういうふうなもし表現がどこかに入れば、この１についてはいいのかなと思います。できればかなり縮小してもうちょっとまとめて評価基準とバランスシートのところだけで小数意見と言っていただければありがたいと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"鶴委員","kind":"質問","question":"その住民の意見とか住民の目に、住民の耳になって私たちが行政なら行政、あるいは政治というものを見つめてまずいところはまずいじゃないですかって。住民を無視して政治はないわけですから、どういう形で住民評価に参加してもらうかという、ちょっと言葉は大事だけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"桜井委員","kind":"意見","question":"できればそれはその他の意見とか、小数意見という形で６、７のところでまとめていただければいいのかなと。だから、１の住民参加については、そういう点では削除することは構いませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"松澤委員","kind":"質問・要望","question":"特に単独会派の３番、そぐわないのでやめるべきだとはっきり言っていくということと、施策はコスト論ではなく区民要求の必要性を重視されたい。それぞれ答申として出す場合にはこれが小数意見があったのでと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"桜井委員","kind":"意見","question":"もう長年、１０年ぐらいやってるから。例えば、１について、評価指標について、ここでその他の意見とか小数意見とか、各項目ごとに……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"辻副委員長","kind":"質問・要望","question":"ですから、私は小数意見というのはこの１の中で、なおこの評価指標についてはこういう意見があったというのを入る。ないとバランスシートをもう一回各会派に対して意見を求めていると、自治体の会計評価にそぐわないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"鶴委員","kind":"質問","question":"ご相談なさったみたいですから、意見を開陳を願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"鶴委員","kind":"提案","question":"心配なことはそう言いながらどんどん負担がふえていくんじゃないかということをこの提案者は心配なさっているところだろうと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"桜井委員","kind":"意見","question":"評価指標についてのところに、２の評価基準についてとタイトルは別に評価基準にこだわりませんから、内容的にはそれでいいと思います。２番目の、４行ぐらいにまとめるということについては結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"辻副委員長","kind":"意見","question":"８階にあるんだけれども、あこそはもちろんセキュリティーがかかっているから、きちっとした形で。庁内ＬＡＮがどういうふうに進んでどうなっているかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"桜井委員","kind":"質問","question":"第三セクターの交付金の使い方というんでしょうか、具体的には四つかな、それぞれ各団体が独自に要綱を持ったわけです。ただ、短い２回のところでできるかどうかというのはちょっと微妙ですけれども。","respondent":"塚本委員長","answer":"やはり特命をいただかないとなかなか調査できないんだろうと思います。よろしゅうありますか。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/373656?Template=document&Id=5702#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":41312,"voices":111}},{"id":"h14-20020306-16","meetingId":"h14-cm03","date":"2002年3月6日","dateIso":"2002-03-06","committee":"街づくり特別委員会","time":"午前１０時０９分～午前１１時３４分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"川西委員","kind":"質問","question":"区への提言の中で、事業導入についての(1)３地区以外の地域であっても、これはどのような形で今後進めるのか聞いておきたいと思います。それから、２番目は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"川西委員","kind":"質問","question":"それから、３ページ(11)３地区の事業の進捗率は低く、期限の延期など国や都に対して必要な措置を講ずるよう、期限の延期は私はよくわかるんです。１０年をもう切れるところが出てきてますから、必要な措置というのはどういうことが考えられるのか伺っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"築舘委員","kind":"質問・要望","question":"国、都に対して要望する。ですから、これは(3)のほうにまとめちゃっていいのではないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"本田委員","kind":"質問","question":"もともと各会派から出されたものをそれぞれ仕分けをして羅列をしたということですから。だから、これをどういうふうに扱うかということによって違ってくるんですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問","question":"これは過日各会派が提出していただいたものをそれなりにまとめられてここに来ているわけですから、今言われるような部分がたくさんあると思うんです。ですから、これで今度はいいのか悪いのかという１項目ずつ整理していく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"横山委員","kind":"質問","question":"(9)の避難路を確保するために、ある程度あそこだなとわかるけれども、これを一般の人が読んだらどうだろうかな。要するに避難路というのは今建築基準法の中でしかるべき道路がなければ建たないわけですから、ちょっと整理する必要があるのかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"藤田委員","kind":"質問","question":"これを１本ずつやっていますとあと２回の委員会で果たしてできるのかどうかと思うのですけれども、ですから本田委員がおっしゃるように。いろいろな機会を通じて区は区で東京都、国に対して働きかけをしているわけですから、我々委員として区に１年間のまとめとして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"石田委員","kind":"意見","question":"それとも東京都にこういう形のものが我々その場に委員会として例出をしてそのほうが逆に今度部課長会とか東京都に提言をしていく中で効果があるのか。品川のまちづくりにとっては少しでも早く進む道であるならば、そっちをしたほうがいいと思うんですがとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"宮崎委員","kind":"意見","question":"そういう意味では、この中身をどういうふうにまとめていくかというのがかぎになってくるのではないかと思うんです。そんな感じがしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"川西委員","kind":"質問・要望","question":"２５平米になって、（「これはそういう意味で言っているんじゃないんです」と呼ぶ者あり）そうですか、違うの。ですから、生かしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"本間委員","kind":"質問","question":"とにかくこのまちづくりについては、あくまでも民間が主体というふうな部分で私たちがどこまで何ができるかというものが出てまいろうかと思います。大変な努力をしながら頑張っていらっしゃるお話も地域の皆さんとの接触の中でお伺いをしておりますので、同様な意見として受けとめています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田委員","kind":"確認","question":"ちょっと委員長の言ったことでご確認をしたいのですが、その密集市街地に有効な手段をどうやってかけていこうという形であれば、このその他についても非常に有効な政策的な手段はたくさんあると思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"石田委員","kind":"意見","question":"理事の方はどう思っていらっしゃるか。例えばそういうものがもしプラスになるのであれば、どういうことを提言していただければ我々も力強いとかいろいろなことがあるかもしれないしとの意見を述べました。","respondent":"沢田委員長、山室住宅指導担当部長","answer":"きのう正副でも、ある程度我々が出してもやはり行政の方が一番よく知っているわけですね、制度の流れ、法の流れ、財政の流れ。ここらで少しまとめ方でどういうまとめがいいのか住宅指導担当部長さんのほうからでも少し発言いただけると… ご案内のとおり、国のほうも都市再生の関係で今いろいろな取り組みをしておりますし、そういったこととのすり合わせも少ししていく必要があるかな。すみません、ちょっとまだ足りませんか。","id":"exchange-013"},{"speaker":"横山委員","kind":"質問","question":"ですから、それについて私は精査して全部一つずつやったら、ほとんどそのままでいいんですよ。ただ、そこら辺のところをやはり委員会としてのまとめだから、ちゃんとした合意のもとにやるべきじゃないのかなと私はさっきからそう思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"横山委員","kind":"質問","question":"２ページの６番、７番の街づくり協議会については(1)、(2)、(3)に分けることはない。ですから、そういうまとめ方を私はされるべきだと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"藤田委員","kind":"質問","question":"ですから、ちょっと重なっている部分もありますし、できるだけ整理をしていただく。相手があることなので、住民がその気になってもらわないと、そうした中でこうした意見がありましたということでまとめてみてはどうかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"意見","question":"一致するところ、しないところというのを出してみて、そういう意見を出し合ったりする色分けをやったらいいのかという気がするんです。そこら辺のところで意見があったら出していただければなというふうにやっていけば、これから進むような気もするんですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"石田委員","kind":"意見","question":"ほかの都心共同を採用してほしいとか、それは一つの制度上の中にこういうこともあって、密集市街地をやっていく。必ずこう言っている意味のこの部分はどういう意味合いって、その中でここにも１回提言しているわけだから、この委員会としてまとまるのではないかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう課題の申し送り事項的な部分でそういったことも含めて検討をお願いしたいというような形にせざるを得ないのかもわからないという時期ではな…そのあたりをきちっとしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"本田委員","kind":"質問","question":"ですから、国とまとめていただいているわけですが、執行機関に取り組んでいただくというのが限られた時間の中では相当だと思うんですね。そういう意見を持っている方々は、またその意見は述べればいいわけで、述べる機会はいろいろなところであるわけですからやっていただく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"石田委員","kind":"質問","question":"個々のことを言っていいということですか、今は。出てくる前に、今ここで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"石田委員","kind":"意見","question":"そういうこともできないので、ある程度の合意のもとという形の努力はいいけれども、全権利者というのは。その他の地区計画についているけれども、そういう個々のことを言っていいというなら、ここで今そういう形の個々のことを言わせていただくけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"その中で密集住宅市街地に絞ってこの１年やってきたわけですから、ほかの部分は全然ケアできていないんですよね。一部取り上げて１年やってきただけの問題で、ほかのものは全部積み残しですから、そういったものを見たときには私は終わっていないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"三上委員","kind":"質問","question":"そういった点で、どうも交通に手が出せないというのは、私はちょっとまちづくりにとって弱いかなという感じがあるんですけれどもね。この委員会にちょっとプラスでもしていただいて、交通という問題も入れてもらえればということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"本田委員","kind":"意見","question":"それからさらに一歩古い段階の都市再生東京のあり方の問題での協議もありますので、もっと関連を深めていく必要があるだろうというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"本間委員","kind":"意見","question":"私も引き続き存続していく必要があると思います。特別委員会のあり方として引き続き、ある程度できましたが、街づくり委員会を引き続き受け継いでいくようにしていったらいいかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"宮崎委員","kind":"意見","question":"１年やって、ようやく密集市外地のところで何らかのまとめができそうだなというふうな段階なので、やるべきことはされるというふうに感じております。動きによっては密集市街地の今後の問題も引き続いてやらなければいけない必要も出てくるかもしれないというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/690912?Template=document&Id=6226#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":21453,"voices":67}}]);
